async function fixCurrentAuditIssues() {
  const stats = {
    updated: false,
    componentSetId: null,
    urlNodeId: null,
    warnings: [],
    operations: [],
  };
  const operations = [
    { componentName: "Separator", update: updateSeparatorComponent },
    { componentName: "Slider", update: updateSliderComponent },
    { componentName: "NavigationItem", update: updateNavigationItemComponent },
    { componentName: "Navbar", update: updateNavbarComponent },
    { componentName: "Sidebar", update: updateSidebarComponent },
    { componentName: "Dialog", update: updateDialogComponent },
    { componentName: "BottomSheet", update: updateBottomSheetComponent },
  ];

  for (const operation of operations) {
    let result = null;
    try {
      result = await operation.update();
    } catch (error) {
      const message = `${operation.componentName}: update failed (${messageFor(error)}).`;
      stats.warnings.push(message);
      stats.operations.push({
        componentName: operation.componentName,
        failed: true,
        message,
      });
      continue;
    }

    mergeAuditIssueFixResult(stats, operation.componentName, result);
  }

  // Sweep the whole page, not just the components above. The seam-level sweep
  // in the shared build and update helpers keeps new drift out, but 61 of the
  // 87 property configurators are called from bespoke update functions that
  // never touch those helpers — MultiSelect and ColorPicker among them — so
  // anything already carrying a dead property would sit there until someone
  // happened to rebuild it. Figma refuses to publish a set with an unused
  // property, so leaving them is not cosmetic.
  const sweptPage = await ensurePage("Components");
  await figma.setCurrentPageAsync(sweptPage);
  await sweptPage.loadAsync();
  // collectComponentSetsInPage, not page.children: the Components page holds 15
  // SECTION nodes and not one component set at the top level, so iterating the
  // direct children swept nothing at all. NavigationItem cleared on the first
  // run only because it is in the operations list above and its update reaches
  // the seam sweep; Drawer is not in that list, which is why it survived.
  let propertiesUnbound = 0;
  for (const componentSet of collectComponentSetsInPage(sweptPage)) {
    propertiesUnbound += reportUnboundComponentProperties(componentSet, stats);
  }

  // The counts are in the message on purpose. Two attempts at this sweep looked
  // identical from outside — one sweeping nothing, one finding nothing — and a
  // silent no-op is indistinguishable from success. "sweep v2" also proves which
  // build of code.js Figma actually loaded; if the message lacks it, the plugin
  // is running a stale copy and nothing below it can be trusted.
  stats.unboundSweepReport =
    `unbound properties: ${stats.unboundSweepSetsScanned || 0} set(s) scanned, ` +
    `${stats.unboundSweepCandidates || 0} non-variant propert(y|ies) examined, ` +
    `${stats.unboundSweepUnreferenced || 0} unreferenced, ` +
    `${propertiesUnbound} unbound, ` +
    `${stats.unboundSweepReadErrors || 0} unreadable set(s).`;
  stats.warnings.push(stats.unboundSweepReport);

  const refreshed = stats.operations
    .filter((operation) => operation.changed)
    .map((operation) => operation.componentName);
  if (refreshed.length > 0) {
    stats.updated = true;
    stats.message =
      `Refreshed ${refreshed.join(", ")}.` +
      (propertiesUnbound > 0
        ? ` ${propertiesUnbound} unbound component propert${propertiesUnbound === 1 ? "y" : "ies"} reported; each needs attaching to a layer before its set will publish.`
        : "") +
      " Run Audit Again to confirm the live file state.";
  } else if (propertiesUnbound > 0) {
    stats.message = `${propertiesUnbound} unbound component propert${propertiesUnbound === 1 ? "y" : "ies"} reported; each needs attaching to a layer before its set will publish.`;
  } else {
    stats.message =
      "No known audit issue component was changed. Review the warnings and run the individual component update if needed.";
  }

  return stats;
}

function mergeAuditIssueFixResult(stats, componentName, result) {
  const changed = Boolean(
    result &&
    (result.updated ||
      result.created ||
      result.rebuilt ||
      result.variantsUpdated ||
      result.variantsCreated ||
      result.compositeRepairsApplied ||
      result.compositeInputInstancesRecreated),
  );
  const operation = {
    componentName,
    changed,
    componentSetId: result && result.componentSetId,
    urlNodeId: result && result.urlNodeId,
    message: result && result.message,
    warnings: result && Array.isArray(result.warnings) ? result.warnings : [],
  };

  stats.operations.push(operation);
  if (operation.componentSetId && !stats.componentSetId) {
    stats.componentSetId = operation.componentSetId;
  }
  if (operation.urlNodeId && !stats.urlNodeId) {
    stats.urlNodeId = operation.urlNodeId;
  }

  for (const key of [
    "variantsUpdated",
    "variantsCreated",
    "variantsRemoved",
    "variantsMissing",
    "compositeRepairsApplied",
    "compositeInputInstancesRecreated",
    "componentVariableBindingsSkipped",
  ]) {
    if (result && typeof result[key] === "number") {
      stats[key] = (stats[key] || 0) + result[key];
    }
  }

  for (const warning of operation.warnings) {
    stats.warnings.push(`${componentName}: ${warning}`);
  }
  if (!changed && operation.message) {
    stats.warnings.push(`${componentName}: ${operation.message}`);
  }
}

function createAuditPerformance() {
  return {
    phases: [],
    byName: {},
  };
}

function auditTimerNow() {
  return Date.now();
}

const AUDIT_ROLLUP_TIMING_NAMES = new Set(["component set total"]);

function timeAuditStep(performance, name, metadata, callback) {
  const startedAt = auditTimerNow();
  try {
    return callback();
  } finally {
    recordAuditTiming(performance, name, startedAt, metadata);
  }
}

function indexAuditPropertiesByBaseName(properties) {
  const result = {};
  for (const property of Object.values(properties || {})) {
    if (!property || !property.baseName || result[property.baseName]) continue;
    result[property.baseName] = property;
  }
  return result;
}

function recordAuditTiming(performance, name, startedAt, metadata) {
  if (!performance || !name || typeof startedAt !== "number") return;

  const durationMs = Math.max(0, auditTimerNow() - startedAt);
  const entry = {
    name,
    durationMs,
  };
  if (metadata && Object.keys(metadata).length > 0) {
    entry.metadata = metadata;
  }
  performance.phases.push(entry);

  const aggregate = performance.byName[name] || {
    durationMs: 0,
    count: 0,
    maxDurationMs: 0,
    maxMetadata: null,
  };
  aggregate.durationMs += durationMs;
  aggregate.count += 1;
  if (durationMs >= aggregate.maxDurationMs) {
    aggregate.maxDurationMs = durationMs;
    aggregate.maxMetadata = metadata || null;
  }
  performance.byName[name] = aggregate;
}

function finalizeAuditPerformance(performance, startedAt) {
  const totalMs = Math.max(0, auditTimerNow() - startedAt);
  const byNameEntries = Object.entries(performance.byName).map(
    ([name, aggregate]) => ({
      name,
      durationMs: aggregate.durationMs,
      count: aggregate.count,
      maxDurationMs: aggregate.maxDurationMs,
      maxMetadata: aggregate.maxMetadata,
    }),
  );
  byNameEntries.sort((a, b) => b.durationMs - a.durationMs);
  const slowestPhase =
    byNameEntries.find((entry) => !AUDIT_ROLLUP_TIMING_NAMES.has(entry.name)) ||
    byNameEntries[0] ||
    null;

  return {
    totalMs,
    slowestPhase,
    byName: byNameEntries,
    phases: performance.phases,
  };
}

async function inspectFile() {
  const collections = await figma.variables.getLocalVariableCollectionsAsync();
  const variables = await figma.variables.getLocalVariablesAsync();

  return {
    fileName: figma.root.name,
    pages: figma.root.children.map((page) => page.name),
    variableCollections: collections.map((collection) => ({
      name: collection.name,
      modes: collection.modes.map((mode) => mode.name),
      variableCount: variables.filter(
        (variable) => variable.variableCollectionId === collection.id,
      ).length,
    })),
    variables: variables.length,
  };
}

