async function buildAllExamplePages() {
  const results = [];
  results.push(await buildDashboardExamplePage());
  results.push(await buildSettingsExamplePage());
  results.push(await buildMobileDrawerExamplePage());
  results.push(await buildOperationsConsoleExamplePage());
  results.push(await buildSdkRouteFlowExamplePage());
  results.push(await buildKioskHandoffExamplePage());

  const warnings = [];
  for (const result of results) {
    for (const warning of result.warnings || []) warnings.push(warning);
  }

  return {
    page: EXAMPLES_PAGE_NAME,
    templateName: "All Examples",
    templateCount: results.length,
    templates: results.map((result) => ({
      name: result.templateName,
      id: result.id,
      urlNodeId: result.urlNodeId,
    })),
    warnings,
    message: `Created ${results.length} example templates on the Examples page.`,
  };
}

async function buildExampleTemplate(key, builder) {
  const config = EXAMPLE_TEMPLATE_CONFIGS[key];
  const stats = createExampleStats(config.name);
  const page = await ensurePage(EXAMPLES_PAGE_NAME);
  await figma.setCurrentPageAsync(page);
  const fonts = await loadButtonFonts(stats);
  await ensureKozmosTextStyles(fonts, stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);

  const cleanup = removeExistingExampleTemplate(page, config.name, key);
  const root = await builder({
    config,
    fonts,
    variableByName,
    stats,
  });
  const placement = resolveExampleTemplatePlacement(
    page,
    root,
    config,
    cleanup.untaggedMatchCount > 0,
  );
  if (cleanup.untaggedMatchCount > 0) {
    const placementSummary = placement.moved
      ? `placed the new generated example at (${Math.round(placement.x)}, ${Math.round(placement.y)}) outside existing page content`
      : "kept the new generated example at its configured position because that slot was clear";
    stats.warnings.push(
      `${config.name}: found ${cleanup.untaggedMatchCount} same-name frame(s) without importer example metadata. Left them untouched and ${placementSummary}.`,
    );
  }
  root.x = placement.x;
  root.y = placement.y;
  root.setSharedPluginData(RUN_NAMESPACE, "kind", "example-template");
  root.setSharedPluginData(RUN_NAMESPACE, "example", key);
  page.appendChild(root);
  normalizeExampleDeferredChildSizing(root);
  stats.framesCreated += 1;

  try {
    figma.viewport.scrollAndZoomIntoView([root]);
  } catch (_error) {
    // Viewport APIs are unavailable in some headless/plugin test contexts.
  }

  return {
    page: EXAMPLES_PAGE_NAME,
    templateName: config.name,
    templateCount: 1,
    id: root.id,
    urlNodeId: nodeIdForUrl(root.id),
    framesCreated: stats.framesCreated,
    instancesCreated: stats.instancesCreated,
    placeholdersCreated: stats.placeholdersCreated,
    warnings: stats.warnings,
    message: `Created ${config.name} on the Examples page.`,
  };
}

function createExampleStats(templateName) {
  return {
    page: EXAMPLES_PAGE_NAME,
    templateName,
    framesCreated: 0,
    instancesCreated: 0,
    placeholdersCreated: 0,
    warnings: [],
  };
}

function removeExistingExampleTemplate(page, name, key) {
  const removable = [];
  let untaggedMatchCount = 0;
  for (const child of page.children) {
    if (child.name !== name) continue;

    let kind = "";
    let example = "";
    try {
      kind = child.getSharedPluginData(RUN_NAMESPACE, "kind") || "";
      example = child.getSharedPluginData(RUN_NAMESPACE, "example") || "";
    } catch (_error) {
      kind = "";
      example = "";
    }

    if (kind === "example-template" && example === key) {
      removable.push(child);
    } else {
      untaggedMatchCount += 1;
    }
  }

  for (const child of removable) {
    child.remove();
  }

  return {
    removedCount: removable.length,
    untaggedMatchCount,
  };
}

function resolveExampleTemplatePlacement(page, root, config, avoidCollisions) {
  const desired = { x: config.x, y: config.y };
  if (!avoidCollisions) {
    return {
      x: desired.x,
      y: desired.y,
      moved: false,
    };
  }

  const size = sceneNodeSize(root, config);
  const desiredBounds = {
    x: desired.x,
    y: desired.y,
    width: size.width,
    height: size.height,
  };
  const occupiedBounds = page.children
    .map((child) => sceneNodeBounds(child))
    .filter(Boolean);

  if (
    !occupiedBounds.some((bounds) => rectanglesOverlap(desiredBounds, bounds))
  ) {
    return {
      x: desired.x,
      y: desired.y,
      moved: false,
    };
  }

  const maxBottom = occupiedBounds.reduce(
    (bottom, bounds) => Math.max(bottom, bounds.y + bounds.height),
    config.y,
  );

  return {
    x: config.x,
    y: maxBottom + EXAMPLE_TEMPLATE_COLLISION_GAP,
    moved: true,
  };
}

function sceneNodeSize(node, fallback) {
  const width =
    node && typeof node.width === "number" && Number.isFinite(node.width)
      ? node.width
      : fallback.width;
  const height =
    node && typeof node.height === "number" && Number.isFinite(node.height)
      ? node.height
      : fallback.height;

  return { width, height };
}

function sceneNodeBounds(node) {
  if (!node) return null;
  if (
    typeof node.x !== "number" ||
    typeof node.y !== "number" ||
    typeof node.width !== "number" ||
    typeof node.height !== "number" ||
    !Number.isFinite(node.x) ||
    !Number.isFinite(node.y) ||
    !Number.isFinite(node.width) ||
    !Number.isFinite(node.height)
  ) {
    return null;
  }

  return {
    x: node.x,
    y: node.y,
    width: node.width,
    height: node.height,
  };
}

function rectanglesOverlap(a, b) {
  return (
    a.x < b.x + b.width &&
    a.x + a.width > b.x &&
    a.y < b.y + b.height &&
    a.y + a.height > b.y
  );
}

