function createExampleMapStage({
  name,
  width,
  height,
  fonts,
  variableByName,
  stats,
}) {
  const stage = createExampleFrame({
    name,
    width,
    height,
    padding: 20,
    itemSpacing: 10,
    fillToken: "Surface/200",
    fillFallback: "#E8EEF5",
    variableByName,
    stats,
  });
  stage.counterAxisAlignItems = "CENTER";
  stage.primaryAxisAlignItems = "CENTER";

  const path = figma.createFrame();
  path.name = "Route Path Preview";
  path.layoutMode = "HORIZONTAL";
  path.primaryAxisSizingMode = "FIXED";
  path.counterAxisSizingMode = "FIXED";
  path.primaryAxisAlignItems = "CENTER";
  path.counterAxisAlignItems = "CENTER";
  path.itemSpacing = 8;
  const markerSizes = [18, 12, 12, 12, 18];
  const markerWidth = markerSizes.reduce((total, size) => total + size, 0);
  const routeGapWidth = (markerSizes.length * 2 - 2) * path.itemSpacing;
  const maxRouteWidth = Math.max(220, width - 48);
  const segmentWidth = Math.max(
    24,
    Math.floor((maxRouteWidth - markerWidth - routeGapWidth) / 4),
  );
  const routeWidth = markerWidth + segmentWidth * 4 + routeGapWidth;
  path.resizeWithoutConstraints(routeWidth, 56);
  path.fills = [];
  path.strokes = [];

  for (let index = 0; index < 5; index += 1) {
    if (index > 0) {
      const segment = figma.createRectangle();
      segment.name = "Route Segment";
      segment.resizeWithoutConstraints(segmentWidth, 4);
      segment.cornerRadius = KOZMOS_RADIUS.pill;
      segment.fills = [
        paintFromVariable("Colors/theme/500", "#135BEC", variableByName, stats),
      ];
      path.appendChild(segment);
    }

    const marker = figma.createEllipse();
    marker.name = index === 0 ? "Origin Marker" : "Route Marker";
    const markerSize = markerSizes[index];
    marker.resizeWithoutConstraints(markerSize, markerSize);
    marker.fills = [
      paintFromVariable(
        index === 4 ? "Colors/emotional/success/500" : "Colors/theme/500",
        index === 4 ? "#16A34A" : "#2563EB",
        variableByName,
        stats,
      ),
    ];
    marker.strokes = [
      paintFromVariable("Surface/0", "#FFFFFF", variableByName, stats),
    ];
    marker.strokeWeight = 2;
    path.appendChild(marker);
  }

  stage.appendChild(path);
  stage.appendChild(
    createExampleText({
      name: "Map Stage Label",
      characters: "Route preview placeholder",
      font: fonts.medium,
      fontSize: 11,
      lineHeight: 16,
      colorToken: "Colors/foreground/400",
      colorFallback: "#5F6675",
      width: width - 56,
      variableByName,
      stats,
    }),
  );
  return stage;
}

function createExampleFrame({
  name,
  width,
  height,
  padding,
  itemSpacing,
  fillToken,
  fillFallback,
  variableByName,
  stats,
}) {
  const frame = figma.createFrame();
  frame.name = name;
  frame.layoutMode = "VERTICAL";
  frame.primaryAxisSizingMode = "FIXED";
  frame.counterAxisSizingMode = "FIXED";
  frame.primaryAxisAlignItems = "MIN";
  frame.counterAxisAlignItems = "MIN";
  frame.itemSpacing = itemSpacing || 0;
  frame.paddingLeft = padding || 0;
  frame.paddingRight = padding || 0;
  frame.paddingTop = padding || 0;
  frame.paddingBottom = padding || 0;
  frame.resizeWithoutConstraints(width, height);
  frame.fills = [
    paintFromVariable(fillToken, fillFallback, variableByName, stats),
  ];
  frame.strokes = [];
  frame.setSharedPluginData(RUN_NAMESPACE, "kind", "example-frame");
  return frame;
}

