function createExampleText({
  name,
  characters,
  font,
  fontSize,
  lineHeight,
  colorToken,
  colorFallback,
  width,
  variableByName,
  stats,
}) {
  const text = figma.createText();
  text.name = name;
  text.fontName = font;
  text.fontSize = fontSize;
  text.lineHeight = { unit: "PIXELS", value: lineHeight };
  text.fills = [
    paintFromVariable(colorToken, colorFallback, variableByName, stats),
  ];
  if (width) resizeNodeWithoutConstraints(text, width, lineHeight);
  setTextAutoResize(text, "HEIGHT");
  setExampleChildSizing(text, "vertical-fill");
  text.characters = characters;
  return text;
}

function setHorizontalFillTextSizing(node) {
  setLayoutSizingHorizontal(node, "FILL");
  setLayoutSizingVertical(node, "HUG");

  try {
    node.layoutGrow = 1;
  } catch (_error) {
    // layoutGrow is unavailable on older plugin runtimes.
  }

  try {
    node.layoutAlign = "CENTER";
  } catch (_error) {
    // layoutAlign is unavailable on older plugin runtimes.
  }
}

function setExampleChildSizing(node, sizingMode) {
  if (!node || !sizingMode) return;

  try {
    node.setSharedPluginData(
      RUN_NAMESPACE,
      EXAMPLE_CHILD_SIZING_DATA_KEY,
      sizingMode,
    );
  } catch (_error) {
    // Shared plugin data is unavailable for a small subset of node-like values.
  }

  applyExampleChildSizing(node, sizingMode);
}

function normalizeExampleDeferredChildSizing(node) {
  if (!node || !node.children) return;

  for (const child of node.children) {
    let sizingMode = "";
    try {
      sizingMode =
        child.getSharedPluginData(
          RUN_NAMESPACE,
          EXAMPLE_CHILD_SIZING_DATA_KEY,
        ) || "";
    } catch (_error) {
      sizingMode = "";
    }

    if (sizingMode) applyExampleChildSizing(child, sizingMode);
    normalizeExampleDeferredChildSizing(child);
  }
}

function applyExampleChildSizing(node, sizingMode) {
  if (sizingMode === "horizontal-fill-fixed") {
    setHorizontalStackFillFixedChildSizing(node);
  } else if (sizingMode === "horizontal-fill-hug") {
    setHorizontalStackFillHugChildSizing(node);
  } else if (sizingMode === "vertical-fill") {
    setVerticalStackChildSizing(node);
  } else if (sizingMode === "fixed") {
    setFixedChildSizing(node);
  } else if (sizingMode === "hug") {
    setHugChildSizing(node);
  }
}

async function createExampleInstance({
  componentSetName,
  variantProperties,
  name,
  textProperties,
  booleanProperties,
  width,
  height,
  fillHorizontal,
  growHorizontal,
  fonts,
  variableByName,
  stats,
}) {
  const created = await createNestedComponentInstance({
    componentSetName,
    variantProperties: variantProperties || {},
    name,
    role: "example",
    stats,
  });

  if (!created) {
    const placeholder = createExamplePlaceholder({
      name,
      label: componentSetName,
      width: width || 180,
      height: height || 44,
      fonts,
      variableByName,
      stats,
    });
    if (growHorizontal) {
      if (height) {
        setExampleChildSizing(placeholder, "horizontal-fill-fixed");
      } else {
        setExampleChildSizing(placeholder, "horizontal-fill-hug");
      }
    } else if (fillHorizontal) {
      setExampleChildSizing(placeholder, "vertical-fill");
    } else if (width && height) {
      setExampleChildSizing(placeholder, "fixed");
    } else {
      setExampleChildSizing(placeholder, "hug");
    }
    return placeholder;
  }

  const { componentSet, instance } = created;
  // An instance of a Core control is a control, whatever it is placed inside.
  // Start Navigation Button and End Route Button reach the nesting check this
  // way rather than through productSdkControlButton.
  if (CONTROL_COMPONENT_SETS.has(componentSetName)) {
    markControlSurface(instance);
  }
  if (textProperties) {
    for (const [baseName, value] of Object.entries(textProperties)) {
      setInstanceTextProperty(instance, componentSet, baseName, value, stats);
    }
  }
  if (booleanProperties) {
    for (const [baseName, value] of Object.entries(booleanProperties)) {
      setInstanceBooleanProperty(
        instance,
        componentSet,
        baseName,
        value,
        stats,
      );
    }
  }

  if (width && height) resizeNodeWithoutConstraints(instance, width, height);
  if (growHorizontal) {
    if (height) {
      setExampleChildSizing(instance, "horizontal-fill-fixed");
    } else {
      setExampleChildSizing(instance, "horizontal-fill-hug");
    }
  } else if (fillHorizontal) {
    setExampleChildSizing(instance, "vertical-fill");
  } else if (width && height) {
    setExampleChildSizing(instance, "fixed");
  } else {
    setExampleChildSizing(instance, "hug");
  }
  stats.instancesCreated += 1;
  return instance;
}

function createExamplePlaceholder({
  name,
  label,
  width,
  height,
  fonts,
  variableByName,
  stats,
}) {
  const placeholder = figma.createFrame();
  placeholder.name = name || `Missing ${label}`;
  placeholder.layoutMode = "HORIZONTAL";
  placeholder.primaryAxisSizingMode = "FIXED";
  placeholder.counterAxisSizingMode = "FIXED";
  placeholder.primaryAxisAlignItems = "CENTER";
  placeholder.counterAxisAlignItems = "CENTER";
  placeholder.paddingLeft = 12;
  placeholder.paddingRight = 12;
  placeholder.paddingTop = 8;
  placeholder.paddingBottom = 8;
  placeholder.cornerRadius = KOZMOS_RADIUS.control;
  placeholder.resizeWithoutConstraints(width, height);
  placeholder.fills = [
    paintFromVariable("Surface/200", "#ECEEF2", variableByName, stats),
  ];
  placeholder.strokes = [
    paintFromVariable("Border/Subtle", "#C7CAD1", variableByName, stats),
  ];
  placeholder.strokeWeight = 1;
  placeholder.appendChild(
    createExampleText({
      name: "Placeholder Text",
      characters: `Missing ${label}`,
      font: fonts.medium,
      fontSize: 12,
      lineHeight: 16,
      colorToken: "Colors/foreground/400",
      colorFallback: "#5F6675",
      width: Math.max(width - 24, 40),
      variableByName,
      stats,
    }),
  );
  placeholder.setSharedPluginData(RUN_NAMESPACE, "kind", "example-placeholder");
  stats.placeholdersCreated += 1;
  return placeholder;
}

async function documentComponentLibrary() {
  const stats = {
    documented: 0,
    descriptionsUpdated: 0,
    pagesCreated: 0,
    pagesUpdated: 0,
    splitPagesRemoved: 0,
    previewsCreated: 0,
    missingComponentSets: [],
    page: null,
    sections: [],
    warnings: [],
  };

  const fonts = await loadButtonFonts(stats);
  const componentSets = await findComponentSetsByName(COMPONENT_DOCS);
  await removeGeneratedSplitDocPages(stats);

  const existed = Boolean(
    figma.root.children.find((page) => page.name === COMPONENT_DOCS_PAGE_NAME),
  );
  const page = await ensurePage(COMPONENT_DOCS_PAGE_NAME);
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();
  removeGeneratedComponentDocs(page);

  const header = createDocsCatalogHeaderFrame(fonts);
  page.appendChild(header);

  let columnIndex = 0;
  let rowY = DOCS_CANVAS_Y + header.height + 48;
  let rowHeight = 0;

  for (let docIndex = 0; docIndex < COMPONENT_DOCS.length; docIndex += 1) {
    const doc = COMPONENT_DOCS[docIndex];
    const componentSet = componentSets[doc.componentSetName];
    if (!componentSet) {
      stats.missingComponentSets.push(doc.componentSetName);
      continue;
    }

    applyComponentSetDescription(
      componentSet,
      doc.componentSetName,
      false,
      null,
    );
    stats.descriptionsUpdated += 1;

    const section = createComponentDocsRoot(doc, componentSet, fonts, stats);
    section.x =
      DOCS_CANVAS_X + columnIndex * (DOCS_SECTION_WIDTH + DOCS_SECTION_GAP);
    section.y = rowY;
    page.appendChild(section);

    stats.documented += 1;
    stats.sections.push({
      name: doc.componentSetName,
      componentSetId: componentSet.id,
      urlNodeId: nodeIdForUrl(componentSet.id),
      x: section.x,
      y: section.y,
    });

    rowHeight = Math.max(rowHeight, docsMeasuredHeight(section));
    columnIndex += 1;
    if (columnIndex >= DOCS_COLUMNS) {
      columnIndex = 0;
      rowY += rowHeight + DOCS_ROW_GAP;
      rowHeight = 0;
    }
  }

  if (existed) {
    stats.pagesUpdated += 1;
  } else {
    stats.pagesCreated += 1;
  }
  stats.page = {
    name: page.name,
    id: page.id,
  };

  if (stats.missingComponentSets.length > 0) {
    stats.warnings.push(
      `Missing component sets: ${stats.missingComponentSets.join(", ")}`,
    );
  }

  stats.message = `Documented ${stats.documented} component set(s) in a ${DOCS_COLUMNS}-column Docs page grid and updated ${stats.descriptionsUpdated} description field(s).`;
  return stats;
}

async function buildSurfaceQaPage() {
  const stats = {
    page: null,
    panelsCreated: 0,
    instancesCreated: 0,
    modeBindingsApplied: 0,
    missingComponentSets: [],
    missingVariants: [],
    warnings: [],
  };

  const fonts = await loadButtonFonts(stats);
  await ensureKozmosTextStyles(fonts, stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const collections = await figma.variables.getLocalVariableCollectionsAsync();
  const componentSets = await findComponentSetsByName(surfaceQaComponentDocs());
  const existed = Boolean(
    figma.root.children.find((page) => page.name === SURFACE_QA_PAGE_NAME),
  );
  const page = await ensurePage(SURFACE_QA_PAGE_NAME);
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();
  removeGeneratedSurfaceQa(page);

  const header = createSurfaceQaHeader(fonts);
  page.appendChild(header);

  const panels = [
    {
      title: "Surface/0 - Light",
      subtitle: "Transparent variants on the default product surface.",
      modeName: "Light",
      productSurface: false,
      fillToken: "Surface/0",
      fillFallback: "#FFFFFF",
      textTone: "light",
    },
    {
      title: "Surface/0 - Dark",
      subtitle: "The same live instances with the Dark variable mode applied.",
      modeName: "Dark",
      productSurface: false,
      fillToken: "Surface/0",
      fillFallback: "#101114",
      textTone: "dark",
    },
    {
      title: "Product map - Light",
      subtitle:
        "Representative indoor map surface with fill-extrusion and symbol_label layers.",
      modeName: "Light",
      productSurface: true,
      fillFallback: "#EEF3F8",
      textTone: "light",
    },
    {
      title: "Product map - Dark",
      subtitle:
        "Dark product-map host surface for glass, ghost, and transparent controls.",
      modeName: "Dark",
      productSurface: true,
      fillFallback: "#151B22",
      textTone: "dark",
    },
  ];

  for (let index = 0; index < panels.length; index += 1) {
    const panel = createSurfaceQaPanel(
      panels[index],
      componentSets,
      collections,
      variableByName,
      fonts,
      stats,
    );
    panel.x =
      SURFACE_QA_CANVAS_X +
      (index % 2) * (SURFACE_QA_PANEL_WIDTH + SURFACE_QA_PANEL_GAP);
    panel.y = SURFACE_QA_CANVAS_Y + 170 + Math.floor(index / 2) * 760;
    page.appendChild(panel);
    stats.panelsCreated += 1;
  }

  stats.page = {
    name: page.name,
    id: page.id,
    existed,
  };
  stats.message = `Built ${stats.panelsCreated} transparent surface QA panel(s) with ${stats.instancesCreated} live component instance(s).`;
  return stats;
}

function surfaceQaComponentDocs() {
  const requested = {};
  for (const group of SURFACE_QA_COMPONENT_GROUPS) {
    for (const row of group.rows) {
      for (const spec of row) requested[spec.componentSetName] = true;
    }
  }

  return Object.keys(requested).map((componentSetName) => ({
    componentSetName,
  }));
}

/**
 * Split an ordered list of heights into at most `columnCount` contiguous
 * groups, minimising the tallest group.
 *
 * Contiguous matters: each column then holds a consecutive slice of the
 * section's alphabetized list, so reading order stays column-major (down, then
 * across) the way a newspaper reads. Binary-searching the height limit and
 * greedily filling is exact for this problem and cheap at these sizes.
 */
function partitionIntoContiguousColumns(heights, columnCount) {
  if (heights.length === 0) return [];

  const limitCount = Math.max(1, Math.min(columnCount, heights.length));
  if (limitCount === 1) return [heights.map((_value, index) => index)];

  let low = 0;
  let high = 0;

  for (const height of heights) {
    low = Math.max(low, height);
    high += height;
  }

  const fits = (limit) => {
    let used = 1;
    let current = 0;

    for (const height of heights) {
      if (current > 0 && current + height > limit) {
        used += 1;
        current = height;
      } else {
        current += height;
      }
    }

    return used <= limitCount;
  };

  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (fits(mid)) high = mid;
    else low = mid + 1;
  }

  const groups = [[]];
  let current = 0;

  for (let index = 0; index < heights.length; index += 1) {
    const group = groups[groups.length - 1];

    if (group.length > 0 && current + heights[index] > low) {
      groups.push([index]);
      current = heights[index];
      continue;
    }

    group.push(index);
    current += heights[index];
  }

  return groups;
}

/**
 * Flow blocks into the column count whose resulting bounding box is closest to
 * square, and return the placement.
 *
 * Reviewability is what this optimises. A tall ribbon and a wide ribbon are
 * equally awkward to scan, and a roughly square block is what Figma's
 * zoom-to-fit is good at. Deriving the count from the measured sizes rather
 * than a target-height constant means it keeps choosing well as sets are added,
 * with nothing to re-tune.
 *
 * Each block is `{ width, height }`; `gap` separates blocks within a column and
 * `columnGap` separates the columns.
 */
function packBlocksIntoColumns(blocks, gap, columnGap, maxColumns) {
  if (blocks.length === 0) {
    return { groups: [], columns: [], width: 0, height: 0 };
  }

  const packHeights = blocks.map((block) => block.height + gap);
  const limit = Math.max(1, Math.min(maxColumns, blocks.length));
  let best = null;

  for (let count = 1; count <= limit; count += 1) {
    const groups = partitionIntoContiguousColumns(packHeights, count);
    const columns = [];
    let width = 0;
    let height = 0;

    for (const group of groups) {
      let columnWidth = 0;
      let columnHeight = 0;

      for (const index of group) {
        columnWidth = Math.max(columnWidth, blocks[index].width);
        columnHeight += packHeights[index];
      }

      columnHeight = Math.max(0, columnHeight - gap);
      columns.push({ x: width, width: columnWidth, height: columnHeight });
      width += columnWidth + columnGap;
      height = Math.max(height, columnHeight);
    }

    width = Math.max(0, width - columnGap);
    const aspect =
      Math.max(width, height) / Math.max(1, Math.min(width, height));

    if (!best || aspect < best.aspect) {
      best = { groups, columns, width, height, aspect };
    }
  }

  return best;
}

function componentSetFootprintHeight(node, bounds) {
  return Math.max(
    bounds.height,
    COMPONENT_PAGE_LAYOUT_MIN_HEIGHTS[canonicalComponentSetName(node.name)] ||
      0,
    COMPONENT_PAGE_LAYOUT_MIN_FOOTPRINT_HEIGHT,
  );
}

/**
 * Lay one section's component sets out in columns, relative to the section's
 * content origin. Column widths are independent because set widths in this
 * library span roughly 200px to several thousand, so a uniform column width
 * would either clip the wide ones or strand whitespace beside the narrow ones.
 */
function layoutComponentSetColumns(nodes) {
  const entries = [];

  for (const node of nodes) {
    const bounds = measureComponentSetLayoutBounds(node);
    entries.push({
      node,
      bounds,
      footprintHeight: componentSetFootprintHeight(node, bounds),
      x: 0,
      y: 0,
    });
  }

  const packed = packBlocksIntoColumns(
    entries.map((entry) => ({
      width: entry.bounds.width,
      height: entry.footprintHeight,
    })),
    COMPONENT_PAGE_LAYOUT_ROW_GAP,
    COMPONENT_PAGE_LAYOUT_COLUMN_GAP,
    COMPONENT_PAGE_LAYOUT_MAX_COLUMNS,
  );

  packed.groups.forEach((group, columnIndex) => {
    const column = packed.columns[columnIndex];
    let columnY = 0;

    for (const index of group) {
      const entry = entries[index];
      entry.x = column.x;
      entry.y = columnY;
      columnY += entry.footprintHeight + COMPONENT_PAGE_LAYOUT_ROW_GAP;
    }

    column.componentCount = group.length;
  });

  return {
    entries,
    columns: packed.columns,
    contentWidth: packed.width,
    contentHeight: packed.height,
  };
}

async function reorganizeComponentsPage() {
  const stats = {
    page: COMPONENTS_PAGE_NAME,
    preservedNodeIds: true,
    movedComponentSets: 0,
    renamedComponentSets: 0,
    unexpectedTopLevelInstancesRemoved: 0,
    skippedComponentSets: [],
    sections: [],
    positions: [],
    warnings: [],
  };
  const page = figma.root.children.find(
    (child) => child.name === COMPONENTS_PAGE_NAME,
  );

  if (!page) {
    stats.message =
      "Components page was not found. Build at least one component set first.";
    return stats;
  }

  await figma.setCurrentPageAsync(page);
  await page.loadAsync();
  removeUnexpectedTopLevelGeneratedInstances(page, stats);
  removeDuplicateGeneratedComponentSetsForKnownComponents(page, stats);

  const fonts = await loadButtonFonts(stats);
  const activeSectionTitles = {};
  const sectionNodes = [];
  for (const section of COMPONENT_PAGE_LAYOUT_SECTIONS) {
    // One yield per section. This pass repositions every set on the page and
    // runs last, so without a break in it the end of a bulk run is a single
    // block Figma cannot save through — which is what the panel's "then
    // reorganizing once" was quietly costing.
    await yieldToFigma();
    const nodes = [];

    for (const name of section.components) {
      const node = findComponentSetOnPage(page, name);

      if (node) {
        normalizeComponentSetNodeName(node, name, stats);
        nodes.push(node);
      } else {
        stats.skippedComponentSets.push(name);
      }
    }

    if (nodes.length === 0) continue;

    activeSectionTitles[section.title] = true;
    sectionNodes.push({
      title: section.title,
      nodes,
    });
  }

  if (sectionNodes.length === 0) {
    stats.message = "No known component sets were found to reorganize.";
    return stats;
  }

  const useNativeSections = canCreateComponentLayoutSection();
  removeGeneratedComponentSectionHeadings(page, activeSectionTitles, {
    removeActive: useNativeSections,
  });
  removeStaleComponentLayoutSections(page, activeSectionTitles);

  // Measure every section before placing any of it: packing the sections
  // themselves into columns needs all the block sizes up front.
  const measuredSections = [];

  for (const section of sectionNodes) {
    const layout = layoutComponentSetColumns(section.nodes);
    const heading = useNativeSections
      ? null
      : upsertComponentSectionHeading(page, section.title, fonts);
    const contentOffsetY = heading
      ? Math.ceil(heading.height || 0) +
        COMPONENT_PAGE_LAYOUT_SECTION_HEADING_GAP
      : COMPONENT_PAGE_LAYOUT_SECTION_PADDING_TOP;
    const trailing = useNativeSections
      ? COMPONENT_PAGE_LAYOUT_SECTION_PADDING_BOTTOM
      : 0;
    const inset = useNativeSections
      ? COMPONENT_PAGE_LAYOUT_SECTION_PADDING_X
      : 0;

    measuredSections.push({
      section,
      layout,
      heading,
      contentOffsetX: inset,
      contentOffsetY,
      width: layout.contentWidth + inset * 2,
      height: contentOffsetY + layout.contentHeight + trailing,
    });
  }

  const sectionGrid = packBlocksIntoColumns(
    measuredSections,
    COMPONENT_PAGE_LAYOUT_SECTION_GAP,
    COMPONENT_PAGE_LAYOUT_SECTION_COLUMN_GAP,
    COMPONENT_PAGE_LAYOUT_MAX_SECTION_COLUMNS,
  );
  stats.sectionColumns = sectionGrid.columns.length;
  stats.pageWidth = sectionGrid.width;
  stats.pageHeight = sectionGrid.height;

  sectionGrid.groups.forEach((group, columnIndex) => {
    const column = sectionGrid.columns[columnIndex];
    let columnY = COMPONENT_PAGE_LAYOUT_Y;

    for (const index of group) {
      const block = measuredSections[index];
      placeComponentSection(
        page,
        block,
        COMPONENT_PAGE_LAYOUT_X + column.x,
        columnY,
        useNativeSections,
        stats,
      );
      columnY += block.height + COMPONENT_PAGE_LAYOUT_SECTION_GAP;
    }
  });

  if (stats.skippedComponentSets.length > 0) {
    stats.warnings.push(
      `${stats.skippedComponentSets.length} known component set(s) were not present on the Components page.`,
    );
  }

  const renameSummary =
    stats.renamedComponentSets > 0
      ? ` Renamed ${stats.renamedComponentSets} legacy / v1 set(s) in place.`
      : "";
  const cleanupSummary =
    stats.unexpectedTopLevelInstancesRemoved > 0
      ? ` Removed ${stats.unexpectedTopLevelInstancesRemoved} stray top-level generated instance(s).`
      : "";
  stats.message =
    `Reorganized ${stats.movedComponentSets} component set(s) on the Components page into ${stats.sections.length} alphabetized ${useNativeSections ? "native Figma section" : "section heading"} group(s) across ${stats.sectionColumns} column(s), ${stats.pageWidth} x ${stats.pageHeight}px; node IDs were preserved.` +
    renameSummary +
    cleanupSummary;
  return stats;
}

/**
 * Place one measured section and its component sets.
 *
 * Native sections own their children, so those children carry section-relative
 * coordinates; the text-heading fallback leaves everything on the page in
 * absolute coordinates. `stats.positions` always records absolute page
 * coordinates so the build report stays comparable across both paths.
 */
function placeComponentSection(
  page,
  block,
  originX,
  originY,
  useNativeSections,
  stats,
) {
  const sectionRecord = {
    title: block.section.title,
    kind: useNativeSections ? "SECTION" : "TEXT",
    x: originX,
    y: originY,
    width: block.width,
    height: block.height,
    columnCount: block.layout.columns.length,
    componentCount: 0,
    components: [],
  };

  let container = page;
  let contentOriginX = originX + block.contentOffsetX;
  let contentOriginY = originY + block.contentOffsetY;
  let layoutSection = null;

  if (useNativeSections) {
    layoutSection = upsertComponentLayoutSection(page, block.section.title);
    page.appendChild(layoutSection);
    layoutSection.x = originX;
    layoutSection.y = originY;
    container = layoutSection;
    contentOriginX = block.contentOffsetX;
    contentOriginY = block.contentOffsetY;
    sectionRecord.id = layoutSection.id;
    sectionRecord.urlNodeId = nodeIdForUrl(layoutSection.id);
  } else {
    block.heading.x = originX;
    block.heading.y = originY;
    sectionRecord.headingId = block.heading.id;
    sectionRecord.headingUrlNodeId = nodeIdForUrl(block.heading.id);
  }

  for (const entry of block.layout.entries) {
    const node = entry.node;
    const contentX = contentOriginX + entry.x;
    const contentY = contentOriginY + entry.y;

    if (node.parent !== container) container.appendChild(node);
    node.x = contentX - entry.bounds.minX;
    node.y = contentY - entry.bounds.minY;
    stats.movedComponentSets += 1;
    stats.positions.push({
      name: node.name,
      section: block.section.title,
      id: node.id,
      urlNodeId: nodeIdForUrl(node.id),
      x: node.x,
      y: node.y,
      visualX: layoutSection ? originX + contentX : contentX,
      visualY: layoutSection ? originY + contentY : contentY,
      width: entry.bounds.width,
      height: entry.bounds.height,
      footprintHeight: entry.footprintHeight,
    });
    sectionRecord.componentCount += 1;
    sectionRecord.components.push(node.name);
  }

  if (layoutSection) {
    resizeNodeWithoutConstraints(layoutSection, block.width, block.height);
  }

  stats.sections.push(sectionRecord);
  return sectionRecord;
}

function componentPageLayoutOrder(sections) {
  const order = [];

  for (const section of sections) {
    for (const componentName of section.components) {
      order.push(componentName);
    }
  }

  return order;
}

function removeDuplicateGeneratedComponentSetsForKnownComponents(page, stats) {
  const knownNames = componentPageLayoutOrder(COMPONENT_PAGE_LAYOUT_SECTIONS);

  for (const componentSetName of knownNames) {
    const keep = findComponentSetOnPage(page, componentSetName);
    if (!keep || keep.type !== "COMPONENT_SET") continue;

    removeDuplicateGeneratedComponentSetsForName(
      page,
      componentSetName,
      keep,
      stats,
    );
  }
}

function componentSectionHeadingName(title) {
  return `Section / ${title}`;
}

function isComponentSectionHeading(node) {
  if (!node) return false;
  if (
    node.getSharedPluginData &&
    node.getSharedPluginData(RUN_NAMESPACE, "kind") ===
      "component-section-heading"
  ) {
    return true;
  }

  return node.type === "TEXT" && /^Section \/ .+/.test(node.name || "");
}

function isComponentLayoutSection(node) {
  if (!node || node.type !== "SECTION") return false;
  if (
    node.getSharedPluginData &&
    node.getSharedPluginData(RUN_NAMESPACE, "kind") === "component-section"
  ) {
    return true;
  }

  for (const section of COMPONENT_PAGE_LAYOUT_SECTIONS) {
    if (node.name === section.title) return true;
  }

  return false;
}

function canCreateComponentLayoutSection() {
  return typeof figma.createSection === "function";
}

function removeGeneratedComponentSectionHeadings(
  page,
  activeSectionTitles,
  options,
) {
  const removable = [];

  for (const child of page.children) {
    if (!isComponentSectionHeading(child)) continue;
    const title = String(child.name || "").replace(/^Section \/ /, "");
    if (options && options.removeActive) {
      removable.push(child);
    } else if (!activeSectionTitles[title]) {
      removable.push(child);
    }
  }

  for (const child of removable) {
    child.remove();
  }
}

function removeStaleComponentLayoutSections(page, activeSectionTitles) {
  const removable = [];

  for (const child of page.children) {
    if (!isComponentLayoutSection(child)) continue;
    const title =
      (child.getSharedPluginData &&
        child.getSharedPluginData(RUN_NAMESPACE, "title")) ||
      child.name;
    if (!activeSectionTitles[title]) removable.push(child);
  }

  for (const section of removable) {
    unwrapSectionChildrenToPage(section, page);
    section.remove();
  }
}

function unwrapSectionChildrenToPage(section, page) {
  if (!section || !section.children) return;

  while (section.children.length > 0) {
    const child = section.children[0];
    const position = absoluteNodePosition(child);
    page.appendChild(child);
    child.x = position.x;
    child.y = position.y;
  }
}

function upsertComponentLayoutSection(page, title) {
  let layoutSection = null;

  for (const child of page.children) {
    if (child.type !== "SECTION") continue;
    const sectionTitle =
      (child.getSharedPluginData &&
        child.getSharedPluginData(RUN_NAMESPACE, "title")) ||
      child.name;
    if (sectionTitle === title) {
      layoutSection = child;
      break;
    }
  }

  if (!layoutSection) {
    layoutSection = figma.createSection();
    page.appendChild(layoutSection);
  }

  layoutSection.name = title;
  layoutSection.setSharedPluginData(RUN_NAMESPACE, "kind", "component-section");
  layoutSection.setSharedPluginData(RUN_NAMESPACE, "title", title);
  try {
    layoutSection.sectionContentsHidden = false;
  } catch (_error) {
    // Older runtimes may not expose collapsible section contents.
  }

  return layoutSection;
}

function upsertComponentSectionHeading(page, title, fonts) {
  const name = componentSectionHeadingName(title);
  let heading = null;

  for (const child of page.children) {
    if (child.name === name && child.type === "TEXT") {
      heading = child;
      break;
    }
  }

  if (!heading) {
    heading = figma.createText();
    page.appendChild(heading);
  }

  heading.name = name;
  heading.fontName = fonts.bold;
  heading.fontSize = 24;
  heading.lineHeight = { unit: "PIXELS", value: 32 };
  heading.fills = [paintFromHex("#2D3440")];
  setTextAutoResize(heading, "WIDTH_AND_HEIGHT");
  heading.characters = title;
  heading.setSharedPluginData(
    RUN_NAMESPACE,
    "kind",
    "component-section-heading",
  );
  heading.setSharedPluginData(RUN_NAMESPACE, "title", title);
  return heading;
}

function measureComponentSetLayoutBounds(node) {
  const bounds = {
    minX: 0,
    minY: 0,
    maxX: Math.ceil(node.width || 0),
    maxY: Math.ceil(node.height || 0),
  };

  measureVisibleChildBounds(node, 0, 0, bounds);

  const minX = Math.floor(bounds.minX);
  const minY = Math.floor(bounds.minY);
  const maxX = Math.ceil(bounds.maxX);
  const maxY = Math.ceil(bounds.maxY);

  return {
    minX,
    minY,
    maxX,
    maxY,
    width: maxX - minX,
    height: maxY - minY,
  };
}

function absoluteNodePosition(node) {
  if (node && node.absoluteTransform) {
    return {
      x: node.absoluteTransform[0][2],
      y: node.absoluteTransform[1][2],
    };
  }

  let x = Number((node && node.x) || 0);
  let y = Number((node && node.y) || 0);
  let parent = node && node.parent;

  while (parent && parent.type !== "PAGE" && parent.type !== "DOCUMENT") {
    x += Number(parent.x || 0);
    y += Number(parent.y || 0);
    parent = parent.parent;
  }

  return { x, y };
}

function measureVisibleChildBounds(parent, offsetX, offsetY, bounds) {
  if (!parent || !("children" in parent)) return;

  for (const child of parent.children) {
    if (child.visible === false) continue;

    const childX = offsetX + (child.x || 0);
    const childY = offsetY + (child.y || 0);
    const childWidth = child.width || 0;
    const childHeight = child.height || 0;

    bounds.minX = Math.min(bounds.minX, childX);
    bounds.minY = Math.min(bounds.minY, childY);
    bounds.maxX = Math.max(bounds.maxX, childX + childWidth);
    bounds.maxY = Math.max(bounds.maxY, childY + childHeight);

    measureVisibleChildBounds(child, childX, childY, bounds);
  }
}

function removeGeneratedSurfaceQa(page) {
  const removable = [];
  for (const child of page.children) {
    if (
      child.getSharedPluginData &&
      child.getSharedPluginData(RUN_NAMESPACE, "kind") === "surface-qa"
    ) {
      removable.push(child);
    }
  }

  for (const child of removable) child.remove();
}

