// A node, and what it holds, in the Dark mode of every Kozmos collection: the
// Figma form of a subtree with a theme of its own.
async function applyKozmosDarkMode(node, stats) {
  const collections = (
    await figma.variables.getLocalVariableCollectionsAsync()
  ).filter((collection) => collection.name.startsWith("Kozmos "));
  applySurfaceQaVariableMode(node, collections, "Dark", stats);
}

function applySurfaceQaVariableMode(node, collections, modeName, stats) {
  if (!node || !node.setExplicitVariableModeForCollection) return;

  for (const collection of collections) {
    const mode = (collection.modes || []).find(
      (candidate) => candidate.name === modeName,
    );
    if (!mode) continue;

    try {
      node.setExplicitVariableModeForCollection(collection.id, mode.modeId);
      stats.modeBindingsApplied += 1;
    } catch (_error) {
      try {
        node.setExplicitVariableModeForCollection(collection, mode.modeId);
        stats.modeBindingsApplied += 1;
      } catch (error) {
        stats.warnings.push(
          `Could not apply ${modeName} mode for ${collection.name} (${messageFor(error)}).`,
        );
      }
    }
  }
}

function pushUnique(values, value) {
  if (values.indexOf(value) === -1) values.push(value);
}

function canonicalComponentSetName(name) {
  if (!name) return name;
  return name.endsWith(COMPONENT_SET_LEGACY_SUFFIX)
    ? name.slice(0, -COMPONENT_SET_LEGACY_SUFFIX.length)
    : name;
}

function componentSetNameMatches(actualName, expectedName) {
  return (
    canonicalComponentSetName(actualName) ===
    canonicalComponentSetName(expectedName)
  );
}

function findComponentSetOnPage(page, name) {
  const canonicalName = canonicalComponentSetName(name);
  let legacyMatch = null;

  for (const componentSet of collectComponentSetsInPage(page)) {
    if (componentSet.name === canonicalName) return componentSet;
    if (
      !legacyMatch &&
      componentSetNameMatches(componentSet.name, canonicalName)
    ) {
      legacyMatch = componentSet;
    }
  }

  return legacyMatch;
}

function collectComponentSetsInPage(page) {
  const componentSets = [];
  if (!page || !page.children) return componentSets;

  collectComponentSetsInNode(page, componentSets);
  return componentSets;
}

function collectComponentSetsInNode(node, componentSets) {
  if (!node) return;
  if (node.type === "COMPONENT_SET") {
    componentSets.push(node);
    return;
  }

  if (!node.children) return;
  for (const child of node.children) {
    collectComponentSetsInNode(child, componentSets);
  }
}

function normalizeComponentSetNodeName(node, canonicalName, stats) {
  if (!node || node.name === canonicalName) return false;

  const oldName = node.name;
  node.name = canonicalName;
  if (stats) {
    incrementStat(stats, "renamedComponentSets");
    if (!stats.renamed) stats.renamed = [];
    stats.renamed.push({
      id: node.id,
      urlNodeId: nodeIdForUrl(node.id),
      oldName,
      newName: canonicalName,
    });
  }
  return true;
}

function removeDuplicateGeneratedComponentSetsForName(
  page,
  componentSetName,
  keepNode,
  stats,
) {
  if (!page) return 0;

  const matches = collectComponentSetsInPage(page).filter((node) =>
    componentSetNameMatches(node.name, componentSetName),
  );

  if (matches.length <= 1) return 0;

  const keep =
    keepNode ||
    matches.find(
      (node) => node.name === canonicalComponentSetName(componentSetName),
    ) ||
    matches[0];
  let removed = 0;

  for (const node of matches) {
    if (keep && node.id === keep.id) continue;

    const oldName = node.name;
    const oldId = node.id;
    try {
      node.remove();
      removed += 1;
      if (stats) {
        if (!stats.duplicateComponentSetsRemovedDetails) {
          stats.duplicateComponentSetsRemovedDetails = [];
        }
        stats.duplicateComponentSetsRemovedDetails.push({
          id: oldId,
          urlNodeId: nodeIdForUrl(oldId),
          oldName,
          keptId: keep && keep.id,
          keptUrlNodeId: keep && nodeIdForUrl(keep.id),
        });
      }
    } catch (error) {
      if (stats && stats.warnings) {
        stats.warnings.push(
          `Could not remove duplicate ${componentSetName} component set "${oldName}" (${messageFor(error)}).`,
        );
      }
    }
  }

  if (removed > 0) {
    incrementStat(stats, "duplicateComponentSetsRemoved", removed);
  }

  return removed;
}

// Set while a bulk update is running. Each single update reorganizes the whole
// Components page, which is fine once and pointless twenty-four times over a
// 94-set page; the bulk runner reorganizes once at the end instead.
let suppressAutoReorganize = false;

async function reorganizeAfterGeneratedComponentMutation(stats) {
  if (suppressAutoReorganize) {
    stats.layoutDeferred = true;
    return null;
  }
  stats.layout = await reorganizeComponentsPage();
  return stats.layout;
}

async function findComponentSetsByName(docs) {
  const requested = {};
  const found = {};

  for (const doc of docs) {
    requested[canonicalComponentSetName(doc.componentSetName)] = true;
  }

  for (const page of figma.root.children) {
    await page.loadAsync();
    for (const componentSet of collectComponentSetsInPage(page)) {
      const canonicalName = canonicalComponentSetName(componentSet.name);
      if (!requested[canonicalName]) continue;
      if (!found[canonicalName] || componentSet.name === canonicalName) {
        found[canonicalName] = componentSet;
      }
    }
  }

  return found;
}

function removeGeneratedComponentDocs(page) {
  const removable = [];

  for (const child of page.children) {
    if (child.getSharedPluginData(RUN_NAMESPACE, "kind") === "component-docs") {
      removable.push(child);
    }
  }

  for (const child of removable) {
    child.remove();
  }
}

async function removeGeneratedSplitDocPages(stats) {
  const removable = [];

  for (const page of figma.root.children) {
    if (page.name.indexOf(COMPONENT_DOC_SPLIT_PAGE_PREFIX) !== 0) continue;

    await page.loadAsync();
    let generatedDocsPage = false;
    for (const child of page.children) {
      if (
        child.getSharedPluginData(RUN_NAMESPACE, "kind") === "component-docs"
      ) {
        generatedDocsPage = true;
        break;
      }
    }

    if (generatedDocsPage) removable.push(page);
  }

  for (const page of removable) {
    try {
      if (figma.currentPage && figma.currentPage.id === page.id) {
        const fallback = figma.root.children.find(
          (candidate) => candidate.id !== page.id,
        );
        if (fallback) await figma.setCurrentPageAsync(fallback);
      }

      page.remove();
      stats.splitPagesRemoved += 1;
    } catch (error) {
      stats.warnings.push(
        `Could not remove generated split docs page "${page.name}" (${messageFor(error)})`,
      );
    }
  }
}

