function addTextStyleSpec(
  specs,
  key,
  name,
  fontName,
  fontSize,
  lineHeight,
  description,
  textDecoration,
) {
  specs.push({
    key,
    name,
    fontName,
    fontSize,
    lineHeight,
    description:
      description ||
      "Kozmos component typography style. Apply color separately through semantic foreground variables.",
    textDecoration,
  });
}

function textStyleKeyForText(size, weight) {
  return `text.${size}.${weight}`;
}

function textStyleKeyForHeading(level) {
  return `heading.${level}`;
}

async function applyTextStyleToNodeAsync(text, key, stats) {
  const style = activeTextStyleByKey[key];
  const spec = activeTextStyleSpecByKey[key];
  if ((!style || !style.id) && !spec) return false;

  let applied = false;

  if (spec) {
    try {
      text.fontName = spec.fontName;
      text.fontSize = spec.fontSize;
      text.lineHeight = { unit: "PIXELS", value: spec.lineHeight };
      text.letterSpacing = { unit: "PERCENT", value: 0 };
      if ("textDecoration" in text) {
        text.textDecoration = spec.textDecoration || "NONE";
      }
      incrementStat(stats, "textStyleTypographyFieldsApplied");
      applied = true;
    } catch (error) {
      pushUniqueWarning(
        stats,
        `text-style-direct-fields:${key}`,
        `Could not apply typography fields for text style "${key}" (${messageFor(error)}).`,
      );
    }
  }

  if (!style || !style.id) return applied;

  try {
    if (text.setTextStyleIdAsync) {
      await text.setTextStyleIdAsync(style.id);
    } else {
      text.textStyleId = style.id;
    }
    incrementStat(stats, "textStyleBindingsApplied");
    applied = true;
  } catch (error) {
    pushUniqueWarning(
      stats,
      `text-style-bind:${key}`,
      `Could not apply text style "${style.name}" (${messageFor(error)}).`,
    );
  }

  return applied;
}

// Whether a text node carries a text style: its own, or one style across its
// whole range. Shared by the audit's count and by Apply Text Styles, which
// leaves styled text alone.
function textNodeHasTextStyle(node) {
  const directStyleId = node.textStyleId;
  if (
    typeof directStyleId === "string" &&
    directStyleId.length > 0 &&
    directStyleId !== figma.mixed
  ) {
    return true;
  }

  if (
    node.getRangeTextStyleId &&
    typeof node.characters === "string" &&
    node.characters.length > 0
  ) {
    try {
      const rangeStyleId = node.getRangeTextStyleId(0, node.characters.length);
      return (
        typeof rangeStyleId === "string" &&
        rangeStyleId.length > 0 &&
        rangeStyleId !== figma.mixed
      );
    } catch (_error) {
      return false;
    }
  }

  return false;
}

// The variables a text's size and leading are bound to, by field. A literal
// write to either drops its binding in Figma, and applying a style writes them.
function typographyVariableBindings(text) {
  const bindings = {};
  const bound = text && text.boundVariables;
  for (const field of ["fontSize", "lineHeight"]) {
    const value = bound && bound[field];
    const aliases = (Array.isArray(value) ? value : [value]).filter(
      (alias) => alias && alias.id,
    );
    const ids = aliases
      .map((alias) => alias.id)
      .filter((id, index, all) => all.indexOf(id) === index);
    // One variable across the node binds back whole; mixed ranges do not.
    if (ids.length === 1) bindings[field] = ids[0];
  }
  return bindings;
}

async function restoreTypographyVariableBindings(text, bindings, stats) {
  for (const field of Object.keys(bindings)) {
    try {
      const variable = await figma.variables.getVariableByIdAsync(
        bindings[field],
      );
      if (!variable) {
        incrementStat(stats, "typographyBindingsLost");
        pushUniqueWarning(
          stats,
          `typography-binding-missing:${bindings[field]}`,
          `A text's ${field} was bound to a variable the file no longer has (${bindings[field]}); it keeps the style's value.`,
        );
        continue;
      }
      text.setBoundVariable(field, variable);
      incrementStat(stats, "typographyBindingsKept");
    } catch (error) {
      incrementStat(stats, "typographyBindingsLost");
      pushUniqueWarning(
        stats,
        `typography-binding:${field}`,
        `Could not bind a text's ${field} back to its variable (${messageFor(error)}).`,
      );
    }
  }
}

async function applyTextStylesToComponentLibrary() {
  const stats = {
    updated: false,
    componentSetsVisited: 0,
    textNodesVisited: 0,
    textNodesStyled: 0,
    textNodesAlreadyStyled: 0,
    textNodesSkippedInInstances: 0,
    textNodesUnmatched: 0,
    warnings: [],
  };

  await loadButtonFonts(stats);

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  const componentSets = page.findAll((node) => node.type === "COMPONENT_SET");

  for (const componentSet of componentSets) {
    stats.componentSetsVisited += 1;
    const textNodes = componentSet.findAll((node) => node.type === "TEXT");

    for (const text of textNodes) {
      stats.textNodesVisited += 1;

      if (hasAncestorTypeBefore(text, "INSTANCE", componentSet)) {
        stats.textNodesSkippedInInstances += 1;
        continue;
      }

      // A styled text carries the style its painter chose, which a guess
      // from the node's name can miss, and restyling writes its size and
      // leading, dropping their variables: run on the live file on
      // 2026-09-21, this unbound 4,957 texts in 46 sets and set 656 of the
      // pickers' 12/16 texts at 14/20. Only text without a style is styled
      // here, and its bindings are put back; an Update restyles a whole set.
      if (textNodeHasTextStyle(text)) {
        stats.textNodesAlreadyStyled += 1;
        continue;
      }

      const key = inferTextStyleKeyForComponentText(text, componentSet);
      const bindings = typographyVariableBindings(text);
      if (key && (await applyTextStyleToNodeAsync(text, key, stats))) {
        await restoreTypographyVariableBindings(text, bindings, stats);
        stats.textNodesStyled += 1;
      } else {
        stats.textNodesUnmatched += 1;
      }
    }

    // A pill's radius is half of whatever box it ends up in. Restyling text
    // can change that box, so the pills are resolved again here rather than
    // left at the value the painter computed for a smaller one.
    resolvePillRadii(componentSet, stats);
  }

  stats.updated = true;
  stats.message = `Applied text styles to ${stats.textNodesStyled} component text node(s) that had none; ${stats.textNodesAlreadyStyled} styled node(s) left as drawn.`;
  return stats;
}

function hasAncestorTypeBefore(node, type, boundary) {
  let parent = node.parent;
  while (parent && parent !== boundary) {
    if (parent.type === type) return true;
    parent = parent.parent;
  }
  return false;
}

function nearestAncestorOfTypeBefore(node, type, boundary) {
  let parent = node.parent;
  while (parent && parent !== boundary) {
    if (parent.type === type) return parent;
    parent = parent.parent;
  }
  return null;
}

function textStyleKeyForNavbarText(textName) {
  if (textName === "Logo Text") return "navbarLogo";
  if (textName === "Context Label Text") return "sidebarSection";
  if (textName === "Context Text") return "navbarItem";
  if (textName === "Primary Action Text" || textName === "Action Text") {
    return "navbarAction";
  }
  if (/^Item \d+ Text$/.test(textName)) return "navigationItem";
  return null;
}

function textStyleKeyForSidebarText(textName, component) {
  if (textName === "Title Text") return "sidebarTitle";
  if (textName === "Section Text") return "sidebarSection";
  if (textName === "Footer Text") return "sidebarItem";

  const props =
    component && component.name
      ? parseSidebarVariantName(component.name)
      : null;
  const navigationKey =
    props && props.content === "Rail" ? "navigationItemRail" : "navigationItem";
  if (/^Item \d+ Text$/.test(textName)) return navigationKey;
  if (textName === "Tool Text" || textName === "Settings Text") {
    return navigationKey;
  }
  return null;
}

function textStyleKeyForNavigationItemText(component, textName) {
  // The badge is drawn with the sidebar section's typography — see
  // createNavigationItemBadgeSlot — so the audit must expect that. Expecting
  // the label style restyled every badge to 14/20 under Apply Text Styles,
  // the badge grew from 22x18 to 24x22, and the pill radius resolved for the
  // smaller box was left behind, which the nesting check then reported.
  if (textName === "Badge Text") return "sidebarSection";
  const props =
    component && component.name
      ? parseNavigationItemVariantName(component.name)
      : null;
  if (props && props.placement === "Rail") return "navigationItemRail";
  return "navigationItem";
}

function inferTextStyleKeyForComponentText(text, componentSet) {
  const component = nearestAncestorOfTypeBefore(
    text,
    "COMPONENT",
    componentSet,
  );
  const setName = componentSet.name;
  const textName = text.name;

  if (setName === "Text" && component) {
    const textProps = parseTextVariantName(component.name);
    if (textProps) return textStyleKeyForText(textProps.size, textProps.weight);
  }

  if (setName === "Heading" && component) {
    const headingProps = parseHeadingVariantName(component.name);
    if (headingProps) return textStyleKeyForHeading(headingProps.value);
  }

  if (setName === "Counter" && component) {
    const counterProps = parseCounterVariantName(component.name);
    if (counterProps && counterProps.size === "Small") return "counterSmall";
    if (counterProps) return "counterDefault";
  }

  if (setName === "Chip" && component) {
    const chipProps = parseChipVariantName(component.name);
    if (chipProps && chipProps.size === "Small") return "chipLabelSmall";
    if (chipProps) return "chipLabel";
  }

  if (setName === "SegmentedControl" && component) {
    const segmentedControlProps = parseSegmentedControlVariantName(
      component.name,
    );
    if (segmentedControlProps && segmentedControlProps.size === "Small") {
      return "segmentedControlLabelSmall";
    }
    if (segmentedControlProps) return "segmentedControlLabel";
  }

  if (setName === "Button") return "buttonLabel";
  if (setName === "Badge") return "badgeLabel";
  if (setName === "Link") return "linkText";
  if (setName === "Label") return "labelText";
  if (setName === "Box") return "boxText";
  if (setName === "Container") return "containerText";
  if (setName === "Breadcrumb") return "breadcrumbItem";
  if (setName === "Pagination" && component) {
    const paginationProps = parsePaginationVariantName(component.name);
    if (paginationProps && paginationProps.size === "Small") {
      return "paginationLabelSmall";
    }
    if (paginationProps) return "paginationLabel";
  }
  if (setName === "Stepper") {
    return textName === "Step Number" ? "fieldText" : "fieldMeta";
  }
  if (setName === "Accordion") {
    return textName === "Trigger Text"
      ? "accordionTrigger"
      : "accordionContent";
  }
  if (setName === "BottomNavigation") return "fieldMeta";
  if (setName === "NavigationItem") {
    return textStyleKeyForNavigationItemText(component, textName);
  }
  if (setName === "Navbar") {
    return textStyleKeyForNavbarText(textName);
  }
  if (setName === "Sidebar") {
    return textStyleKeyForSidebarText(textName, component);
  }
  if (setName === "Tabs") return "tabsTrigger";
  if (setName === "Tooltip") return "tooltipContent";
  if (setName === "Avatar") return "avatarFallback";
  if (setName === "Alert") {
    return textName === "Title" ? "alertTitle" : "alertDescription";
  }
  if (setName === "EmptyState") {
    return textName === "Title Text"
      ? "emptyStateTitle"
      : "emptyStateDescription";
  }
  if (setName === "Card") {
    if (textName === "Title Text") return "cardTitle";
    if (textName === "Description Text") return "cardDescription";
    return "cardBody";
  }
  if (setName === "List") return "listItem";
  if (
    setName === "Tree" ||
    setName === "TreeItem" ||
    setName === "TreeParentItem" ||
    setName === "TreeChildItem"
  ) {
    // A row's count is drawn with the Counter's small typography — see
    // createTreeCount — so the audit must expect that, not the row text.
    // Expecting treeItem here flagged every parent count as stale, 96 of
    // them, and an Update could never clear it because the painter and the
    // expectation disagreed with each other.
    if (/Count Text$/.test(textName)) return "counterSmall";
    return "treeItem";
  }
  if (setName === "Table") {
    if (/^Header \d+ Text$/.test(textName)) return "tableHeader";
    return "tableCell";
  }
  if (setName === "Timeline") {
    if (/^Item \d+ Time$/.test(textName)) return "fieldMeta";
    return "listItem";
  }
  if (setName === "Dialog") {
    if (textName === "Title Text") return "dialogTitle";
    if (textName === "Description Text") return "dialogDescription";
    return "dialogBody";
  }
  if (setName === "Popover") {
    if (textName === "Title Text") return "popoverTitle";
    return "popoverDescription";
  }
  if (setName === "Menu") {
    if (textName === "Shortcut Text") return "menuShortcut";
    if (textName === "Label Text") return "menuItemStrong";
    return "menuItem";
  }
  if (setName === "Toast") {
    if (textName === "Description Text") return "toastDescription";
    return "toastTitle";
  }
  if (setName === "Checkbox" || setName === "Radio" || setName === "Switch") {
    return "controlLabel";
  }
  if (
    setName === "FormField" ||
    setName === "Input" ||
    setName === "PasswordInput" ||
    setName === "NumberInput" ||
    setName === "Textarea" ||
    setName === "Search" ||
    setName === "Select" ||
    setName === "DatePicker" ||
    setName === "DateRangePicker" ||
    setName === "TimePicker" ||
    setName === "FileUpload" ||
    setName === "ColorPicker" ||
    setName === "Slider"
  ) {
    if (textName === "Optional Text") return "fieldMeta";
    // The field painters draw every label-like text with
    // applyFieldLabelTypography: a range's Start and End labels, the
    // calendar's month titles, the required mark inside the label, and
    // FileUpload's browse action (semibold in the code; Medium is the
    // importer's nearest weight). The guess follows the painters, so the
    // audit reports a real drift rather than 160 false ones (2026-09-21).
    if (
      /Label Text$/.test(textName) ||
      /Month Text$/.test(textName) ||
      textName === "Required Mark" ||
      textName === "Browse Text"
    ) {
      return "fieldLabel";
    }
    // The small readouts the painters draw with the 12/16 meta style: the
    // calendar's weekdays, FileUpload's description and file meta, and
    // ColorPicker's channel, alpha, mode and hex values. Guessed as field
    // text, 656 of them were restyled at 14/20 in the live file (2026-09-21).
    if (
      textName === "Weekday Text" ||
      (setName === "FileUpload" &&
        (textName === "Description Text" ||
          /^File Meta Text( \d+)?$/.test(textName))) ||
      (setName === "ColorPicker" &&
        (/ Value Text$/.test(textName) ||
          textName === "Alpha Unit Text" ||
          textName === "Mode Text" ||
          (textName === "Value Text" &&
            Boolean(text.parent) &&
            text.parent.name === "ColorPicker Hex Field")))
    ) {
      return "fieldMeta";
    }
    return "fieldText";
  }

  return null;
}

async function applyButtonLabelTypography(
  label,
  fonts,
  textStyle,
  variableByName,
  stats,
) {
  label.fontName = fonts.medium;
  label.fontSize = 14;
  label.lineHeight = { unit: "PIXELS", value: 20 };
  label.textAutoResize = "WIDTH_AND_HEIGHT";

  if (textStyle && textStyle.id) {
    try {
      if (label.setTextStyleIdAsync) {
        await label.setTextStyleIdAsync(textStyle.id);
      } else {
        label.textStyleId = textStyle.id;
      }
      incrementStat(stats, "textStyleBindingsApplied");
    } catch (error) {
      stats.warnings.push(
        `Could not apply ${BUTTON_LABEL_TEXT_STYLE_NAME} to Button label (${messageFor(error)}).`,
      );
    }
  }

  bindFloatVariable(
    label,
    "fontSize",
    "Button/label/font-size",
    variableByName,
    stats,
  );
  bindFloatVariable(
    label,
    "lineHeight",
    "Button/label/line-height",
    variableByName,
    stats,
  );
}

async function applyTextTypography(
  text,
  size,
  weight,
  fonts,
  variableByName,
  stats,
) {
  const metrics = textMetrics(size);
  text.fontName = textFontForWeight(weight, fonts);
  text.fontSize = metrics.fontSize;
  text.lineHeight = { unit: "PIXELS", value: metrics.lineHeight };
  text.textAutoResize = "WIDTH_AND_HEIGHT";
  await applyTextStyleToNodeAsync(
    text,
    textStyleKeyForText(size, weight),
    stats,
  );

  bindFloatVariable(
    text,
    "fontSize",
    `Text/font-size/${metrics.token}`,
    variableByName,
    stats,
  );
  bindFloatVariable(
    text,
    "lineHeight",
    `Text/line-height/${metrics.token}`,
    variableByName,
    stats,
  );
}

