async function buildChipComponent() {
  const stats = {
    created: false,
    componentSetId: null,
    urlNodeId: null,
    variants: 0,
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  removeStaleGeneratedComponentArtifacts(page, "Chip", stats);

  const existing = findComponentSetOnPage(page, "Chip");
  if (existing) {
    normalizeComponentSetNodeName(existing, "Chip", stats);
    stats.existing = true;
    stats.componentSetId = existing.id;
    stats.urlNodeId = nodeIdForUrl(existing.id);
    stats.message =
      "Chip already exists. Use Update Chip to preserve its node ID.";
    return stats;
  }

  const fonts = await loadButtonFonts(stats);
  await ensureKozmosTextStyles(fonts, stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const components = [];

  let index = 0;
  for (const variant of CHIP_VARIANTS) {
    for (const size of CHIP_SIZES) {
      for (const state of CHIP_STATES) {
        for (const removable of CHIP_REMOVABLE) {
          const component = await createChipVariant({
            variant,
            size,
            state,
            removable,
            variableByName,
            fonts,
            stats,
          });
          component.x = (index % 6) * 180;
          component.y = Math.floor(index / 6) * 76;
          page.appendChild(component);
          components.push(component);
          index += 1;
        }
      }
    }
  }

  const componentSet = figma.combineAsVariants(components, page);
  componentSet.name = "Chip";
  componentSet.x = 80;
  componentSet.y = 1600;
  componentSet.setSharedPluginData(RUN_NAMESPACE, "kind", "component-set");
  componentSet.setSharedPluginData(RUN_NAMESPACE, "build", PLUGIN_BUILD);
  componentSet.setSharedPluginData(RUN_NAMESPACE, "component", "Chip");
  applyComponentSetDescription(componentSet, "Chip", false, [
    "Kozmos Chip component set generated from React Chip API.",
    "Variant maps to Chip.variant.",
    "Size maps to Chip.size.",
    "State maps to selected and disabled props in Code Connect.",
    "Removable maps to the presence of Chip.onRemove.",
    "Label Text maps to Chip children in Code Connect.",
    "Focus follows the React focus-visible ring.",
  ]);
  clearComponentSetContainerFill(componentSet);

  stats.created = true;
  stats.componentSetId = componentSet.id;
  stats.urlNodeId = nodeIdForUrl(componentSet.id);
  stats.variants = components.length;
  normalizeComponentSetVariantProperties(
    componentSet,
    expectedVariantAxesForComponentSetName(componentSet.name),
    stats,
  );
  configureChipProperties(componentSet, stats);
  return stats;
}

