async function updateColorPickerComponent() {
  const stats = {
    updated: false,
    componentSetId: null,
    urlNodeId: null,
    variantsUpdated: 0,
    variantsCreated: 0,
    variantsMissing: 0,
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  removeStaleGeneratedComponentArtifacts(page, "ColorPicker", stats);

  const existing = findComponentSetOnPage(page, "ColorPicker");
  if (!existing || existing.type !== "COMPONENT_SET") {
    stats.message = "ColorPicker was not found. Run Build ColorPicker first.";
    return stats;
  }
  normalizeComponentSetNodeName(existing, "ColorPicker", stats);

  const fonts = await loadButtonFonts(stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const seenKeys = {};

  existing.setSharedPluginData(RUN_NAMESPACE, "kind", "component-set");
  existing.setSharedPluginData(RUN_NAMESPACE, "build", PLUGIN_BUILD);
  existing.setSharedPluginData(RUN_NAMESPACE, "component", "ColorPicker");
  applyComponentSetDescription(existing, "ColorPicker", true, [
    "Kozmos ColorPicker component set generated from React ColorPicker API.",
    "State maps to focus, disabled, and readOnly props in Code Connect.",
    "Status maps to validation tone: default, error, warning, and success.",
    "Content maps to closed field and open picker popover anatomy examples.",
    "Format maps to ColorPicker.format and controls whether HEX, RGB, or HSL inputs are visible.",
    "Label Text maps to ColorPicker.label.",
    "Value Text maps to the selected color value in Code Connect examples.",
    "Preset swatches represent ColorPicker.presets; product code supplies accessible names.",
    "Focus follows the React focus-visible ring; documented in metadata for v1.",
    "Updated in place to preserve the Code Connect node ID.",
  ]);
  clearComponentSetContainerFill(existing);

  for (const child of existing.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseColorPickerVariantName(child.name);
    if (!props) {
      stats.warnings.push(
        `Skipped unrecognized ColorPicker variant "${child.name}".`,
      );
      continue;
    }

    seenKeys[
      `${props.state}/${props.status}/${props.content}/${props.format}`
    ] = true;
    await updateColorPickerVariant(child, {
      state: props.state,
      status: props.status,
      content: props.content,
      format: props.format,
      variableByName,
      fonts,
      stats,
    });
    stats.variantsUpdated += 1;
  }

  for (const state of COLOR_PICKER_STATES) {
    for (const status of COLOR_PICKER_STATUSES) {
      for (const content of COLOR_PICKER_CONTENT) {
        for (const format of COLOR_PICKER_FORMATS) {
          const key = `${state}/${status}/${content}/${format}`;
          if (seenKeys[key]) continue;

          const component = await createColorPickerVariant({
            state,
            status,
            content,
            format,
            variableByName,
            fonts,
            stats,
          });
          existing.appendChild(component);
          seenKeys[key] = true;
          stats.variantsCreated += 1;
        }
      }
    }
  }

  layoutColorPickerVariants(existing);

  stats.updated = true;
  stats.componentSetId = existing.id;
  stats.urlNodeId = nodeIdForUrl(existing.id);
  normalizeComponentSetVariantProperties(
    existing,
    expectedVariantAxesForComponentSetName(existing.name),
    stats,
  );
  configureColorPickerProperties(existing, stats);
  return stats;
}

