async function buildStateStatusComponent(config) {
  const stats = {
    created: false,
    componentSetId: null,
    urlNodeId: null,
    variants: 0,
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  removeStaleGeneratedComponentArtifacts(page, config.componentName, stats);

  const existing = findComponentSetOnPage(page, config.componentSetName);
  if (existing) {
    normalizeComponentSetNodeName(existing, config.componentSetName, stats);
    const duplicateCount = removeDuplicateGeneratedComponentSetsForName(
      page,
      config.componentSetName,
      existing,
      stats,
    );
    stats.existing = true;
    stats.componentSetId = existing.id;
    stats.urlNodeId = nodeIdForUrl(existing.id);
    stats.message = `${config.componentSetName} already exists. Use Update ${config.componentName} to preserve its node ID.`;
    if (duplicateCount > 0) {
      await reorganizeAfterGeneratedComponentMutation(stats);
    }
    return stats;
  }

  const fonts = await loadButtonFonts(stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const components = [];
  const types = config.types || [null];

  for (let stateIndex = 0; stateIndex < config.states.length; stateIndex += 1) {
    const state = config.states[stateIndex];
    for (
      let statusIndex = 0;
      statusIndex < config.statuses.length;
      statusIndex += 1
    ) {
      const status = config.statuses[statusIndex];
      for (let typeIndex = 0; typeIndex < types.length; typeIndex += 1) {
        const type = types[typeIndex];
        const component = await config.createVariant({
          state,
          status,
          type,
          variableByName,
          fonts,
          stats,
        });
        component.x = (statusIndex * types.length + typeIndex) * config.xStep;
        component.y = stateIndex * config.yStep;
        page.appendChild(component);
        components.push(component);
      }
    }
  }

  const componentSet = figma.combineAsVariants(components, page);
  componentSet.name = config.componentSetName;
  componentSet.x = config.x;
  componentSet.y = config.y;
  componentSet.setSharedPluginData(RUN_NAMESPACE, "kind", "component-set");
  componentSet.setSharedPluginData(RUN_NAMESPACE, "build", PLUGIN_BUILD);
  componentSet.setSharedPluginData(
    RUN_NAMESPACE,
    "component",
    config.componentName,
  );
  applyComponentSetDescription(
    componentSet,
    config.componentSetName,
    false,
    config.description,
  );
  clearComponentSetContainerFill(componentSet);

  stats.created = true;
  stats.componentSetId = componentSet.id;
  stats.urlNodeId = nodeIdForUrl(componentSet.id);
  stats.variants = components.length;
  normalizeComponentSetVariantProperties(
    componentSet,
    expectedVariantAxesForComponentSetName(componentSet.name),
    stats,
  );
  await config.configureProperties(componentSet, stats, variableByName);
  reportUnboundComponentProperties(componentSet, stats);
  await reorganizeAfterGeneratedComponentMutation(stats);
  return stats;
}

async function updateStateStatusComponent(config) {
  const stats = {
    updated: false,
    componentSetId: null,
    urlNodeId: null,
    variantsUpdated: 0,
    variantsCreated: 0,
    variantsMissing: 0,
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  removeStaleGeneratedComponentArtifacts(page, config.componentName, stats);

  const existing = findComponentSetOnPage(page, config.componentSetName);
  if (!existing || existing.type !== "COMPONENT_SET") {
    stats.message = `${config.componentSetName} was not found. Run Build ${config.componentName} first.`;
    return stats;
  }
  normalizeComponentSetNodeName(existing, config.componentSetName, stats);
  removeDuplicateGeneratedComponentSetsForName(
    page,
    config.componentSetName,
    existing,
    stats,
  );

  const fonts = await loadButtonFonts(stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const seenKeys = {};
  const types = config.types || [null];

  existing.setSharedPluginData(RUN_NAMESPACE, "kind", "component-set");
  existing.setSharedPluginData(RUN_NAMESPACE, "build", PLUGIN_BUILD);
  existing.setSharedPluginData(
    RUN_NAMESPACE,
    "component",
    config.componentName,
  );
  applyComponentSetDescription(
    existing,
    config.componentSetName,
    true,
    config.description,
  );
  clearComponentSetContainerFill(existing);

  for (const child of existing.children) {
    if (child.type !== "COMPONENT") continue;

    const props = config.parseVariantName(child.name);
    if (!props) {
      stats.warnings.push(
        `Skipped unrecognized ${config.componentName} variant "${child.name}".`,
      );
      continue;
    }

    const type = props.type || null;
    seenKeys[stateStatusComponentKey(props.state, props.status, type)] = true;
    await config.updateVariant(child, {
      state: props.state,
      status: props.status,
      type,
      variableByName,
      fonts,
      stats,
    });
    stats.variantsUpdated += 1;
  }

  for (const state of config.states) {
    for (const status of config.statuses) {
      for (const type of types) {
        const key = stateStatusComponentKey(state, status, type);
        if (seenKeys[key]) continue;

        const component = await config.createVariant({
          state,
          status,
          type,
          variableByName,
          fonts,
          stats,
        });
        existing.appendChild(component);
        seenKeys[key] = true;
        stats.variantsCreated += 1;
      }
    }
  }

  layoutStateStatusVariants(existing, config);

  stats.updated = true;
  stats.componentSetId = existing.id;
  stats.urlNodeId = nodeIdForUrl(existing.id);
  normalizeComponentSetVariantProperties(
    existing,
    expectedVariantAxesForComponentSetName(existing.name),
    stats,
  );
  await config.configureProperties(existing, stats, variableByName);
  reportUnboundComponentProperties(existing, stats);
  // These updaters sync variants and properties and never looked at an icon's
  // paint, so a slot orphaned by an earlier redraw stayed black through every
  // Update. Repair from what each slot already records.
  repairIconSlotTints(existing, variableByName, stats);
  await reorganizeAfterGeneratedComponentMutation(stats);
  return stats;
}

function layoutStateStatusVariants(componentSet, config) {
  if (!componentSet || !componentSet.children) return;

  const types = config.types || [null];
  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = config.parseVariantName(child.name);
    if (!props) continue;

    const stateIndex = config.states.indexOf(props.state);
    const statusIndex = config.statuses.indexOf(props.status);
    const typeIndex = types.indexOf(props.type || null);
    child.x =
      (statusIndex * types.length + Math.max(0, typeIndex)) * config.xStep;
    child.y = stateIndex * config.yStep;
  }
}

function stateStatusComponentKey(state, status, type) {
  return type ? `${state}/${status}/${type}` : `${state}/${status}`;
}

async function buildPlannedMatrixComponent(config) {
  const stats = {
    created: false,
    componentSetId: null,
    urlNodeId: null,
    variants: 0,
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  removeStaleGeneratedComponentArtifacts(page, config.componentName, stats);

  const existing = findComponentSetOnPage(page, config.componentSetName);
  if (existing) {
    normalizeComponentSetNodeName(existing, config.componentSetName, stats);
    const duplicateCount = removeDuplicateGeneratedComponentSetsForName(
      page,
      config.componentSetName,
      existing,
      stats,
    );
    stats.existing = true;
    stats.componentSetId = existing.id;
    stats.urlNodeId = nodeIdForUrl(existing.id);
    stats.message = `${config.componentSetName} already exists. Use Update ${config.componentName} to preserve its node ID.`;
    if (duplicateCount > 0) {
      await reorganizeAfterGeneratedComponentMutation(stats);
    }
    return stats;
  }

  const fonts = await loadButtonFonts(stats);
  await ensureKozmosTextStyles(fonts, stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const components = [];

  for (const props of config.combinations()) {
    const component = await config.createVariant({
      props,
      variableByName,
      fonts,
      stats,
    });
    page.appendChild(component);
    components.push(component);
  }

  const componentSet = figma.combineAsVariants(components, page);
  componentSet.name = config.componentSetName;
  componentSet.x = config.x;
  componentSet.y = config.y;
  componentSet.setSharedPluginData(RUN_NAMESPACE, "kind", "component-set");
  componentSet.setSharedPluginData(RUN_NAMESPACE, "build", PLUGIN_BUILD);
  componentSet.setSharedPluginData(
    RUN_NAMESPACE,
    "component",
    config.componentName,
  );
  applyComponentSetDescription(
    componentSet,
    config.componentSetName,
    false,
    config.description,
  );
  clearComponentSetContainerFill(componentSet);

  if (typeof config.layoutVariants === "function") {
    config.layoutVariants(componentSet);
  }

  stats.created = true;
  stats.componentSetId = componentSet.id;
  stats.urlNodeId = nodeIdForUrl(componentSet.id);
  stats.variants = components.length;
  normalizeComponentSetVariantProperties(
    componentSet,
    expectedVariantAxesForComponentSetName(componentSet.name),
    stats,
  );
  await config.configureProperties(componentSet, stats, variableByName);
  reportUnboundComponentProperties(componentSet, stats);
  runGeneratedComponentPostUpdateMaintenance(
    componentSet,
    config.componentName,
    stats,
  );
  await reorganizeAfterGeneratedComponentMutation(stats);
  await runGeneratedComponentPostLayoutMaintenance({
    componentName: config.componentName,
    componentSetName: config.componentSetName,
    stats,
  });
  return stats;
}

async function updatePlannedMatrixComponent(config) {
  const stats = {
    updated: false,
    componentSetId: null,
    urlNodeId: null,
    variantsUpdated: 0,
    variantsCreated: 0,
    variantsRemoved: 0,
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  removeStaleGeneratedComponentArtifacts(page, config.componentName, stats);

  const existing = findComponentSetOnPage(page, config.componentSetName);
  if (!existing || existing.type !== "COMPONENT_SET") {
    stats.message = `${config.componentSetName} was not found. Run Build ${config.componentName} first.`;
    return stats;
  }
  normalizeComponentSetNodeName(existing, config.componentSetName, stats);
  removeDuplicateGeneratedComponentSetsForName(
    page,
    config.componentSetName,
    existing,
    stats,
  );

  const fonts = await loadButtonFonts(stats);
  await ensureKozmosTextStyles(fonts, stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const seenKeys = {};

  existing.setSharedPluginData(RUN_NAMESPACE, "kind", "component-set");
  existing.setSharedPluginData(RUN_NAMESPACE, "build", PLUGIN_BUILD);
  existing.setSharedPluginData(
    RUN_NAMESPACE,
    "component",
    config.componentName,
  );
  applyComponentSetDescription(
    existing,
    config.componentSetName,
    true,
    config.description,
  );
  clearComponentSetContainerFill(existing);

  const desiredKeys = {};
  if (config.removeUnexpectedVariants || config.removeDuplicateVariantKeys) {
    for (const props of config.combinations()) {
      desiredKeys[config.keyForProps(props)] = true;
    }
  }

  // Removals are collected and applied after the creation pass, never during
  // it. Figma destroys a component set that has no children, so removing every
  // variant before creating the replacements takes the set with it — and with
  // it the node ID Code Connect pins. That is what happened to MapControlButton
  // on 2026-09-05: six variants failed to parse, all six were removed, and the
  // set was gone before the first replacement could be appended.
  const pendingRemoval = [];
  const existingChildren = Array.from(existing.children || []);
  const variantTotal = existingChildren.length;
  for (const child of existingChildren) {
    if (child.type !== "COMPONENT") continue;

    const props = config.parseVariantName(child.name);
    if (!props) {
      if (config.removeUnexpectedVariants) {
        pendingRemoval.push({ node: child, kind: "unrecognized" });
        continue;
      }
      stats.warnings.push(
        `Skipped unrecognized ${config.componentName} variant "${child.name}".`,
      );
      continue;
    }

    const key = config.keyForProps(props);
    if (config.removeUnexpectedVariants && !desiredKeys[key]) {
      pendingRemoval.push({ node: child, kind: "stale" });
      continue;
    }

    if (seenKeys[key]) {
      if (config.removeDuplicateVariantKeys) {
        pendingRemoval.push({ node: child, kind: "duplicate" });
        continue;
      }
      stats.warnings.push(
        `Skipped duplicate ${config.componentName} variant "${child.name}".`,
      );
      continue;
    }

    seenKeys[key] = true;
    await reportSetProgress(
      config.componentSetName,
      `variant ${stats.variantsUpdated + 1} of ${variantTotal}`,
      stats.variantsUpdated === 0,
    );
    await config.updateVariant(child, {
      props,
      variableByName,
      fonts,
      stats,
    });
    stats.variantsUpdated += 1;
  }

  for (const props of config.combinations()) {
    const key = config.keyForProps(props);
    if (seenKeys[key]) continue;

    await reportSetProgress(
      config.componentSetName,
      `new variant ${stats.variantsCreated + 1}`,
      stats.variantsCreated === 0,
    );
    const component = await config.createVariant({
      props,
      variableByName,
      fonts,
      stats,
    });
    existing.appendChild(component);
    seenKeys[key] = true;
    stats.variantsCreated += 1;
  }

  // Safe now: every replacement exists, so the set cannot be emptied.
  for (const entry of pendingRemoval) {
    try {
      entry.node.remove();
      stats.variantsRemoved += 1;
    } catch (error) {
      stats.warnings.push(
        `Could not remove ${entry.kind} ${config.componentName} variant "${entry.node.name}" (${messageFor(error)}).`,
      );
    }
  }

  if (typeof config.layoutVariants === "function") {
    config.layoutVariants(existing);
  }

  stats.updated = true;
  stats.componentSetId = existing.id;
  stats.urlNodeId = nodeIdForUrl(existing.id);
  await reportSetProgress(config.componentSetName, "variant properties", true);
  normalizeComponentSetVariantProperties(
    existing,
    expectedVariantAxesForComponentSetName(existing.name),
    stats,
  );
  await reportSetProgress(
    config.componentSetName,
    "component properties",
    true,
  );
  await config.configureProperties(existing, stats, variableByName);
  reportUnboundComponentProperties(existing, stats);
  // These updaters sync variants and properties and never looked at an icon's
  // paint, so a slot orphaned by an earlier redraw stayed black through every
  // Update. Repair from what each slot already records.
  repairIconSlotTints(existing, variableByName, stats);
  await reportSetProgress(config.componentSetName, "maintenance", true);
  runGeneratedComponentPostUpdateMaintenance(
    existing,
    config.componentName,
    stats,
  );
  await reportSetProgress(config.componentSetName, "layout", true);
  await reorganizeAfterGeneratedComponentMutation(stats);
  await runGeneratedComponentPostLayoutMaintenance({
    componentName: config.componentName,
    componentSetName: config.componentSetName,
    stats,
  });
  return stats;
}

function parseVariantValueMap(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  return values;
}

