function tagVariantCombinations() {
  const combinations = [];
  for (const variant of TAG_VARIANTS) {
    for (const removable of TAG_REMOVABLE) {
      combinations.push({ variant, removable });
    }
  }
  return combinations;
}

function tagVariantKey(props) {
  return `${props.variant}/${props.removable}`;
}

function parseTagVariantName(name) {
  const values = parseVariantValueMap(name);
  if (
    TAG_VARIANTS.indexOf(values.Variant) === -1 ||
    TAG_REMOVABLE.indexOf(values.Removable) === -1
  ) {
    return null;
  }
  return { variant: values.Variant, removable: values.Removable };
}

