function treeParentItemVariantCombinations() {
  return treeItemVariantCombinationsForType("Parent");
}

function treeChildItemVariantCombinations() {
  return treeItemVariantCombinationsForType("Child");
}

function treeItemVariantCombinations() {
  const combinations = [];
  for (const type of TREE_ITEM_TYPES) {
    const variants = treeItemVariantCombinationsForType(type);
    for (const variant of variants) combinations.push(variant);
  }
  return combinations;
}

function treeItemVariantCombinationsForType(type) {
  const combinations = [];
  for (const content of TREE_CONTENT) {
    const expandedOptions = type === "Parent" ? TREE_EXPANDED : ["False"];
    for (const expanded of expandedOptions) {
      for (const depth of TREE_ITEM_DEPTHS) {
        for (const density of TREE_DENSITIES) {
          for (const state of TREE_STATES) {
            combinations.push({
              type,
              content,
              expanded,
              depth,
              density,
              state,
            });
          }
        }
      }
    }
  }
  return combinations;
}

function treeItemVariantKey(props) {
  return `${props.type}/${props.content}/${props.expanded}/${props.depth}/${props.density}/${props.state}`;
}

function treeStandaloneItemVariantKey(props) {
  return `${props.content}/${props.expanded}/${props.depth}/${props.density}/${props.state}`;
}

function parseTreeItemVariantName(name) {
  const values = parseVariantValueMap(name);
  const expanded = values.Expanded || "False";
  const type = normalizeTreeItemType(values.Type);
  const state = normalizeTreeState(values.State);
  if (
    TREE_ITEM_TYPES.indexOf(type) === -1 ||
    TREE_CONTENT.indexOf(values.Content) === -1 ||
    TREE_EXPANDED.indexOf(expanded) === -1 ||
    (type === "Child" && expanded !== "False") ||
    TREE_ITEM_DEPTHS.indexOf(values.Depth) === -1 ||
    TREE_DENSITIES.indexOf(values.Density) === -1 ||
    TREE_STATES.indexOf(state) === -1
  ) {
    return null;
  }
  return {
    type,
    content: values.Content,
    expanded,
    depth: values.Depth,
    density: values.Density,
    state,
  };
}

function parseTreeParentItemVariantName(name) {
  return parseTreeStandaloneItemVariantName(name, "Parent");
}

function parseTreeChildItemVariantName(name) {
  return parseTreeStandaloneItemVariantName(name, "Child");
}

function parseTreeStandaloneItemVariantName(name, type) {
  const values = parseVariantValueMap(name);
  const content = values.Content || "Basic";
  const expanded = type === "Parent" ? values.Expanded || "False" : "False";
  const depth = values.Depth || "0";
  const density = values.Density || "Default";
  const state = normalizeTreeState(values.State);
  const legacyType = values.Type ? normalizeTreeItemType(values.Type) : type;

  if (
    legacyType !== type ||
    TREE_CONTENT.indexOf(content) === -1 ||
    TREE_EXPANDED.indexOf(expanded) === -1 ||
    TREE_ITEM_DEPTHS.indexOf(depth) === -1 ||
    TREE_DENSITIES.indexOf(density) === -1 ||
    TREE_STATES.indexOf(state) === -1
  ) {
    return null;
  }

  return {
    type,
    content,
    expanded,
    depth,
    density,
    state,
  };
}

function normalizeTreeState(value) {
  if (value === "Default") return "Idle";
  if (TREE_STATES.indexOf(value) !== -1) return value;
  return value || "Idle";
}

function normalizeTreeItemType(value) {
  if (value === "Branch") return "Parent";
  if (value === "Leaf") return "Child";
  if (TREE_ITEM_TYPES.indexOf(value) !== -1) return value;
  return value || "Parent";
}

function timelineVariantCombinations() {
  const combinations = [];
  for (const content of TIMELINE_CONTENT) {
    for (const density of TIMELINE_DENSITIES) {
      combinations.push({ content, density });
    }
  }
  return combinations;
}

function timelineVariantKey(props) {
  return `${props.content}/${props.density}`;
}

function parseTimelineVariantName(name) {
  const values = parseVariantValueMap(name);
  if (
    TIMELINE_CONTENT.indexOf(values.Content) === -1 ||
    TIMELINE_DENSITIES.indexOf(values.Density) === -1
  ) {
    return null;
  }
  return { content: values.Content, density: values.Density };
}

async function createTagVariant({ props, variableByName, fonts, stats }) {
  const component = figma.createComponent();
  await updateTagVariant(component, {
    props,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

async function updateTagVariant(
  component,
  { props, variableByName, fonts, stats },
) {
  const config = tagConfig(props.variant);
  const removable = props.removable === "True";

  component.name = `Variant=${props.variant}, Removable=${props.removable}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "AUTO";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = 6;
  component.paddingLeft = 12;
  component.paddingRight = removable ? 8 : 12;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(64, 32);
  component.cornerRadius = KOZMOS_RADIUS.pill;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Tag");

  component.fills = config.background
    ? [
        paintFromVariable(
          config.background,
          config.backgroundFallback,
          variableByName,
          stats,
        ),
      ]
    : [];
  component.strokes = config.stroke
    ? [
        paintFromVariable(
          config.stroke,
          config.strokeFallback,
          variableByName,
          stats,
        ),
      ]
    : [];
  component.strokeWeight = config.stroke ? 1 : 0;

  removeDirectChildren(component);

  const label = figma.createText();
  label.name = "Label Text";
  await applyBadgeLabelTypography(label, fonts, variableByName, stats);
  label.characters = tagLabelText(props.variant);
  label.fills = [
    paintFromVariable(
      config.foreground,
      config.foregroundFallback,
      variableByName,
      stats,
    ),
  ];
  label.textAlignVertical = "CENTER";
  setTextAutoResize(label, "WIDTH_AND_HEIGHT");
  component.appendChild(label);
  setHugChildSizing(label);

  if (removable) {
    const icon = await createFixedIconInstance(
      "x-close",
      config.foreground,
      config.foregroundFallback,
      variableByName,
      stats,
      14,
    );
    icon.name = "Remove Icon";
    component.appendChild(icon);
    setHugChildSizing(icon);
  }
}

