async function createNavigationItemNestedInstance({
  content,
  density,
  fallbackName,
  iconName,
  label,
  placement,
  role,
  state,
  textNodeName,
  variableByName,
  fonts,
  stats,
}) {
  const created = await createNestedComponentInstance({
    componentSetName: "NavigationItem",
    variantProperties: {
      Placement: placement,
      Content: content,
      Density: density,
      State: state,
    },
    name: fallbackName,
    role,
    stats,
  });

  if (created) {
    const instance = created.instance;
    setInstanceTextProperty(
      instance,
      created.componentSet,
      "Label Text",
      label,
      stats,
    );
    if (content !== "Label" && iconName) {
      const iconComponent = await findKozmosIconSourceComponent(iconName);
      setInstanceSwapProperty(
        instance,
        created.componentSet,
        "Leading Icon",
        iconComponent ? iconComponent.id : null,
        stats,
      );
    }
    markNestedComponentInstance(instance, "NavigationItem", role);
    return instance;
  }

  const frame = figma.createFrame();
  frame.name = fallbackName;
  frame.layoutMode = placement === "Rail" ? "VERTICAL" : "HORIZONTAL";
  frame.primaryAxisSizingMode = placement === "Top" ? "AUTO" : "FIXED";
  frame.counterAxisSizingMode = "FIXED";
  frame.primaryAxisAlignItems = placement === "Rail" ? "CENTER" : "MIN";
  frame.counterAxisAlignItems = "CENTER";
  frame.itemSpacing = placement === "Rail" ? 4 : 8;
  frame.paddingLeft = placement === "Rail" ? 8 : 12;
  frame.paddingRight = placement === "Rail" ? 8 : 12;
  frame.paddingTop = placement === "Rail" ? 8 : 0;
  frame.paddingBottom = placement === "Rail" ? 8 : 0;
  frame.resizeWithoutConstraints(
    placement === "Rail" ? 72 : 112,
    placement === "Rail" ? 72 : 44,
  );
  frame.cornerRadius = KOZMOS_RADIUS.control;
  frame.clipsContent = false;
  frame.fills =
    state === "Selected"
      ? [
          paintFromVariable(
            "Colors/background/100",
            "#E3E4E8",
            variableByName,
            stats,
          ),
        ]
      : [];
  frame.strokes = [];
  frame.setSharedPluginData(RUN_NAMESPACE, "kind", "missing-nested-component");

  if (content !== "Label") {
    const icon = await createFixedIconInstance(
      iconName || "home-line",
      state === "Selected" ? "Colors/theme/500" : "Colors/foreground/400",
      state === "Selected" ? "#135BEC" : "#5E6575",
      variableByName,
      stats,
      placement === "Rail" ? 20 : 18,
    );
    icon.name = `${textNodeName} Icon`;
    frame.appendChild(icon);
    setHugChildSizing(icon);
  }

  if (content !== "Icon Only") {
    const text = figma.createText();
    text.name = textNodeName;
    await applyNavigationItemTypography(
      text,
      fonts,
      placement,
      variableByName,
      stats,
    );
    text.characters = label;
    text.fills = [
      paintFromVariable(
        state === "Selected" ? "Colors/theme/700" : "Colors/foreground/0",
        state === "Selected" ? "#0B3E9D" : "#000000",
        variableByName,
        stats,
      ),
    ];
    text.textAlignHorizontal = placement === "Rail" ? "CENTER" : "LEFT";
    text.textAlignVertical = "CENTER";
    text.resizeWithoutConstraints(placement === "Rail" ? 56 : 80, 20);
    setTextAutoResize(text, "TRUNCATE");
    frame.appendChild(text);
    if (placement === "Side") {
      setHorizontalStackFillHugChildSizing(text);
    } else {
      setHugChildSizing(text);
    }
  }

  if (stats && stats.warnings) {
    stats.warnings.push(
      `${fallbackName}: build NavigationItem before updating Navbar or Sidebar to use live nested navigation rows.`,
    );
  }
  return frame;
}

