async function updateSidebarVariant(
  component,
  { props, variableByName, fonts, stats },
) {
  const isRail = props.content === "Rail";
  const hasTools = props.content === "Tools";
  component.name = `Content=${props.content}`;
  component.layoutMode = "VERTICAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "MIN";
  component.counterAxisAlignItems = isRail ? "CENTER" : "MIN";
  component.itemSpacing = isRail ? 12 : 16;
  component.paddingLeft = isRail ? 4 : 16;
  component.paddingRight = isRail ? 4 : 16;
  component.paddingTop = 16;
  component.paddingBottom = 16;
  component.resizeWithoutConstraints(
    isRail ? SIDEBAR_RAIL_WIDTH : SIDEBAR_DEFAULT_WIDTH,
    SIDEBAR_DEFAULT_HEIGHT,
  );
  component.cornerRadius = KOZMOS_RADIUS.none;
  component.clipsContent = false;
  component.fills = [
    paintFromVariable("Surface/0", "#FFFFFF", variableByName, stats),
  ];
  component.strokes = [
    paintFromVariable("Border/Subtle", "#C7CAD1", variableByName, stats),
  ];
  component.strokeWeight = 1;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Sidebar");

  bindSizeVariables(
    component,
    isRail ? "Sidebar/width/rail" : "Sidebar/width/default",
    "Sidebar/height/default",
    variableByName,
    stats,
  );
  bindFloatVariable(
    component,
    "paddingLeft",
    isRail ? "Sidebar/padding/x/rail" : "Sidebar/padding/x",
    variableByName,
    stats,
  );
  bindFloatVariable(
    component,
    "paddingRight",
    isRail ? "Sidebar/padding/x/rail" : "Sidebar/padding/x",
    variableByName,
    stats,
  );

  const reusableSlots = extractReusableSlotsByName(
    component,
    requiredSidebarSlotNamesForContent(props.content),
    stats,
    "Sidebar",
  );
  removeDirectChildrenExceptMany(component, Object.values(reusableSlots));

  const header = await createSidebarHeaderSlot({
    component,
    compact: isRail,
    reusableSlot: reusableSlotNamed(reusableSlots, "Header Slot"),
    variableByName,
    fonts,
    stats,
  });
  component.appendChild(header);
  setVerticalStackChildSizing(header);

  const navigation = await createSidebarNavigationSlot({
    component,
    content: props.content,
    reusableSlot: reusableSlotNamed(reusableSlots, "Navigation Slot"),
    variableByName,
    fonts,
    stats,
  });
  component.appendChild(navigation);
  setVerticalStackFillChildSizing(navigation);

  if (hasTools) {
    const tools = await createSidebarToolsSlot({
      component,
      reusableSlot: reusableSlotNamed(reusableSlots, "Tools Slot"),
      variableByName,
      fonts,
      stats,
    });
    component.appendChild(tools);
    setVerticalStackChildSizing(tools);
  }

  const footer = await createSidebarFooterSlot({
    component,
    compact: isRail,
    reusableSlot: reusableSlotNamed(reusableSlots, "Footer Slot"),
    variableByName,
    fonts,
    stats,
  });
  component.appendChild(footer);
  setVerticalStackChildSizing(footer);
}

