async function createSidebarNavigationSlot({
  component,
  content,
  reusableSlot,
  variableByName,
  fonts,
  stats,
}) {
  if (content === "Rail") {
    return createSidebarRailNavigationSlot({
      component,
      reusableSlot,
      variableByName,
      fonts,
      stats,
    });
  }

  const shell = createOrReuseShellSlot({
    component,
    reusableSlot,
    ownerName: "Sidebar",
    stats,
    slotName: "Navigation Slot",
    width: SIDEBAR_SLOT_WIDTH,
    height:
      content === "Tools"
        ? SIDEBAR_TOOLS_NAVIGATION_HEIGHT
        : SIDEBAR_NAVIGATION_HEIGHT,
    layoutMode: "VERTICAL",
    itemSpacing: 4,
  });
  const slot = shell.node;
  if (shell.reusedContent) return slot;

  if (content === "Sections") {
    const label = figma.createText();
    label.name = "Section Text";
    await applySidebarSectionTypography(label, fonts, variableByName, stats);
    label.characters = "Navigation";
    label.fills = [
      paintFromVariable(
        "Colors/foreground/400",
        "#5D626F",
        variableByName,
        stats,
      ),
    ];
    label.textAlignVertical = "CENTER";
    label.resizeWithoutConstraints(SIDEBAR_SLOT_WIDTH, 20);
    setTextAutoResize(label, "TRUNCATE");
    slot.appendChild(label);
    setVerticalStackChildSizing(label);
  }

  const rows = [
    {
      name: "Item 1 Text",
      label: "Overview",
      icon: "home-line",
      active: true,
    },
    { name: "Item 2 Text", label: "Explore", icon: "search-md", active: false },
    {
      name: "Item 3 Text",
      label: "Settings",
      icon: "settings-01",
      active: false,
    },
  ];

  for (const row of rows) {
    const item = await createSidebarNavigationRow({
      row,
      variableByName,
      fonts,
      stats,
    });
    slot.appendChild(item);
    setVerticalFixedFillChildSizing(item);
  }

  return slot;
}

