function layoutTreeItemVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;
    const props = parseTreeItemVariantName(child.name);
    if (!props) continue;
    const typeIndex = TREE_ITEM_TYPES.indexOf(props.type);
    const contentIndex = TREE_CONTENT.indexOf(props.content);
    const expandedIndex =
      props.type === "Parent" ? TREE_EXPANDED.indexOf(props.expanded) : 0;
    const depthIndex = TREE_ITEM_DEPTHS.indexOf(props.depth);
    const densityIndex = TREE_DENSITIES.indexOf(props.density);
    const stateIndex = TREE_STATES.indexOf(props.state);

    child.x = (contentIndex * TREE_STATES.length + stateIndex) * 380;
    child.y =
      (((typeIndex * TREE_ITEM_DEPTHS.length + depthIndex) *
        TREE_DENSITIES.length +
        densityIndex) *
        2 +
        expandedIndex) *
      72;
  }

  resizeComponentSetToContainChildren(componentSet);
}

function layoutTreeParentItemVariants(componentSet) {
  layoutStandaloneTreeItemVariants(
    componentSet,
    parseTreeParentItemVariantName,
  );
}

function layoutTreeChildItemVariants(componentSet) {
  layoutStandaloneTreeItemVariants(componentSet, parseTreeChildItemVariantName);
}

function layoutStandaloneTreeItemVariants(componentSet, parseVariantName) {
  if (!componentSet || !componentSet.children) return;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;
    const props = parseVariantName(child.name);
    if (!props) continue;
    const contentIndex = TREE_CONTENT.indexOf(props.content);
    const expandedIndex =
      props.type === "Parent" ? TREE_EXPANDED.indexOf(props.expanded) : 0;
    const depthIndex = TREE_ITEM_DEPTHS.indexOf(props.depth);
    const densityIndex = TREE_DENSITIES.indexOf(props.density);
    const stateIndex = TREE_STATES.indexOf(props.state);

    child.x = (contentIndex * TREE_STATES.length + stateIndex) * 380;
    child.y =
      ((depthIndex * TREE_DENSITIES.length + densityIndex) *
        (props.type === "Parent" ? 2 : 1) +
        expandedIndex) *
      72;
  }

  resizeComponentSetToContainChildren(componentSet);
}

