function configureColorPickerProperties(componentSet, stats) {
  configureLabelTextProperty(componentSet, "Brand color", stats);
  configureNamedTextProperty(
    componentSet,
    "Value Text",
    "Value Text",
    "#135BEC",
    stats,
  );
  // The format label is variant-driven: "Mode Text" reads HEX / HSL / RGB from
  // the Format axis, so a text property beside it could only ever disagree with
  // the variant. "Hex Label Text" is the last survivor of that family and joins
  // the three siblings already deleted here — it is the ColorPicker half of the
  // unbound properties that keep the set out of the published library.
  deleteComponentPropertiesByBaseName(
    componentSet,
    ["Mode Text", "Hue Label Text", "Alpha Label Text", "Hex Label Text"],
    ["TEXT"],
    stats,
  );
  // Same shape as MultiSelect's chip labels: the palette name is rendered by
  // the nested Select instance's own Placeholder Text, so a ColorPicker-level
  // property has nothing it can attach to. The Select is exposed instead.
  deleteComponentPropertiesByBaseName(
    componentSet,
    ["Palette Text"],
    ["TEXT"],
    stats,
  );
  for (const [nodeName, defaultValue] of [
    ["Hue Value Text", "0"],
    ["Saturation Value Text", "0"],
    ["Lightness Value Text", "85"],
    ["Red Value Text", "19"],
    ["Green Value Text", "91"],
    ["Blue Value Text", "236"],
    ["Alpha Value Text", "100"],
    ["Alpha Unit Text", "%"],
  ]) {
    configureNamedTextProperty(
      componentSet,
      nodeName,
      nodeName,
      defaultValue,
      stats,
    );
  }
  configureHelperTextProperty(componentSet, "Choose a color.", stats);
  configureHelperVisibilityProperty(componentSet, stats);
  configureFocusVisibleProperty(componentSet, stats);
}

function configureSliderProperties(componentSet, stats) {
  configureLabelTextProperty(componentSet, "Slider", stats);
  configureFocusVisibleProperty(componentSet, stats);
}

function configureRatingProperties(_componentSet, _stats) {}

function configureStepperProperties(componentSet, stats) {
  for (let index = 1; index <= 4; index += 1) {
    configureNamedTextProperty(
      componentSet,
      `Step ${index} Text`,
      `Step ${index} Text`,
      `Step ${index}`,
      stats,
    );
  }
}

