    parseVariantName: parseFloorSelectorVariantName,
    configureProperties: configureFloorSelectorProperties,
    autoReorganize: true,
    description: FLOOR_SELECTOR_DESCRIPTION.concat([
      "Updated in place to preserve the Code Connect node ID.",
    ]),
