// --- POIDetailPanel --------------------------------------------------------

// The glyph used to be actionLabel.charAt(0), which put a literal "N", "S"
// and "S" on the three buttons -- two of them identical, and all three reading
// as a placeholder someone forgot to fill in. Every other builder here uses a
// real mark, so these do too; the star matches SaveLocationCard's.
const POI_DETAIL_PANEL_ACTION_GLYPHS = {
  Navigate: "→",
  Save: "☆",
  Share: "↗",
};
const POI_DETAIL_PANEL_ACTION_ICONS = {
  Navigate: "navigation-pointer-01",
  Save: "bookmark",
  Share: "share-01",
};

async function createPOIDetailPanelVariant(args) {
  const component = figma.createComponent();
  await updatePOIDetailPanelVariant(component, args);
  return component;
}

function parsePOIDetailPanelVariantName(name) {
  return productSdkVariantValues(
    name,
    "Presentation",
    POI_DETAIL_PANEL_PRESENTATIONS,
  );
}

async function updatePOIDetailPanelVariant(
  component,
  { value, variableByName, fonts, stats },
) {
  const width = 380;
  const contentWidth = width - 32;
  productSdkVariantRoot(component, "POIDetailPanel", "Presentation=" + value, {
    primarySizing: "AUTO",
    counterSizing: "FIXED",
    spacing: 12,
    padding: 16,
    width,
    height: 420,
  });
  productSdkSurface(component, KOZMOS_RADIUS.container, variableByName, stats);

  // Sheet is anchored to the bottom edge, so only its top corners round and it
  // carries a grabber. Inline sits in the document flow with no elevation
  // affordance at all. Panel is the free-standing docked card.
  // In a sheet the panel paints no surface, border or shadow of its own: it
  // sits on the sheet's grey, which draws the handle (2026-09-21,
  // `components.poiDetailPanel.content.sheetSurface`). Only its top corners
  // round, at the control radius, as `rounded-t-control` does.
  const sheet = value === "Sheet";
  if (sheet) {
    component.fills = [];
    component.strokes = [];
    component.cornerRadius = KOZMOS_RADIUS.none;
    component.topLeftRadius = KOZMOS_RADIUS.control;
    component.topRightRadius = KOZMOS_RADIUS.control;
  } else if (value === "Inline") {
    component.strokes = [];
    component.cornerRadius = KOZMOS_RADIUS.none;
  }

  const header = await productSdkPanelHeader({
    title: "Kozmos Cafe",
    titleNodeName: "Title Text",
    closeGlyph: value === "Inline" ? null : "×",
    width: contentWidth,
    fonts,
    variableByName,
    stats,
  });
  appendWithSizing(component, header, "FILL", "HUG");

  const subtitle = await productSdkText({
    name: "Subtitle Text",
    characters: "Cafe · Level 2 · Open until 21:00",
    styleKey: "cardDescription",
    fonts,
    bold: false,
    fontSize: 12,
    lineHeight: 16,
    colorToken: "Colors/foreground/400",
    colorFallback: "#5D626F",
    variableByName,
    stats,
    width: contentWidth,
  });
  appendWithSizing(component, subtitle, "FILL", null);

  const media = await productSdkSlot({
    name: "Media Slot",
    label: "POIMediaGallery slot",
    width: contentWidth,
    height: 120,
    fonts,
    variableByName,
    stats,
  });
  // On the sheet's own grey an inset block is white instead of muted.
  const sheetInset = paintFromVariable(
    "Colors/background/0",
    "#FFFFFF",
    variableByName,
    stats,
  );
  if (sheet) media.fills = [sheetInset];
  appendWithSizing(component, media, "FILL", "FIXED");

  const description = await productSdkText({
    name: "Description Text",
    characters:
      "Speciality coffee and pastries beside the north atrium escalators.",
    styleKey: "cardBody",
    fonts,
    bold: false,
    fontSize: 14,
    lineHeight: 20,
    colorToken: "Colors/foreground/0",
    colorFallback: "#000000",
    variableByName,
    stats,
    width: contentWidth,
    wrap: true,
  });
  appendWithSizing(component, description, "FILL", "HUG");

  const services = await productSdkSlot({
    name: "Services Slot",
    label: "Services and access restrictions",
    width: contentWidth,
    height: 44,
    fonts,
    variableByName,
    stats,
    muted: true,
  });
  if (sheet) services.fills = [clonePaint(sheetInset)];
  appendWithSizing(component, services, "FILL", "FIXED");

  const actions = productSdkFrame("Actions Slot", {
    direction: "horizontal",
    primarySizing: "FIXED",
    counterSizing: "FIXED",
    spacing: 8,
    width: contentWidth,
    height: 44,
  });
  for (const actionLabel of ["Navigate", "Save", "Share"]) {
    const action = await productSdkControlButton({
      name: actionLabel + " Action",
      glyph: POI_DETAIL_PANEL_ACTION_GLYPHS[actionLabel],
      iconName: POI_DETAIL_PANEL_ACTION_ICONS[actionLabel],
      label: actionLabel,
      fonts,
      variableByName,
      stats,
    });
    appendWithSizing(actions, action, "HUG", "FIXED");
  }
  appendWithSizing(component, actions, "FILL", "FIXED");
}

function configurePOIDetailPanelProperties(componentSet, stats) {
  configureNamedTextProperty(
    componentSet,
    "Title Text",
    "Title Text",
    "Kozmos Cafe",
    stats,
  );
  configureNamedTextProperty(
    componentSet,
    "Subtitle Text",
    "Subtitle Text",
    "Cafe · Level 2 · Open until 21:00",
    stats,
  );
  configureNamedTextProperty(
    componentSet,
    "Description Text",
    "Description Text",
    "Speciality coffee and pastries beside the north atrium escalators.",
    stats,
  );
}

