/**
 * Every combination a generated set draws.
 *
 * Forty-five sets are built through these two helpers, and all of them had
 * exactly one axis. A component that grows a second — Card's padding,
 * EmptyState's size, POIResultCard's appearance — would otherwise need its own
 * hand-rolled Build and Update, which is how Rating ended up with a copy of
 * this logic that then had to be changed twice.
 *
 * `axis2Name` and `axis2Values` are optional: without them the behaviour is
 * exactly what it was, one axis and one loop.
 */
function generatedVariantCombinations(config) {
  const seconds = config.axis2Values || [null];
  const out = [];
  for (let i = 0; i < config.values.length; i += 1)
    for (let j = 0; j < seconds.length; j += 1)
      out.push({ value: config.values[i], second: seconds[j], i, j });
  return out;
}

/** The key a combination is remembered by while Update walks the set. */
function generatedVariantKey(value, second) {
  return second === null || second === undefined ? value : `${value}/${second}`;
}

async function buildSingleAxisComponent(config) {
  const stats = {
    created: false,
    componentSetId: null,
    urlNodeId: null,
    variants: 0,
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  removeStaleGeneratedComponentArtifacts(page, config.componentName, stats);

  const existing = findComponentSetOnPage(page, config.componentSetName);
  if (existing) {
    normalizeComponentSetNodeName(existing, config.componentSetName, stats);
    const duplicateCount = removeDuplicateGeneratedComponentSetsForName(
      page,
      config.componentSetName,
      existing,
      stats,
    );
    stats.existing = true;
    stats.componentSetId = existing.id;
    stats.urlNodeId = nodeIdForUrl(existing.id);
    stats.message = `${config.componentSetName} already exists. Use Update ${config.componentName} to preserve its node ID.`;
    if (duplicateCount > 0) {
      await reorganizeAfterGeneratedComponentMutation(stats);
    }
    return stats;
  }

  const fonts = await loadButtonFonts(stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const components = [];

  for (const combination of generatedVariantCombinations(config)) {
    const component = await config.createVariant({
      value: combination.value,
      second: combination.second,
      variableByName,
      fonts,
      stats,
    });
    component.x = combination.i * config.xStep;
    // A second axis takes its own row, so the two never overlap.
    component.y = combination.j * (config.yStep || 0);
    page.appendChild(component);
    components.push(component);
  }

  const componentSet = figma.combineAsVariants(components, page);
  componentSet.name = config.componentSetName;
  componentSet.x = config.x;
  componentSet.y = config.y;
  componentSet.setSharedPluginData(RUN_NAMESPACE, "kind", "component-set");
  componentSet.setSharedPluginData(RUN_NAMESPACE, "build", PLUGIN_BUILD);
  componentSet.setSharedPluginData(
    RUN_NAMESPACE,
    "component",
    config.componentName,
  );
  applyComponentSetDescription(
    componentSet,
    config.componentSetName,
    false,
    config.description,
  );
  clearComponentSetContainerFill(componentSet);

  stats.created = true;
  stats.componentSetId = componentSet.id;
  stats.urlNodeId = nodeIdForUrl(componentSet.id);
  stats.variants = components.length;
  normalizeComponentSetVariantProperties(
    componentSet,
    expectedVariantAxesForComponentSetName(componentSet.name),
    stats,
  );
  await config.configureProperties(componentSet, stats, variableByName);
  reportUnboundComponentProperties(componentSet, stats);
  runGeneratedComponentPostUpdateMaintenance(
    componentSet,
    config.componentName,
    stats,
  );
  await reorganizeAfterGeneratedComponentMutation(stats);
  await runGeneratedComponentPostLayoutMaintenance({
    componentName: config.componentName,
    componentSetName: config.componentSetName,
    stats,
  });
  return stats;
}

async function updateSingleAxisComponent(config) {
  const stats = {
    updated: false,
    componentSetId: null,
    urlNodeId: null,
    variantsUpdated: 0,
    variantsCreated: 0,
    variantsMissing: 0,
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  removeStaleGeneratedComponentArtifacts(page, config.componentName, stats);

  const existing = findComponentSetOnPage(page, config.componentSetName);
  if (!existing || existing.type !== "COMPONENT_SET") {
    stats.message = `${config.componentSetName} was not found. Run Build ${config.componentName} first.`;
    return stats;
  }
  normalizeComponentSetNodeName(existing, config.componentSetName, stats);
  removeDuplicateGeneratedComponentSetsForName(
    page,
    config.componentSetName,
    existing,
    stats,
  );

  const fonts = await loadButtonFonts(stats);
  const variableByName = await ensureComponentRuntimeVariables(stats);
  const seenValues = {};

  existing.setSharedPluginData(RUN_NAMESPACE, "kind", "component-set");
  existing.setSharedPluginData(RUN_NAMESPACE, "build", PLUGIN_BUILD);
  existing.setSharedPluginData(
    RUN_NAMESPACE,
    "component",
    config.componentName,
  );
  applyComponentSetDescription(
    existing,
    config.componentSetName,
    true,
    config.description,
  );
  clearComponentSetContainerFill(existing);

  for (const child of existing.children) {
    if (child.type !== "COMPONENT") continue;

    const props = config.parseVariantName(child.name);
    if (!props) {
      stats.warnings.push(
        `Skipped unrecognized ${config.componentName} variant "${child.name}".`,
      );
      continue;
    }

    // A variant drawn before a second axis existed parses with `second`
    // undefined, and the component's own parser decides what that means --
    // normally its default. Update then RENAMES it rather than replacing it,
    // so the node ids Code Connect pins survive.
    seenValues[generatedVariantKey(props.value, props.second)] = true;
    await reportSetProgress(
      config.componentSetName,
      `variant ${stats.variantsUpdated + 1} of ${existing.children.length}`,
      stats.variantsUpdated === 0,
    );
    await config.updateVariant(child, {
      value: props.value,
      second: props.second,
      variableByName,
      fonts,
      stats,
    });
    stats.variantsUpdated += 1;
  }

  for (const combination of generatedVariantCombinations(config)) {
    const key = generatedVariantKey(combination.value, combination.second);
    if (seenValues[key]) continue;

    const component = await config.createVariant({
      value: combination.value,
      second: combination.second,
      variableByName,
      fonts,
      stats,
    });
    existing.appendChild(component);
    seenValues[key] = true;
    stats.variantsCreated += 1;
  }

  layoutSingleAxisVariants(existing, config);

  stats.updated = true;
  stats.componentSetId = existing.id;
  stats.urlNodeId = nodeIdForUrl(existing.id);
  await reportSetProgress(config.componentSetName, "variant properties", true);
  normalizeComponentSetVariantProperties(
    existing,
    expectedVariantAxesForComponentSetName(existing.name),
    stats,
  );
  await reportSetProgress(
    config.componentSetName,
    "component properties",
    true,
  );
  await config.configureProperties(existing, stats, variableByName);
  reportUnboundComponentProperties(existing, stats);
  // These updaters sync variants and properties and never looked at an icon's
  // paint, so a slot orphaned by an earlier redraw stayed black through every
  // Update. Repair from what each slot already records.
  repairIconSlotTints(existing, variableByName, stats);
  await reportSetProgress(config.componentSetName, "maintenance", true);
  runGeneratedComponentPostUpdateMaintenance(
    existing,
    config.componentName,
    stats,
  );
  await reportSetProgress(config.componentSetName, "layout", true);
  await reorganizeAfterGeneratedComponentMutation(stats);
  await runGeneratedComponentPostLayoutMaintenance({
    componentName: config.componentName,
    componentSetName: config.componentSetName,
    stats,
  });
  return stats;
}

function layoutSingleAxisVariants(componentSet, config) {
  if (!componentSet || !componentSet.children) return;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = config.parseVariantName(child.name);
    if (!props) continue;

    const valueIndex = config.values.indexOf(props.value);
    const secondIndex = config.axis2Values
      ? config.axis2Values.indexOf(props.second)
      : 0;
    child.x = valueIndex * config.xStep;
    child.y = (secondIndex < 0 ? 0 : secondIndex) * (config.yStep || 0);
  }

  // A component set is a frame, and a frame keeps its size when its children
  // shrink. WayfindingCard was 700x1058 around 700x134 of variants -- 87% dead
  // space -- and POICard 74%, both left over from taller earlier layouts. The
  // Components page packs by bounding box, so an empty block costs a real
  // column slot, not just looks.
  resizeComponentSetToContainChildren(componentSet);
}

function layoutTextVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  const toneColumns = TEXT_TONES.length;
  const columnWidth = 240;
  const rowHeight = 86;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseTextVariantName(child.name);
    if (!props) continue;

    const sizeIndex = TEXT_SIZES.indexOf(props.size);
    const weightIndex = TEXT_WEIGHTS.indexOf(props.weight);
    const toneIndex = TEXT_TONES.indexOf(props.tone);
    child.x = (weightIndex * toneColumns + toneIndex) * columnWidth;
    child.y = sizeIndex * rowHeight;
  }
}

function layoutStackVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  const columnWidth = 380;
  const rowHeight = 160;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseStackVariantName(child.name);
    if (!props) continue;

    const directionIndex = STACK_DIRECTIONS.indexOf(props.direction);
    const gapIndex = STACK_GAPS.indexOf(props.gap);
    child.x = gapIndex * columnWidth;
    child.y = directionIndex * rowHeight;
  }
}

function layoutGridVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  const columnGap = 60;
  const rowGap = 48;
  let maxWidth = 360;
  let maxHeight = 0;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;
    if (typeof child.width === "number" && Number.isFinite(child.width)) {
      maxWidth = Math.max(maxWidth, child.width);
    }
    if (typeof child.height === "number" && Number.isFinite(child.height)) {
      maxHeight = Math.max(maxHeight, child.height);
    }
  }

  if (!maxHeight) maxHeight = 264;

  let maxColumnsIndex = 0;
  let maxGapIndex = 0;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseGridVariantName(child.name);
    if (!props) continue;

    const columnsIndex = GRID_COLUMNS.indexOf(props.columns);
    const gapIndex = GRID_GAPS.indexOf(props.gap);
    maxColumnsIndex = Math.max(maxColumnsIndex, columnsIndex);
    maxGapIndex = Math.max(maxGapIndex, gapIndex);
    child.x = columnsIndex * (maxWidth + columnGap);
    child.y = gapIndex * (maxHeight + rowGap);
  }

  resizeNodeWithoutConstraints(
    componentSet,
    (maxColumnsIndex + 1) * maxWidth + maxColumnsIndex * columnGap,
    (maxGapIndex + 1) * maxHeight + maxGapIndex * rowGap,
  );
  componentSet.clipsContent = false;
}

function layoutTabsVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseTabsVariantName(child.name);
    if (!props) continue;

    const countIndex = TABS_COUNTS.indexOf(props.count);
    const activeIndex = TABS_ACTIVE_TO_INDEX[props.active];
    const stateIndex = TABS_STATES.indexOf(props.state);
    child.x = activeIndex * 700;
    child.y = (countIndex * TABS_STATES.length + stateIndex) * 76;
  }
}

function layoutToggleButtonVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  const columnWidth = 180;
  const rowHeight = 72;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseToggleButtonVariantName(child.name);
    if (!props) continue;

    const variantIndex = TOGGLE_BUTTON_VARIANTS.indexOf(props.variant);
    const sizeIndex = TOGGLE_BUTTON_SIZES.indexOf(props.size);
    const stateIndex = TOGGLE_BUTTON_STATES.indexOf(props.state);
    child.x =
      (variantIndex * TOGGLE_BUTTON_SIZES.length + sizeIndex) * columnWidth;
    child.y = stateIndex * rowHeight;
  }

  resizeComponentSetToContainChildren(componentSet);
}

function layoutSplitButtonVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  const columnWidth = 260;
  const rowHeight = 76;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseSplitButtonVariantName(child.name);
    if (!props) continue;

    const variantIndex = SPLIT_BUTTON_VARIANTS.indexOf(props.variant);
    const sizeIndex = SPLIT_BUTTON_SIZES.indexOf(props.size);
    const stateIndex = SPLIT_BUTTON_STATES.indexOf(props.state);
    child.x =
      (variantIndex * SPLIT_BUTTON_SIZES.length + sizeIndex) * columnWidth;
    child.y = stateIndex * rowHeight;
  }

  resizeComponentSetToContainChildren(componentSet);
}

function layoutFloatingActionButtonVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  const columnWidth = 128;
  const rowHeight = 96;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseFloatingActionButtonVariantName(child.name);
    if (!props) continue;

    const variantIndex = FLOATING_ACTION_BUTTON_VARIANTS.indexOf(props.variant);
    const sizeIndex = FLOATING_ACTION_BUTTON_SIZES.indexOf(props.size);
    const stateIndex = FLOATING_ACTION_BUTTON_STATES.indexOf(props.state);
    child.x =
      (variantIndex * FLOATING_ACTION_BUTTON_SIZES.length + sizeIndex) *
      columnWidth;
    child.y = stateIndex * rowHeight;
  }

  resizeComponentSetToContainChildren(componentSet);
}

