async function configureFloatingActionButtonProperties(
  componentSet,
  iconComponent,
  variableByName,
  stats,
) {
  if (!iconComponent) {
    configureFocusVisibleProperty(componentSet, stats);
    return;
  }

  const iconSourceComponents = await findKozmosIconSourceComponents();
  const preferredValues = iconPreferredValues(iconSourceComponents);
  const propertyName = ensureInstanceSwapProperty(
    componentSet,
    BUTTON_ICON_PROPERTY,
    iconComponent.id,
    stats,
    preferredValues,
  );

  if (propertyName) {
    for (const child of componentSet.children) {
      if (child.type !== "COMPONENT") continue;

      const props = parseFloatingActionButtonVariantName(child.name);
      if (!props) continue;

      const config = floatingActionButtonConfig(props.variant, props.state);
      const metrics = floatingActionButtonMetrics(props.size);
      let icon = directChildNamed(child, "Icon");
      if (
        icon &&
        icon.type === "INSTANCE" &&
        !isGeneratedIconSlotWrapper(icon)
      ) {
        syncIconSlotInstance(
          icon,
          config,
          variableByName,
          stats,
          metrics.iconSize,
          metrics.iconSizeToken,
        );
      } else {
        if (icon) icon.remove();
        icon = createIconSlotInstance(
          iconComponent,
          config.foreground,
          config.foregroundFallback,
          variableByName,
          stats,
          metrics.iconSize,
          metrics.iconSizeToken,
        );
      }
      child.appendChild(icon);
      setHugChildSizing(icon);
      bindInstanceSwapProperty(icon, propertyName, stats);
      stats.iconSlotsBound += 1;
    }
  }

  configureFocusVisibleProperty(componentSet, stats);
}

