async function rebuildGeneratedComponentSet(config) {
  const rebuildStats = {
    rebuilt: false,
    removed: [],
    warnings: [],
  };

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();
  await removeGeneratedNodesForRebuild(
    page,
    config.componentSetName,
    rebuildStats,
  );

  const buildResult = await config.build();
  const merged = mergeRebuildResult(rebuildStats, buildResult, config);
  await finalizeRebuiltGeneratedComponentSet(config, merged);
  return merged;
}

async function finalizeRebuiltGeneratedComponentSet(config, stats) {
  if (!config || !stats || !stats.created) return;

  const page = await ensurePage("Components");
  await figma.setCurrentPageAsync(page);
  await page.loadAsync();

  const componentSet = findComponentSetOnPage(page, config.componentSetName);
  if (componentSet && componentSet.type === "COMPONENT_SET") {
    runGeneratedComponentPostUpdateMaintenance(
      componentSet,
      config.componentName,
      stats,
    );
  }

  if (!stats.layout) {
    await reorganizeAfterGeneratedComponentMutation(stats);
    await runGeneratedComponentPostLayoutMaintenance({
      componentName: config.componentName,
      componentSetName: config.componentSetName,
      stats,
    });
  }
}

async function removeGeneratedNodesForRebuild(page, componentSetName, stats) {
  const nodes = collectGeneratedNodesForRebuild(page, componentSetName);

  if (nodes.length === 0) {
    stats.warnings.push(
      `${componentSetName} was not found on the Components page before rebuild; creating a fresh set.`,
    );
    return;
  }

  for (const node of nodes) {
    const oldName = node.name;
    const oldId = node.id;
    const oldType = node.type;

    stats.removed.push({
      id: oldId,
      urlNodeId: nodeIdForUrl(oldId),
      oldName,
      type: oldType,
    });

    node.remove();
  }
}

function collectGeneratedNodesForRebuild(root, componentSetName) {
  const nodes = [];

  function visit(parent) {
    if (!parent || !parent.children) return;

    for (const child of parent.children.slice()) {
      if (
        child.type === "COMPONENT_SET" &&
        componentSetNameMatches(child.name, componentSetName)
      ) {
        nodes.push(child);
        continue;
      }

      if (
        child.type === "INSTANCE" &&
        (componentSetNameMatches(child.name, componentSetName) ||
          componentSetNameMatches(
            nodeSourceComponentSet(child),
            componentSetName,
          ))
      ) {
        nodes.push(child);
        continue;
      }

      if (shouldTraverseGeneratedCleanupContainer(child)) visit(child);
    }
  }

  visit(root);
  return nodes;
}

function mergeRebuildResult(rebuildStats, buildResult, config) {
  const merged = {};
  for (const key of Object.keys(buildResult)) {
    merged[key] = buildResult[key];
  }

  merged.rebuilt = buildResult.created === true;
  merged.removed = rebuildStats.removed;

  const warnings = [];
  for (const warning of rebuildStats.warnings) warnings.push(warning);
  if (buildResult.warnings) {
    for (const warning of buildResult.warnings) warnings.push(warning);
  }
  merged.warnings = warnings;

  if (buildResult.created) {
    const removedCount = rebuildStats.removed.length;
    merged.message =
      `${config.componentSetName} was rebuilt with fresh node-id=${buildResult.urlNodeId}. ` +
      `${removedCount} old generated node(s) were removed.`;
  } else if (buildResult.existing) {
    merged.message = `Could not rebuild ${config.componentSetName}; another node with that name still exists on the Components page.`;
  }

  return merged;
}

function removeStaleGeneratedComponentArtifacts(page, componentName, stats) {
  const stale = collectStaleGeneratedComponentArtifacts(page, componentName);

  for (const child of stale) {
    child.remove();
    incrementStat(stats, "staleArtifactsRemoved");
  }
}

function collectStaleGeneratedComponentArtifacts(root, componentName) {
  const stale = [];
  const componentSetName = componentName;

  function visit(parent) {
    if (!parent || !parent.children) return;

    for (const child of parent.children.slice()) {
      if (child.type === "COMPONENT_SET") continue;

      if (
        child.type === "COMPONENT" &&
        child.getSharedPluginData &&
        child.getSharedPluginData(RUN_NAMESPACE, "component") === componentName
      ) {
        stale.push(child);
        continue;
      }

      if (
        child.type === "INSTANCE" &&
        (componentSetNameMatches(child.name, componentSetName) ||
          componentSetNameMatches(
            nodeSourceComponentSet(child),
            componentSetName,
          ))
      ) {
        stale.push(child);
        continue;
      }

      if (
        componentName === "Badge" &&
        child.type === "TEXT" &&
        child.name === "Label Text" &&
        child.characters === ""
      ) {
        stale.push(child);
        continue;
      }

      if (isTopLevelGeneratedAnatomyArtifact(child, componentName)) {
        stale.push(child);
        continue;
      }

      if (shouldTraverseGeneratedCleanupContainer(child)) visit(child);
    }
  }

  visit(root);
  return stale;
}

function isComponentDefinitionNode(node) {
  return (
    node &&
    (node.type === "COMPONENT_SET" ||
      node.type === "COMPONENT" ||
      node.type === "INSTANCE")
  );
}

function shouldTraverseGeneratedCleanupContainer(node) {
  return (
    node &&
    !isComponentDefinitionNode(node) &&
    (node.type === "PAGE" || node.type === "SECTION" || node.type === "GROUP")
  );
}

function isTopLevelGeneratedAnatomyArtifact(node, componentName) {
  if (!node || node.type === "COMPONENT_SET" || node.type === "COMPONENT") {
    return false;
  }

  const namesByComponent = {
    Accordion: [
      "Accordion Content",
      "Accordion Divider",
      "Accordion Trigger",
      "Content Text",
      "Trigger Text",
    ],
    Drawer: [
      "Body Text",
      "Content Slot",
      "Drawer Body",
      "Drawer Close",
      "Drawer Footer",
      "Drawer Header",
      "Drawer Header Content",
      "Primary Action",
      "Secondary Action",
      "Title Text",
      "Description Text",
    ],
    PasswordInput: [
      "Eye Outline",
      "Eye Pupil",
      "Eye Slash",
      "Helper Text",
      "Label Text",
      "PasswordInput Field",
      "PasswordInput Value Slot",
      "Placeholder Text",
      "Visibility Icon / hide",
      "Visibility Icon / show",
      "Visibility Toggle",
    ],
    OTPInput: [
      "Digit 1 Cell",
      "Digit 1 Text",
      "Digit 2 Cell",
      "Digit 2 Text",
      "Digit 3 Cell",
      "Digit 3 Text",
      "Digit 4 Cell",
      "Digit 4 Text",
      "Digit 5 Cell",
      "Digit 5 Text",
      "Digit 6 Cell",
      "Digit 6 Text",
      "Helper Text",
      "Label Text",
      "OTPInput Cell Group",
    ],
    Navbar: [
      "Logo Slot",
      "Site Slot",
      "Site Selector",
      "Context Slot",
      "Context Selector",
      "Navigation Slot",
      "Primary Action Slot",
      "Actions Slot",
      "Utility Slot",
      "Utility Button",
      "Account Slot",
      "Account Avatar",
    ],
  };
  const names = namesByComponent[componentName];
  return !!names && names.indexOf(node.name) !== -1;
}

async function ensurePage(name) {
  const existing = figma.root.children.find((page) => page.name === name);
  if (existing) {
    await existing.loadAsync();
    return existing;
  }

  const page = figma.createPage();
  page.name = name;
  page.setSharedPluginData(RUN_NAMESPACE, "kind", "page");
  await page.loadAsync();
  return page;
}

async function resolveConfiguredFonts(stats) {
  const config = currentFontConfig();
  const regular = await loadFirstAvailableFont(
    fontCandidatesForRole("regular"),
  );
  const medium = await loadFirstAvailableFont(
    fontCandidatesForRole("medium", regular),
  );
  const bold = await loadFirstAvailableFont(
    fontCandidatesForRole("bold", medium),
  );

  if (
    !sameFont(regular, {
      family: config.family,
      style: config.regularStyle,
    })
  ) {
    pushUniqueWarning(
      stats,
      `font-fallback:regular:${config.family}:${config.regularStyle}`,
      `Configured ${config.family} ${config.regularStyle} was unavailable for regular text; using ${fontLabel(regular)}.`,
    );
  }

  if (
    !sameFont(medium, {
      family: config.family,
      style: config.mediumStyle,
    })
  ) {
    pushUniqueWarning(
      stats,
      `font-fallback:medium:${config.family}:${config.mediumStyle}`,
      `Configured ${config.family} ${config.mediumStyle} was unavailable for medium text; using ${fontLabel(medium)}.`,
    );
  }

  if (
    !sameFont(bold, {
      family: config.family,
      style: config.boldStyle,
    })
  ) {
    pushUniqueWarning(
      stats,
      `font-fallback:bold:${config.family}:${config.boldStyle}`,
      `Configured ${config.family} ${config.boldStyle} was unavailable for bold text; using ${fontLabel(bold)}.`,
    );
  }

  if (stats) {
    stats.fontConfig = {
      requestedFamily: config.family,
      regular: fontLabel(regular),
      medium: fontLabel(medium),
      bold: fontLabel(bold),
    };
  }

  const fonts = { regular, medium, bold };
  return fonts;
}

async function loadButtonFonts(stats) {
  const fonts = await resolveConfiguredFonts(stats);
  await ensureKozmosTextStyles(fonts, stats);
  return fonts;
}

async function loadFirstAvailableFont(fonts) {
  let lastError = null;
  for (const font of fonts) {
    try {
      await figma.loadFontAsync(font);
      return font;
    } catch (error) {
      lastError = error;
    }
  }

  throw lastError || new Error("No usable font found.");
}

async function createButtonVariant({
  variant,
  size,
  state,
  variableByName,
  fonts,
  textStyle,
  stats,
}) {
  const config = buttonConfig(variant, state);
  const metrics = buttonMetrics(size);
  const component = figma.createComponent();
  component.name = `Variant=${variant}, Size=${size}, State=${state}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = metrics.gap;
  component.paddingLeft = metrics.paddingX;
  component.paddingRight = metrics.paddingX;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(metrics.width, metrics.height);
  component.cornerRadius = KOZMOS_RADIUS.control;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Button");

  component.fills = config.background
    ? [
        paintFromVariable(
          config.background,
          config.backgroundFallback,
          variableByName,
          stats,
        ),
      ]
    : [];

  if (config.stroke) {
    component.strokes = [
      paintFromVariable(
        config.stroke,
        config.strokeFallback,
        variableByName,
        stats,
      ),
    ];
    component.strokeWeight = 1;
  } else {
    component.strokes = [];
    component.strokeWeight = 0;
  }

  bindButtonGeometryVariables(
    component,
    metrics,
    config,
    variableByName,
    stats,
  );

  if (variant === "Glass") {
    component.effects = [elevationEffect("overlay")];
  }

  if (state === "Loading") {
    component.appendChild(
      createSpinnerGlyph(
        config.foreground,
        config.foregroundFallback,
        variableByName,
        stats,
        metrics.spinnerSize,
        metrics.spinnerSizeToken,
      ),
    );
  }

  if (size !== "Icon") {
    const label = figma.createText();
    label.name = "Label Text";
    await applyButtonLabelTypography(
      label,
      fonts,
      textStyle,
      variableByName,
      stats,
    );
    label.characters = state === "Loading" ? "Loading" : variant;
    label.fills = [
      paintFromVariable(
        config.foreground,
        config.foregroundFallback,
        variableByName,
        stats,
      ),
    ];
    if (variant === "Link") label.textDecoration = "UNDERLINE";
    component.appendChild(label);
  }

  syncFocusRing(component, {
    enabled: state === "Default",
    width: metrics.width,
    height: metrics.height,
    radius: KOZMOS_RADIUS.control,
    variableName: "Colors/theme/500",
    fallback: "#135BEC",
    variableByName,
    stats,
  });

  return component;
}

function parseButtonVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (
    BUTTON_VARIANTS.indexOf(values.Variant) === -1 ||
    BUTTON_SIZES.indexOf(values.Size) === -1 ||
    BUTTON_STATES.indexOf(values.State) === -1
  ) {
    return null;
  }

  return {
    variant: values.Variant,
    size: values.Size,
    state: values.State,
  };
}

