async function updateSplitButtonVariant(
  component,
  { variant, size, state, variableByName, fonts, textStyle, stats },
) {
  const config = splitButtonConfig(variant, state);
  const metrics = splitButtonMetrics(size);

  component.name = `Variant=${variant}, Size=${size}, State=${state}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "MIN";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = 0;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(metrics.width, metrics.height);
  component.cornerRadius = KOZMOS_RADIUS.control;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "SplitButton");

  component.fills = config.background
    ? [
        paintFromVariable(
          config.background,
          config.backgroundFallback,
          variableByName,
          stats,
        ),
      ]
    : [];

  if (config.stroke) {
    component.strokes = [
      paintFromVariable(
        config.stroke,
        config.strokeFallback,
        variableByName,
        stats,
      ),
    ];
    component.strokeWeight = 1;
  } else {
    component.strokes = [];
    component.strokeWeight = 0;
  }

  let mainAction = directChildNamed(component, "Main Action");
  if (mainAction && mainAction.type !== "FRAME") {
    mainAction.remove();
    mainAction = null;
  }

  if (!mainAction || mainAction.type !== "FRAME") {
    mainAction = figma.createFrame();
    mainAction.name = "Main Action";
  }
  mainAction.layoutMode = "HORIZONTAL";
  mainAction.primaryAxisSizingMode = "FIXED";
  mainAction.counterAxisSizingMode = "FIXED";
  mainAction.primaryAxisAlignItems = "CENTER";
  mainAction.counterAxisAlignItems = "CENTER";
  mainAction.itemSpacing = 0;
  mainAction.paddingLeft = metrics.mainPaddingX;
  mainAction.paddingRight = metrics.mainPaddingX;
  mainAction.paddingTop = 0;
  mainAction.paddingBottom = 0;
  mainAction.resizeWithoutConstraints(
    metrics.width - metrics.triggerWidth - 1,
    metrics.height,
  );
  mainAction.fills = [];
  mainAction.strokes = [];
  mainAction.cornerRadius = KOZMOS_RADIUS.none;
  mainAction.clipsContent = false;
  setHorizontalStackFillChildSizing(mainAction);

  let label = directChildNamed(mainAction, "Label Text");
  if (label && label.type !== "TEXT") {
    label.remove();
    label = null;
  }

  if (!label || label.type !== "TEXT") {
    label = figma.createText();
    label.name = "Label Text";
  }

  await applyButtonLabelTypography(
    label,
    fonts,
    textStyle,
    variableByName,
    stats,
  );
  label.characters = variant === "Destructive" ? "Delete" : "Action";
  label.fills = [
    paintFromVariable(
      config.foreground,
      config.foregroundFallback,
      variableByName,
      stats,
    ),
  ];
  label.textDecoration = "NONE";
  mainAction.appendChild(label);
  setHugChildSizing(label);

  let divider = directChildNamed(component, "Divider");
  if (divider && divider.type !== "RECTANGLE") {
    divider.remove();
    divider = null;
  }

  if (!divider || divider.type !== "RECTANGLE") {
    divider = figma.createRectangle();
    divider.name = "Divider";
  }
  divider.resizeWithoutConstraints(1, metrics.height);
  divider.fills = [
    paintFromVariable(
      config.foreground,
      config.foregroundFallback,
      variableByName,
      stats,
    ),
  ];
  divider.opacity = state === "Disabled" ? 0.24 : 0.32;
  divider.strokes = [];
  setFixedChildSizing(divider);

  let trigger = directChildNamed(component, "Menu Trigger");
  if (trigger && trigger.type !== "FRAME") {
    trigger.remove();
    trigger = null;
  }

  if (!trigger || trigger.type !== "FRAME") {
    trigger = figma.createFrame();
    trigger.name = "Menu Trigger";
  }
  trigger.layoutMode = "HORIZONTAL";
  trigger.primaryAxisSizingMode = "FIXED";
  trigger.counterAxisSizingMode = "FIXED";
  trigger.primaryAxisAlignItems = "CENTER";
  trigger.counterAxisAlignItems = "CENTER";
  trigger.itemSpacing = 0;
  trigger.paddingLeft = 0;
  trigger.paddingRight = 0;
  trigger.paddingTop = 0;
  trigger.paddingBottom = 0;
  trigger.resizeWithoutConstraints(metrics.triggerWidth, metrics.height);
  trigger.fills = [];
  trigger.strokes = [];
  trigger.cornerRadius = KOZMOS_RADIUS.none;
  trigger.clipsContent = false;
  setFixedChildSizing(trigger);

  removeGeneratedButtonChild(trigger, "Icon", true);
  const icon = await createFixedIconInstance(
    "chevron-down",
    config.foreground,
    config.foregroundFallback,
    variableByName,
    stats,
    16,
    "SplitButton/icon/size",
  );
  trigger.appendChild(icon);

  component.appendChild(mainAction);
  component.appendChild(divider);
  component.appendChild(trigger);

  bindSplitButtonGeometryVariables(
    component,
    mainAction,
    trigger,
    divider,
    metrics,
    config,
    variableByName,
    stats,
  );

  syncFocusRing(component, {
    enabled: state !== "Disabled",
    width: metrics.width,
    height: metrics.height,
    radius: KOZMOS_RADIUS.control,
    variableName: "Colors/theme/500",
    fallback: "#135BEC",
    variableByName,
    stats,
  });
}

