async function updateFloatingActionButtonVariant(
  component,
  { variant, size, state, iconComponent, variableByName, stats },
) {
  const config = floatingActionButtonConfig(variant, state);
  const metrics = floatingActionButtonMetrics(size);

  component.name = `Variant=${variant}, Size=${size}, State=${state}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = 0;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(metrics.size, metrics.size);
  component.cornerRadius = metrics.size / 2;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(
    RUN_NAMESPACE,
    "component",
    "FloatingActionButton",
  );

  component.fills = config.background
    ? [
        paintFromVariable(
          config.background,
          config.backgroundFallback,
          variableByName,
          stats,
        ),
      ]
    : [];

  if (config.stroke) {
    component.strokes = [
      paintFromVariable(
        config.stroke,
        config.strokeFallback,
        variableByName,
        stats,
      ),
    ];
    component.strokeWeight = 1;
  } else {
    component.strokes = [];
    component.strokeWeight = 0;
  }

  component.effects =
    state === "Disabled"
      ? []
      : [
          {
            type: "DROP_SHADOW",
            color: { r: 0, g: 0, b: 0, a: 0.18 },
            offset: { x: 0, y: 8 },
            radius: 16,
            spread: -8,
            visible: true,
            blendMode: "NORMAL",
          },
        ];

  bindFloatingActionButtonGeometryVariables(
    component,
    metrics,
    config,
    variableByName,
    stats,
  );

  removeGeneratedButtonChild(component, "Icon", true);
  let icon = null;
  const resolvedIconComponent =
    iconComponent ||
    (await resolveDefaultIconSourceComponent(variableByName, stats));
  if (resolvedIconComponent) {
    icon = createIconSlotInstance(
      resolvedIconComponent,
      config.foreground,
      config.foregroundFallback,
      variableByName,
      stats,
      metrics.iconSize,
      metrics.iconSizeToken,
    );
    component.appendChild(icon);
    setHugChildSizing(icon);
  }

  syncFocusRing(component, {
    enabled: state !== "Disabled",
    width: metrics.size,
    height: metrics.size,
    radius: metrics.size / 2,
    variableName: "Colors/theme/500",
    fallback: "#135BEC",
    variableByName,
    stats,
  });
}

