async function updateSeparatorVariant(
  component,
  { value, variableByName, stats },
) {
  const horizontal = value === "Horizontal";
  component.name = `Orientation=${value}`;
  component.layoutMode = "NONE";
  component.resizeWithoutConstraints(horizontal ? 320 : 1, horizontal ? 1 : 44);
  // A divider is a border drawn as a 1px rectangle, so it reads the border
  // role like every other edge. It was foreground/500, a text colour at
  // 4.2:1, while the web drew the same rule at 1.6:1.
  component.fills = [
    paintFromVariable("Border/Subtle", "#C7CAD1", variableByName, stats),
  ];
  component.strokes = [];
  component.strokeWeight = 0;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Separator");
  bindSizeVariables(
    component,
    horizontal ? "Separator/length/default" : "Separator/thickness",
    horizontal ? "Separator/thickness" : "Separator/height/vertical",
    variableByName,
    stats,
  );
}

async function createSkeletonVariant({ value, variableByName, stats }) {
  const component = figma.createComponent();
  await updateSkeletonVariant(component, {
    value,
    variableByName,
    stats,
  });
  return component;
}

function parseSkeletonVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (SKELETON_SHAPES.indexOf(values.Shape) === -1) return null;

  return {
    value: values.Shape,
    shape: values.Shape,
  };
}

async function updateSkeletonVariant(
  component,
  { value, variableByName, stats },
) {
  const metrics = skeletonMetrics(value);
  component.name = `Shape=${value}`;
  component.layoutMode = "NONE";
  component.resizeWithoutConstraints(metrics.width, metrics.height);
  component.cornerRadius = metrics.radius;
  component.fills = [
    paintFromVariable(
      "Colors/background/200",
      "#C7CAD1",
      variableByName,
      stats,
    ),
  ];
  component.strokes = [];
  component.strokeWeight = 0;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Skeleton");

  bindSizeVariables(
    component,
    metrics.widthToken,
    metrics.heightToken,
    variableByName,
    stats,
  );
  bindFloatVariable(
    component,
    "cornerRadius",
    metrics.radiusToken,
    variableByName,
    stats,
  );
}

async function createBoxVariant({ value, variableByName, fonts, stats }) {
  const component = figma.createComponent();
  await updateBoxVariant(component, {
    value,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

function parseBoxVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (BOX_SURFACES.indexOf(values.Surface) === -1) return null;

  return {
    value: values.Surface,
    surface: values.Surface,
  };
}

async function updateBoxVariant(component, { value, variableByName, stats }) {
  const config = boxSurfaceConfig(value);
  component.name = `Surface=${value}`;
  component.layoutMode = "VERTICAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = 0;
  component.paddingLeft = 16;
  component.paddingRight = 16;
  component.paddingTop = 16;
  component.paddingBottom = 16;
  component.resizeWithoutConstraints(320, 120);
  component.cornerRadius = KOZMOS_RADIUS.control;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Box");

  component.fills = config.background
    ? [
        paintFromVariable(
          config.background,
          config.backgroundFallback,
          variableByName,
          stats,
        ),
      ]
    : [];

  if (config.stroke) {
    component.strokes = [
      paintFromVariable(
        config.stroke,
        config.strokeFallback,
        variableByName,
        stats,
      ),
    ];
    component.strokeWeight = 1;
  } else {
    component.strokes = [];
    component.strokeWeight = 0;
  }

  bindSizeVariables(
    component,
    "Box/width/default",
    "Box/min-height/default",
    variableByName,
    stats,
  );
  for (const field of [
    "paddingLeft",
    "paddingRight",
    "paddingTop",
    "paddingBottom",
  ]) {
    bindFloatVariable(
      component,
      field,
      "Box/padding/default",
      variableByName,
      stats,
    );
  }
  bindFloatVariable(
    component,
    "cornerRadius",
    "Box/radius",
    variableByName,
    stats,
  );
  if (config.stroke) {
    bindFloatVariable(
      component,
      "strokeWeight",
      "Box/stroke/width",
      variableByName,
      stats,
    );
  }

  removeDirectChildrenNamed(component, ["Box Text", "Content Slot"]);
  const contentSlot = appendComponentContentSlot({
    component,
    height: 88,
    ownerName: "Box",
    parent: component,
    slotName: "Content Slot",
    stats,
    width: 288,
  });
  setVerticalStackFillChildSizing(contentSlot);
}

async function createStackVariant({ direction, gap, variableByName, stats }) {
  const component = figma.createComponent();
  await updateStackVariant(component, {
    direction,
    gap,
    variableByName,
    stats,
  });
  return component;
}

function parseStackVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (
    STACK_DIRECTIONS.indexOf(values.Direction) === -1 ||
    STACK_GAPS.indexOf(values.Gap) === -1
  ) {
    return null;
  }

  return {
    direction: values.Direction,
    gap: values.Gap,
  };
}

async function updateStackVariant(
  component,
  { direction, gap, variableByName, stats },
) {
  const horizontal = direction === "Row";
  component.name = `Direction=${direction}, Gap=${gap}`;
  component.layoutMode = horizontal ? "HORIZONTAL" : "VERTICAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = Number(gap) * 4;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(320, horizontal ? 72 : 120);
  component.fills = [];
  component.strokes = [];
  component.strokeWeight = 0;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Stack");

  bindSizeVariables(
    component,
    "Stack/width/default",
    horizontal ? "Stack/height/row" : "Stack/height/column",
    variableByName,
    stats,
  );
  bindFloatVariable(
    component,
    "itemSpacing",
    `Stack/gap/${gap}`,
    variableByName,
    stats,
  );

  const existingItems = (component.children || []).filter(
    (child) => /^Stack Item /.test(child.name) || child.name === "Content Slot",
  );
  for (const child of existingItems) child.remove();

  const contentSlot = appendComponentContentSlot({
    component,
    height: horizontal ? 72 : 120,
    itemSpacing: Number(gap) * 4,
    layoutMode: horizontal ? "HORIZONTAL" : "VERTICAL",
    ownerName: "Stack",
    parent: component,
    slotName: "Content Slot",
    stats,
    width: 320,
  });
  setVerticalStackFillChildSizing(contentSlot);
}

async function createGridVariant({ columns, gap, variableByName, stats }) {
  const component = figma.createComponent();
  await updateGridVariant(component, {
    columns,
    gap,
    variableByName,
    stats,
  });
  return component;
}

function parseGridVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (
    GRID_COLUMNS.indexOf(values.Columns) === -1 ||
    GRID_GAPS.indexOf(values.Gap) === -1
  ) {
    return null;
  }

  return {
    columns: values.Columns,
    gap: values.Gap,
  };
}

async function updateGridVariant(
  component,
  { columns, gap, variableByName, stats },
) {
  const gapPx = Number(gap) * 4;
  const columnCount = Number(columns);
  const width = 360;
  const cellHeight = 40;
  const height =
    GRID_PREVIEW_ROWS * cellHeight + (GRID_PREVIEW_ROWS - 1) * gapPx;
  const cellWidth = (width - (columnCount - 1) * gapPx) / columnCount;

  component.name = `Columns=${columns}, Gap=${gap}`;
  component.layoutMode = "VERTICAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "MIN";
  component.counterAxisAlignItems = "MIN";
  component.itemSpacing = gapPx;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(width, height);
  component.fills = [];
  component.strokes = [];
  component.strokeWeight = 0;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Grid");

  bindSizeVariables(
    component,
    "Grid/width/default",
    `Grid/height/${gap}`,
    variableByName,
    stats,
  );

  removeDirectChildrenMatching(
    component,
    (child) =>
      isGridCellSlotName(child.name) ||
      isGridRowFrameName(child.name) ||
      isLegacyGridCellFrameName(child.name) ||
      child.name === "Content Slot",
  );

  for (let rowIndex = 0; rowIndex < GRID_PREVIEW_ROWS; rowIndex += 1) {
    const row = createGridRowFrame({
      gapPx,
      height: cellHeight,
      rowIndex,
      width,
    });
    component.appendChild(row);
    setVerticalStackFillChildSizing(row);

    for (let columnIndex = 0; columnIndex < columnCount; columnIndex += 1) {
      const slotIndex = rowIndex * columnCount + columnIndex;
      const cellSlot = appendComponentContentSlot({
        component,
        height: cellHeight,
        itemSpacing: 0,
        layoutMode: "VERTICAL",
        ownerName: "Grid",
        parent: row,
        slotName: `Cell ${slotIndex + 1} Slot`,
        stats,
        width: cellWidth,
      });
      cellSlot.setSharedPluginData(RUN_NAMESPACE, "component", "Grid");
      cellSlot.setSharedPluginData(
        RUN_NAMESPACE,
        "grid-cell-index",
        String(slotIndex + 1),
      );
      cellSlot.setSharedPluginData(
        RUN_NAMESPACE,
        "grid-row",
        String(rowIndex + 1),
      );
      cellSlot.setSharedPluginData(
        RUN_NAMESPACE,
        "grid-column",
        String(columnIndex + 1),
      );
      bindGridCellSlotVariables(cellSlot, variableByName, stats);
      setHorizontalStackFillChildSizing(cellSlot);
    }
  }
}

function createGridRowFrame({ gapPx, height, rowIndex, width }) {
  const row = figma.createFrame();
  row.name = `Grid Row ${rowIndex + 1}`;
  row.layoutMode = "HORIZONTAL";
  row.primaryAxisSizingMode = "FIXED";
  row.counterAxisSizingMode = "FIXED";
  row.primaryAxisAlignItems = "MIN";
  row.counterAxisAlignItems = "MIN";
  row.itemSpacing = gapPx;
  row.paddingLeft = 0;
  row.paddingRight = 0;
  row.paddingTop = 0;
  row.paddingBottom = 0;
  row.resizeWithoutConstraints(width, height);
  row.fills = [];
  row.strokes = [];
  row.clipsContent = false;
  row.setSharedPluginData(RUN_NAMESPACE, "kind", "grid-row");
  row.setSharedPluginData(RUN_NAMESPACE, "component", "Grid");
  return row;
}

function gridCellSlotNames(columns, rows) {
  const names = [];
  const total = columns * rows;
  for (let index = 0; index < total; index += 1) {
    names.push(`Cell ${index + 1} Slot`);
  }
  return names;
}

function maxGridColumnCount() {
  let max = 0;
  for (const columns of GRID_COLUMNS) {
    max = Math.max(max, Number(columns));
  }
  return max;
}

function isGridCellSlotName(name) {
  return /^Cell \d+ Slot$/.test(name || "");
}

function isGridRowFrameName(name) {
  return /^Grid Row(?: \d+)?$/.test(name || "");
}

function isLegacyGridCellFrameName(name) {
  return /^Grid Cell(?: \d+)?$/.test(name || "");
}

function bindGridCellSlotVariables(slot, variableByName, stats) {
  bindFloatVariable(
    slot,
    "height",
    "Grid/cell/height/default",
    variableByName,
    stats,
  );
}

async function createContainerVariant({
  value,
  second,
  variableByName,
  fonts,
  stats,
}) {
  const component = figma.createComponent();
  await updateContainerVariant(component, {
    value,
    second,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

function parseContainerVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (CONTAINER_CENTERED.indexOf(values.Centered) === -1) return null;

  // A variant drawn before the Inset axis carries none and is the page's,
  // so Update renames it rather than replacing it.
  const second = values.Inset || "Window";
  if (CONTAINER_INSETS.indexOf(second) === -1) return null;

  return {
    value: values.Centered,
    second,
    centered: values.Centered,
  };
}

async function updateContainerVariant(
  component,
  { value, second, variableByName, stats },
) {
  const centered = value === "True";
  const inset = CONTAINER_INSETS.indexOf(second) === -1 ? "Window" : second;
  component.name = `Centered=${value}, Inset=${inset}`;
  component.layoutMode = "VERTICAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = centered ? "CENTER" : "MIN";
  component.itemSpacing = 0;
  component.paddingLeft = containerInsetPadding(inset);
  component.paddingRight = containerInsetPadding(inset);
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(480, 120);
  component.fills = [];
  component.strokes = [];
  component.strokeWeight = 0;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Container");

  bindSizeVariables(
    component,
    "Container/width/default",
    "Container/min-height/default",
    variableByName,
    stats,
  );
  bindFloatVariable(
    component,
    "paddingLeft",
    "Container/padding/x",
    variableByName,
    stats,
  );
  bindFloatVariable(
    component,
    "paddingRight",
    "Container/padding/x",
    variableByName,
    stats,
  );

  let content = directChildNamed(component, "Container Content");
  if (content && content.type !== "FRAME") {
    content.remove();
    content = null;
  }

  if (!content || content.type !== "FRAME") {
    content = figma.createFrame();
    content.name = "Container Content";
  }

  const contentWidth = centered ? 320 : 432;
  content.layoutMode = "HORIZONTAL";
  content.primaryAxisSizingMode = "FIXED";
  content.counterAxisSizingMode = "FIXED";
  content.primaryAxisAlignItems = "CENTER";
  content.counterAxisAlignItems = "CENTER";
  content.itemSpacing = 0;
  content.paddingLeft = 16;
  content.paddingRight = 16;
  content.paddingTop = 16;
  content.paddingBottom = 16;
  content.resizeWithoutConstraints(contentWidth, 64);
  content.cornerRadius = KOZMOS_RADIUS.control;
  content.fills = [
    paintFromVariable(
      "Colors/background/100",
      "#F4F5F7",
      variableByName,
      stats,
    ),
  ];
  content.strokes = [
    paintFromVariable("Border/Subtle", "#C7CAD1", variableByName, stats),
  ];
  content.strokeWeight = 1;
  content.clipsContent = false;

  bindSizeVariables(
    content,
    centered
      ? "Container/content-width/centered"
      : "Container/content-width/fluid",
    "Container/content-height",
    variableByName,
    stats,
  );
  for (const field of [
    "paddingLeft",
    "paddingRight",
    "paddingTop",
    "paddingBottom",
  ]) {
    bindFloatVariable(
      content,
      field,
      "Container/content-padding",
      variableByName,
      stats,
    );
  }
  bindFloatVariable(
    content,
    "cornerRadius",
    "Container/content-radius",
    variableByName,
    stats,
  );
  bindFloatVariable(
    content,
    "strokeWeight",
    "Container/content-stroke/width",
    variableByName,
    stats,
  );

  removeDirectChildrenNamed(content, ["Container Text", "Content Slot"]);
  const contentSlot = appendComponentContentSlot({
    component,
    height: 32,
    layoutMode: "HORIZONTAL",
    ownerName: "Container",
    parent: content,
    slotName: "Content Slot",
    stats,
    width: contentWidth - 32,
  });
  setLayoutSizingHorizontal(contentSlot, "FILL");
  setLayoutSizingVertical(contentSlot, "FILL");
  component.appendChild(content);
}

async function createBreadcrumbVariant({
  value,
  variableByName,
  fonts,
  stats,
}) {
  const component = figma.createComponent();
  await updateBreadcrumbVariant(component, {
    value,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

function parseBreadcrumbVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (BREADCRUMB_CONTENT.indexOf(values.Content) === -1) return null;

  return {
    value: values.Content,
    content: values.Content,
  };
}

async function updateBreadcrumbVariant(
  component,
  { value, variableByName, fonts, stats },
) {
  const isEllipsis = value === "Ellipsis";
  component.name = `Content=${value}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "MIN";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = 8;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(isEllipsis ? 284 : 360, 44);
  component.fills = [];
  component.strokes = [];
  component.strokeWeight = 0;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Breadcrumb");

  bindSizeVariables(
    component,
    isEllipsis ? "Breadcrumb/width/ellipsis" : "Breadcrumb/width/basic",
    "Breadcrumb/height",
    variableByName,
    stats,
  );
  bindFloatVariable(
    component,
    "itemSpacing",
    "Breadcrumb/gap",
    variableByName,
    stats,
  );

  const oldChildren = [];
  for (const child of component.children || []) {
    oldChildren.push(child);
  }
  for (const child of oldChildren) {
    child.remove();
  }

  await appendBreadcrumbText({
    parent: component,
    name: "Item 1 Text",
    characters: "Home",
    colorToken: "Colors/foreground/400",
    colorFallback: "#5D626F",
    fonts,
    variableByName,
    stats,
  });
  await appendBreadcrumbSeparator(component, variableByName, stats);

  if (isEllipsis) {
    appendBreadcrumbEllipsis(component, variableByName, stats);
  } else {
    await appendBreadcrumbText({
      parent: component,
      name: "Item 2 Text",
      characters: "Components",
      colorToken: "Colors/foreground/400",
      colorFallback: "#5D626F",
      fonts,
      variableByName,
      stats,
    });
  }

  await appendBreadcrumbSeparator(component, variableByName, stats);
  await appendBreadcrumbText({
    parent: component,
    name: "Current Page Text",
    characters: "Breadcrumb",
    colorToken: "Colors/foreground/0",
    colorFallback: "#000000",
    fonts,
    variableByName,
    stats,
  });
}

async function appendBreadcrumbText({
  parent,
  name,
  characters,
  colorToken,
  colorFallback,
  fonts,
  variableByName,
  stats,
}) {
  const text = figma.createText();
  text.name = name;
  text.fontName = fonts.regular;
  text.fontSize = 14;
  text.lineHeight = { unit: "PIXELS", value: 20 };
  await applyTextStyleToNodeAsync(text, "breadcrumbItem", stats);
  text.characters = characters;
  text.fills = [
    paintFromVariable(colorToken, colorFallback, variableByName, stats),
  ];
  setTextAutoResize(text, "WIDTH_AND_HEIGHT");
  bindFloatVariable(
    text,
    "fontSize",
    "Breadcrumb/font-size",
    variableByName,
    stats,
  );
  bindFloatVariable(
    text,
    "lineHeight",
    "Breadcrumb/line-height",
    variableByName,
    stats,
  );
  parent.appendChild(text);
  setHugChildSizing(text);
  return text;
}

async function appendBreadcrumbSeparator(parent, variableByName, stats) {
  const icon = await createFixedIconInstance(
    "chevron-right",
    "Colors/foreground/400",
    "#5D626F",
    variableByName,
    stats,
    14,
  );
  parent.appendChild(icon);
  setHugChildSizing(icon);
  return icon;
}

function appendBreadcrumbEllipsis(parent, variableByName, stats) {
  const frame = figma.createFrame();
  frame.name = "Breadcrumb Ellipsis";
  frame.layoutMode = "HORIZONTAL";
  frame.primaryAxisSizingMode = "FIXED";
  frame.counterAxisSizingMode = "FIXED";
  frame.primaryAxisAlignItems = "CENTER";
  frame.counterAxisAlignItems = "CENTER";
  frame.itemSpacing = 3;
  frame.paddingLeft = 0;
  frame.paddingRight = 0;
  frame.paddingTop = 0;
  frame.paddingBottom = 0;
  frame.resizeWithoutConstraints(36, 36);
  frame.fills = [];
  frame.strokes = [];
  frame.strokeWeight = 0;
  frame.clipsContent = false;
  bindSizeVariables(
    frame,
    "Breadcrumb/ellipsis/size",
    "Breadcrumb/ellipsis/size",
    variableByName,
    stats,
  );

  for (let index = 0; index < 3; index += 1) {
    const dot = figma.createEllipse();
    dot.name = "Ellipsis Dot";
    dot.resizeWithoutConstraints(4, 4);
    dot.fills = [
      paintFromVariable(
        "Colors/foreground/400",
        "#5D626F",
        variableByName,
        stats,
      ),
    ];
    dot.strokes = [];
    frame.appendChild(dot);
    setHugChildSizing(dot);
  }

  parent.appendChild(frame);
}

async function createPaginationVariant({
  content,
  size,
  variableByName,
  fonts,
  stats,
}) {
  const component = figma.createComponent();
  await updatePaginationVariant(component, {
    content,
    size,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

function parsePaginationVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (
    PAGINATION_CONTENT.indexOf(values.Content) === -1 ||
    PAGINATION_SIZES.indexOf(values.Size) === -1
  ) {
    return null;
  }

  return {
    content: values.Content,
    size: values.Size,
  };
}

function paginationVariantKey(props) {
  return `${props.content}/${props.size}`;
}

function layoutPaginationVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parsePaginationVariantName(child.name);
    if (!props) continue;

    const contentIndex = PAGINATION_CONTENT.indexOf(props.content);
    const sizeIndex = PAGINATION_SIZES.indexOf(props.size);
    child.x = contentIndex * 540;
    child.y = sizeIndex * 100;
  }
}

async function updatePaginationVariant(
  component,
  { content, size, variableByName, fonts, stats },
) {
  const metrics = paginationMetrics(size, content);

  component.name = `Content=${content}, Size=${size}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = metrics.gap;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(metrics.width, metrics.height);
  component.fills = [];
  component.strokes = [];
  component.strokeWeight = 0;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Pagination");

  const oldChildren = Array.from(component.children || []);
  for (const child of oldChildren) child.remove();

  const controls = [];
  controls.push(
    await appendPaginationControl({
      parent: component,
      name: "Pagination Previous",
      textName: "Previous Text",
      text: "Previous",
      role: "previous",
      widthToken: metrics.actionWidthToken,
      width: metrics.actionWidth,
      icon: "chevron-left",
      iconPosition: "before",
      active: false,
      metrics,
      variableByName,
      fonts,
      stats,
    }),
  );

  if (content === "Compact") {
    controls.push(
      await appendPaginationControl({
        parent: component,
        name: "Pagination Compact",
        textName: "Compact Text",
        text: "2 / 10",
        role: "compact",
        widthToken: metrics.compactLabelWidthToken,
        width: metrics.compactLabelWidth,
        active: false,
        quiet: true,
        metrics,
        variableByName,
        fonts,
        stats,
      }),
    );
  } else {
    controls.push(
      await appendPaginationControl({
        parent: component,
        name: "Pagination Page 1",
        textName: "Page 1 Text",
        text: "1",
        role: "page",
        width: metrics.itemSize,
        active: false,
        metrics,
        variableByName,
        fonts,
        stats,
      }),
    );
    controls.push(
      await appendPaginationControl({
        parent: component,
        name: "Pagination Page 2",
        textName: "Page 2 Text",
        text: "2",
        role: "page",
        width: metrics.itemSize,
        active: true,
        metrics,
        variableByName,
        fonts,
        stats,
      }),
    );
    controls.push(
      await appendPaginationControl({
        parent: component,
        name: "Pagination Page 3",
        textName: "Page 3 Text",
        text: "3",
        role: "page",
        width: metrics.itemSize,
        active: false,
        metrics,
        variableByName,
        fonts,
        stats,
      }),
    );

    if (content === "Ellipsis") {
      controls.push(
        appendPaginationEllipsis(component, metrics, variableByName, stats),
      );
      controls.push(
        await appendPaginationControl({
          parent: component,
          name: "Pagination Last Page",
          textName: "Last Page Text",
          text: "10",
          role: "page",
          width: metrics.itemSize,
          active: false,
          metrics,
          variableByName,
          fonts,
          stats,
        }),
      );
    }
  }

  controls.push(
    await appendPaginationControl({
      parent: component,
      name: "Pagination Next",
      textName: "Next Text",
      text: "Next",
      role: "next",
      widthToken: metrics.actionWidthToken,
      width: metrics.actionWidth,
      icon: "chevron-right",
      iconPosition: "after",
      active: false,
      metrics,
      variableByName,
      fonts,
      stats,
    }),
  );

  bindPaginationGeometryVariables(
    component,
    metrics,
    controls,
    variableByName,
    stats,
  );
}

async function appendPaginationControl({
  parent,
  name,
  textName,
  text,
  role,
  widthToken,
  width,
  icon,
  iconPosition,
  active,
  quiet,
  metrics,
  variableByName,
  fonts,
  stats,
}) {
  const frame = figma.createFrame();
  frame.name = name;
  frame.layoutMode = "HORIZONTAL";
  frame.primaryAxisSizingMode = "FIXED";
  frame.counterAxisSizingMode = "FIXED";
  frame.primaryAxisAlignItems = "CENTER";
  frame.counterAxisAlignItems = "CENTER";
  frame.itemSpacing = icon ? 6 : 0;
  frame.paddingLeft = 0;
  frame.paddingRight = 0;
  frame.paddingTop = 0;
  frame.paddingBottom = 0;
  frame.resizeWithoutConstraints(width, metrics.height);
  frame.cornerRadius = metrics.radius;
  frame.clipsContent = false;
  frame.setSharedPluginData(RUN_NAMESPACE, "kind", "pagination-control");
  frame.setSharedPluginData(RUN_NAMESPACE, "role", role);

  if (active) {
    frame.fills = [
      paintFromVariable("Surface/0", "#FFFFFF", variableByName, stats),
    ];
    frame.strokes = [
      paintFromVariable("Colors/theme/600", "#1051E8", variableByName, stats),
    ];
    frame.strokeWeight = 1;
  } else {
    frame.fills = [];
    frame.strokes = [];
    frame.strokeWeight = 0;
  }

  const foreground = active
    ? { token: "Colors/theme/600", fallback: "#1051E8" }
    : quiet
      ? { token: "Colors/foreground/400", fallback: "#5D626F" }
      : { token: "Colors/foreground/0", fallback: "#000000" };

  async function appendIcon(iconName) {
    const iconNode = await createFixedIconInstance(
      iconName,
      foreground.token,
      foreground.fallback,
      variableByName,
      stats,
      metrics.iconSize,
      "Pagination/icon/size",
    );
    frame.appendChild(iconNode);
    setHugChildSizing(iconNode);
  }

  if (icon && iconPosition === "before") await appendIcon(icon);

  const label = figma.createText();
  label.name = textName;
  await applyPaginationLabelTypography(
    label,
    metrics,
    fonts,
    variableByName,
    stats,
  );
  label.characters = text;
  label.fills = [
    paintFromVariable(
      foreground.token,
      foreground.fallback,
      variableByName,
      stats,
    ),
  ];
  label.textAlignHorizontal = "CENTER";
  label.textAlignVertical = "CENTER";
  frame.appendChild(label);
  setHugChildSizing(label);

  if (icon && iconPosition === "after") await appendIcon(icon);

  parent.appendChild(frame);

  return {
    node: frame,
    widthToken: widthToken || "Pagination/item/size",
    hasStroke: active,
  };
}

function appendPaginationEllipsis(parent, metrics, variableByName, stats) {
  const frame = figma.createFrame();
  frame.name = "Pagination Ellipsis";
  frame.layoutMode = "HORIZONTAL";
  frame.primaryAxisSizingMode = "FIXED";
  frame.counterAxisSizingMode = "FIXED";
  frame.primaryAxisAlignItems = "CENTER";
  frame.counterAxisAlignItems = "CENTER";
  frame.itemSpacing = 3;
  frame.paddingLeft = 0;
  frame.paddingRight = 0;
  frame.paddingTop = 0;
  frame.paddingBottom = 0;
  frame.resizeWithoutConstraints(metrics.itemSize, metrics.height);
  frame.cornerRadius = metrics.radius;
  frame.fills = [];
  frame.strokes = [];
  frame.strokeWeight = 0;
  frame.clipsContent = false;
  frame.setSharedPluginData(RUN_NAMESPACE, "kind", "pagination-control");
  frame.setSharedPluginData(RUN_NAMESPACE, "role", "ellipsis");

  for (let index = 0; index < 3; index += 1) {
    const dot = figma.createEllipse();
    dot.name = "Ellipsis Dot";
    dot.resizeWithoutConstraints(4, 4);
    dot.fills = [
      paintFromVariable(
        "Colors/foreground/400",
        "#5D626F",
        variableByName,
        stats,
      ),
    ];
    dot.strokes = [];
    frame.appendChild(dot);
    setHugChildSizing(dot);
  }

  parent.appendChild(frame);

  return {
    node: frame,
    widthToken: "Pagination/item/size",
    hasStroke: false,
  };
}

async function createAccordionVariant({ value, variableByName, fonts, stats }) {
  const component = figma.createComponent();
  await updateAccordionVariant(component, {
    value,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

function parseAccordionVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (ACCORDION_STATES.indexOf(values.State) === -1) return null;

  return {
    value: values.State,
    state: values.State,
  };
}

async function updateAccordionVariant(
  component,
  { value, variableByName, fonts, stats },
) {
  const isOpen = value === "Open";
  component.name = `State=${value}`;
  component.layoutMode = "VERTICAL";
  component.primaryAxisSizingMode = "AUTO";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "MIN";
  component.counterAxisAlignItems = "MIN";
  component.itemSpacing = 0;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(360, isOpen ? 128 : 53);
  component.fills = [];
  component.strokes = [
    paintFromVariable("Border/Subtle", "#C7CAD1", variableByName, stats),
  ];
  component.strokeWeight = 1;
  component.strokeTopWeight = 0;
  component.strokeRightWeight = 0;
  component.strokeBottomWeight = 1;
  component.strokeLeftWeight = 0;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Accordion");

  bindFloatVariable(
    component,
    "width",
    "Accordion/width/default",
    variableByName,
    stats,
  );
  clearBoundVariable(component, "height", stats);
  setLayoutSizingHorizontal(component, "FIXED");
  setLayoutSizingVertical(component, "HUG");
  bindFloatVariable(
    component,
    "strokeBottomWeight",
    "Accordion/divider/height",
    variableByName,
    stats,
  );

  const oldChildren = [];
  for (const child of component.children || []) {
    oldChildren.push(child);
  }
  for (const child of oldChildren) {
    child.remove();
  }

  const trigger = figma.createFrame();
  trigger.name = "Accordion Trigger";
  trigger.layoutMode = "HORIZONTAL";
  trigger.primaryAxisSizingMode = "FIXED";
  trigger.counterAxisSizingMode = "FIXED";
  trigger.primaryAxisAlignItems = "MIN";
  trigger.counterAxisAlignItems = "CENTER";
  trigger.itemSpacing = 16;
  trigger.paddingLeft = 0;
  trigger.paddingRight = 0;
  trigger.paddingTop = 0;
  trigger.paddingBottom = 0;
  trigger.resizeWithoutConstraints(360, 52);
  trigger.fills = [];
  trigger.strokes = [];
  trigger.strokeWeight = 0;
  trigger.clipsContent = false;
  bindSizeVariables(
    trigger,
    "Accordion/width/default",
    "Accordion/trigger/height",
    variableByName,
    stats,
  );
  setVerticalFixedFillChildSizing(trigger);

  await appendAccordionText({
    parent: trigger,
    name: "Trigger Text",
    characters: "Is it accessible?",
    fontToken: "Accordion/trigger/font-size",
    lineHeightToken: "Accordion/trigger/line-height",
    colorToken: "Colors/foreground/0",
    colorFallback: "#000000",
    fillHorizontal: true,
    fonts,
    variableByName,
    stats,
  });
  await appendAccordionChevron({
    parent: trigger,
    isOpen,
    variableByName,
    stats,
  });
  component.appendChild(trigger);

  if (isOpen) {
    const content = figma.createFrame();
    content.name = "Accordion Content";
    content.layoutMode = "VERTICAL";
    content.primaryAxisSizingMode = "AUTO";
    content.counterAxisSizingMode = "FIXED";
    content.primaryAxisAlignItems = "MIN";
    content.counterAxisAlignItems = "MIN";
    content.itemSpacing = 0;
    content.paddingLeft = 0;
    content.paddingRight = 0;
    content.paddingTop = 0;
    content.paddingBottom = 16;
    content.resizeWithoutConstraints(360, 36);
    content.fills = [];
    content.strokes = [];
    content.strokeWeight = 0;
    content.clipsContent = false;
    bindFloatVariable(
      content,
      "width",
      "Accordion/width/default",
      variableByName,
      stats,
    );
    clearBoundVariable(content, "height", stats);
    bindFloatVariable(
      content,
      "paddingBottom",
      "Accordion/content/padding-bottom",
      variableByName,
      stats,
    );
    setVerticalStackChildSizing(content);
    await appendAccordionText({
      parent: content,
      name: "Content Text",
      characters: "Yes. It follows the WAI-ARIA disclosure pattern.",
      fontToken: "Accordion/content/font-size",
      lineHeightToken: "Accordion/content/line-height",
      colorToken: "Colors/foreground/400",
      colorFallback: "#5D626F",
      fillHorizontal: true,
      fonts,
      variableByName,
      stats,
    });
    component.appendChild(content);
  }
}

async function appendAccordionText({
  parent,
  name,
  characters,
  fontToken,
  lineHeightToken,
  colorToken,
  colorFallback,
  fillHorizontal = false,
  fonts,
  variableByName,
  stats,
}) {
  const text = figma.createText();
  text.name = name;
  text.fontName = fonts.regular;
  text.fontSize = 14;
  text.lineHeight = { unit: "PIXELS", value: 20 };
  await applyTextStyleToNodeAsync(
    text,
    name === "Trigger Text" ? "accordionTrigger" : "accordionContent",
    stats,
  );
  text.characters = characters;
  text.fills = [
    paintFromVariable(colorToken, colorFallback, variableByName, stats),
  ];
  setNodePropertyIfSupported(text, "textAlignHorizontal", "LEFT");
  setNodePropertyIfSupported(
    text,
    "textAlignVertical",
    name === "Trigger Text" ? "CENTER" : "TOP",
  );
  setTextAutoResize(text, fillHorizontal ? "HEIGHT" : "WIDTH_AND_HEIGHT");
  bindFloatVariable(text, "fontSize", fontToken, variableByName, stats);
  bindFloatVariable(text, "lineHeight", lineHeightToken, variableByName, stats);
  parent.appendChild(text);
  if (fillHorizontal) {
    setLayoutSizingHorizontal(text, "FILL");
    setLayoutSizingVertical(text, "HUG");
    try {
      text.layoutAlign = "STRETCH";
    } catch (_error) {
      // layoutAlign is unavailable on older plugin runtimes.
    }
    try {
      text.layoutGrow = 1;
    } catch (_error) {
      // layoutGrow is unavailable on older plugin runtimes.
    }
    try {
      text.constraints = { horizontal: "STRETCH", vertical: "MIN" };
    } catch (_error) {
      // Constraints are not available on every node type.
    }
  } else {
    setHugChildSizing(text);
  }
  return text;
}

async function appendAccordionChevron({
  parent,
  isOpen,
  variableByName,
  stats,
}) {
  const icon = await createFixedIconInstance(
    isOpen ? "chevron-up" : "chevron-down",
    "Colors/foreground/400",
    "#5D626F",
    variableByName,
    stats,
    16,
  );
  parent.appendChild(icon);
  setHugChildSizing(icon);
  return icon;
}

function parseCounterVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (
    COUNTER_TONES.indexOf(values.Tone) === -1 ||
    COUNTER_SIZES.indexOf(values.Size) === -1
  ) {
    return null;
  }

  return {
    tone: values.Tone,
    size: values.Size,
  };
}

function parseChipVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (
    CHIP_VARIANTS.indexOf(values.Variant) === -1 ||
    CHIP_SIZES.indexOf(values.Size) === -1 ||
    CHIP_STATES.indexOf(values.State) === -1 ||
    CHIP_REMOVABLE.indexOf(values.Removable) === -1
  ) {
    return null;
  }

  return {
    variant: values.Variant,
    size: values.Size,
    state: values.State,
    removable: values.Removable,
  };
}

function chipVariantKey(props) {
  return `${props.variant}/${props.size}/${props.state}/${props.removable}`;
}

function layoutChipVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseChipVariantName(child.name);
    if (!props) continue;

    const variantIndex = CHIP_VARIANTS.indexOf(props.variant);
    const sizeIndex = CHIP_SIZES.indexOf(props.size);
    const stateIndex = CHIP_STATES.indexOf(props.state);
    const removableIndex = CHIP_REMOVABLE.indexOf(props.removable);
    const flatIndex =
      ((variantIndex * CHIP_SIZES.length + sizeIndex) * CHIP_STATES.length +
        stateIndex) *
        CHIP_REMOVABLE.length +
      removableIndex;
    child.x = (flatIndex % 6) * 180;
    child.y = Math.floor(flatIndex / 6) * 76;
  }
}

async function updateChipVariant(
  component,
  { variant, size, state, removable, variableByName, fonts, stats },
) {
  const metrics = chipMetrics(size);
  const config = chipConfig(variant, state);

  component.name = `Variant=${variant}, Size=${size}, State=${state}, Removable=${removable}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "AUTO";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = metrics.gap;
  component.paddingLeft = metrics.paddingX;
  component.paddingRight = metrics.paddingX;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(metrics.minWidth, metrics.height);
  component.cornerRadius = KOZMOS_RADIUS.pill;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Chip");

  component.fills = config.background
    ? [
        paintFromVariable(
          config.background,
          config.backgroundFallback,
          variableByName,
          stats,
        ),
      ]
    : [];
  component.strokes = [
    paintFromVariable(
      config.stroke,
      config.strokeFallback,
      variableByName,
      stats,
    ),
  ];
  component.strokeWeight = 1;

  bindChipGeometryVariables(component, metrics, variableByName, stats);

  await syncChipVariantChildren({
    component,
    variant,
    size,
    removable,
    config,
    variableByName,
    fonts,
    stats,
  });

  syncFocusRing(component, {
    enabled: state !== "Disabled",
    width: Math.max(metrics.minWidth, component.width),
    height: metrics.height,
    radius: KOZMOS_RADIUS.pill,
    variableName: "Colors/theme/500",
    fallback: "#135BEC",
    variableByName,
    stats,
  });
}

function parseSegmentedControlVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (
    SEGMENTED_CONTROL_SIZES.indexOf(values.Size) === -1 ||
    SEGMENTED_CONTROL_ACTIVE.indexOf(values.Active) === -1 ||
    SEGMENTED_CONTROL_STATES.indexOf(values.State) === -1
  ) {
    return null;
  }

  return {
    size: values.Size,
    active: values.Active,
    state: values.State,
  };
}

function segmentedControlVariantKey(props) {
  return `${props.size}/${props.active}/${props.state}`;
}

function layoutSegmentedControlVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  const columns = 4;
  const columnGap = 48;
  const rowGap = 32;
  let maxWidth = 0;
  let maxHeight = 0;

  for (const size of SEGMENTED_CONTROL_SIZES) {
    const metrics = segmentedControlMetrics(size);
    maxWidth = Math.max(maxWidth, metrics.width);
    maxHeight = Math.max(maxHeight, metrics.height);
  }

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;
    if (typeof child.width === "number" && Number.isFinite(child.width)) {
      maxWidth = Math.max(maxWidth, child.width);
    }
  }

  const xStep = maxWidth + columnGap;
  const yStep = maxHeight + rowGap;
  let maxFlatIndex = 0;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseSegmentedControlVariantName(child.name);
    if (!props) continue;

    const sizeIndex = SEGMENTED_CONTROL_SIZES.indexOf(props.size);
    const activeIndex = SEGMENTED_CONTROL_ACTIVE.indexOf(props.active);
    const stateIndex = SEGMENTED_CONTROL_STATES.indexOf(props.state);
    const flatIndex =
      (sizeIndex * SEGMENTED_CONTROL_ACTIVE.length + activeIndex) *
        SEGMENTED_CONTROL_STATES.length +
      stateIndex;
    maxFlatIndex = Math.max(maxFlatIndex, flatIndex);
    child.x = (flatIndex % columns) * xStep;
    child.y = Math.floor(flatIndex / columns) * yStep;
  }

  const rows = Math.floor(maxFlatIndex / columns) + 1;
  resizeNodeWithoutConstraints(
    componentSet,
    columns * maxWidth + (columns - 1) * columnGap,
    rows * maxHeight + (rows - 1) * rowGap,
  );
  componentSet.clipsContent = false;
}

async function updateSegmentedControlVariant(
  component,
  { size, active, state, variableByName, fonts, stats },
) {
  const metrics = segmentedControlMetrics(size);
  const activeIndex = segmentedControlActiveIndex(active);
  const config = segmentedControlConfig(state);

  component.name = `Size=${size}, Active=${active}, State=${state}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "AUTO";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = 0;
  component.paddingLeft = metrics.padding;
  component.paddingRight = metrics.padding;
  component.paddingTop = metrics.padding;
  component.paddingBottom = metrics.padding;
  component.resizeWithoutConstraints(metrics.width, metrics.height);
  setNodePropertyIfSupported(component, "minWidth", metrics.width);
  setNodePropertyIfSupported(component, "minHeight", metrics.height);
  component.cornerRadius = metrics.radius;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "SegmentedControl");

  component.fills = [
    paintFromVariable(
      config.background,
      config.backgroundFallback,
      variableByName,
      stats,
    ),
  ];
  component.strokes = [
    paintFromVariable(
      config.stroke,
      config.strokeFallback,
      variableByName,
      stats,
    ),
  ];
  component.strokeWeight = 1;

  bindSegmentedControlGeometryVariables(
    component,
    metrics,
    variableByName,
    stats,
  );

  const sizing = await syncSegmentedControlVariantChildren({
    component,
    activeIndex,
    state,
    metrics,
    variableByName,
    fonts,
    stats,
  });

  resizeNodeWithoutConstraints(
    component,
    sizing && sizing.controlWidth ? sizing.controlWidth : metrics.width,
    metrics.height,
  );
  component.primaryAxisSizingMode = "AUTO";
}

