function parseBadgeVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (
    BADGE_VARIANTS.indexOf(values.Variant) === -1 ||
    BADGE_SIZES.indexOf(values.Size) === -1
  ) {
    return null;
  }

  return {
    variant: values.Variant,
    size: values.Size,
  };
}

async function updateBadgeVariant(
  component,
  { variant, size, variableByName, iconComponent, fonts, stats },
) {
  const config = badgeConfig(variant);
  const metrics = badgeMetrics(size);

  component.name = `Variant=${variant}, Size=${size}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = size === "Icon" ? "FIXED" : "AUTO";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = size === "Icon" ? 0 : 4;
  component.paddingLeft = metrics.paddingX;
  component.paddingRight = metrics.paddingX;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(metrics.width, metrics.height);
  component.cornerRadius = KOZMOS_RADIUS.control;
  component.clipsContent = false;
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Badge");

  component.fills = config.background
    ? [
        paintFromVariable(
          config.background,
          config.backgroundFallback,
          variableByName,
          stats,
        ),
      ]
    : [];

  if (config.stroke) {
    component.strokes = [
      paintFromVariable(
        config.stroke,
        config.strokeFallback,
        variableByName,
        stats,
      ),
    ];
    component.strokeWeight = 1;
  } else {
    component.strokes = [];
    component.strokeWeight = 0;
  }

  bindBadgeGeometryVariables(component, metrics, config, variableByName, stats);

  await syncBadgeVariantChildren({
    component,
    variant,
    size,
    config,
    variableByName,
    iconComponent,
    fonts,
    stats,
  });
}

async function createCardVariant({
  value,
  second,
  variableByName,
  fonts,
  stats,
}) {
  const component = figma.createComponent();
  await updateCardVariant(component, {
    value,
    second,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

function parseCardVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  if (CARD_CONTENT.indexOf(values.Content) === -1) {
    return null;
  }

  // A variant drawn before the Padding axis carries no Padding, and is the
  // card as it was: 24. Reading it as Default is what lets Update rename it
  // instead of replacing it, so its node id survives.
  const second = values.Padding || "Default";
  if (CARD_PADDINGS.indexOf(second) === -1) {
    return null;
  }

  return {
    value: values.Content,
    second,
  };
}

async function updateCardVariant(
  component,
  { value, second, variableByName, fonts, stats },
) {
  const padding = CARD_PADDINGS.indexOf(second) === -1 ? "Default" : second;
  component.name = `Content=${value}, Padding=${padding}`;
  component.layoutMode = "VERTICAL";
  component.primaryAxisSizingMode = "AUTO";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "MIN";
  component.counterAxisAlignItems = "MIN";
  component.itemSpacing = 0;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  component.resizeWithoutConstraints(360, 100);
  component.cornerRadius = KOZMOS_RADIUS.container;
  component.clipsContent = false;
  component.fills = [
    paintFromVariable("Surface/0", "#FFFFFF", variableByName, stats),
  ];
  component.strokes = [
    paintFromVariable("Border/Subtle", "#C7CAD1", variableByName, stats),
  ];
  component.strokeWeight = 1;
  component.effects = [elevationEffect("raised")];
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Card");

  await syncCardVariantChildren({
    component,
    value,
    padding,
    variableByName,
    fonts,
    stats,
  });
}

