async function createRatingVariant({
  scale,
  value,
  state,
  variableByName,
  fonts,
  stats,
}) {
  const component = figma.createComponent();
  await updateRatingVariant(component, {
    scale,
    value,
    state,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

function parseRatingVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  const value = values.Value;
  const state = values.State || "Default";
  // Older variants carry no Scale: they are the stars, which is what the set
  // held before thumbs existed. Reading them as Stars is what lets Update
  // keep their node ids instead of replacing them.
  const scale = values.Scale || "Stars";

  if (
    RATING_SCALES.indexOf(scale) === -1 ||
    ratingValuesForScale(scale).indexOf(value) === -1 ||
    RATING_STATES.indexOf(state) === -1
  ) {
    return null;
  }

  return { scale, value, state };
}

async function updateRatingVariant(
  component,
  { scale, value, state, variableByName, fonts, stats },
) {
  const resolvedScale = RATING_SCALES.indexOf(scale) === -1 ? "Stars" : scale;
  component.name = `Scale=${resolvedScale}, Value=${value}, State=${state}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = 0;
  component.paddingLeft = 0;
  component.paddingRight = 0;
  component.paddingTop = 0;
  component.paddingBottom = 0;
  // Two 44 cells for thumbs, five for stars, plus the 8 between the thumbs.
  // 8 between the two thumbs; the stars space themselves inside their cells.
  component.itemSpacing = resolvedScale === "Thumbs" ? 8 : 0;
  component.resizeWithoutConstraints(resolvedScale === "Thumbs" ? 96 : 220, 44);
  component.cornerRadius = KOZMOS_RADIUS.none;
  component.clipsContent = false;
  component.fills = [];
  component.strokes = [];
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Rating");

  await syncRatingVariantChildren({
    component,
    scale: resolvedScale,
    value,
    state,
    variableByName,
    fonts,
    stats,
  });
}

function layoutRatingVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseRatingVariantName(child.name);
    if (!props) continue;

    const valueIndex = RATING_VALUES.indexOf(props.value);
    const stateIndex = RATING_STATES.indexOf(props.state);
    const scaleIndex = RATING_SCALES.indexOf(props.scale);
    child.x = valueIndex * 260;
    // Each scale takes its own band of rows, so the two never overlap.
    child.y = (scaleIndex * RATING_STATES.length + stateIndex) * 80;
  }

  resizeComponentSetToContainChildren(componentSet);
}

async function createStepperVariant({
  count,
  current,
  variableByName,
  fonts,
  stats,
}) {
  const component = figma.createComponent();
  await updateStepperVariant(component, {
    count,
    current,
    variableByName,
    fonts,
    stats,
  });
  return component;
}

function parseStepperVariantName(name) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  const count = values.Count;
  const current = values.Current || "1";

  if (
    STEPPER_COUNTS.indexOf(count) === -1 ||
    STEPPER_CURRENT.indexOf(current) === -1 ||
    stepperCurrentIndex(current) >= stepperCountNumber(count)
  ) {
    return null;
  }

  return { count, current };
}

async function updateStepperVariant(
  component,
  { count, current, variableByName, fonts, stats },
) {
  const countNumber = stepperCountNumber(count);
  const width = stepperWidth(countNumber);

  component.name = `Count=${count}, Current=${current}`;
  component.layoutMode = "NONE";
  component.resizeWithoutConstraints(width, 72);
  component.cornerRadius = KOZMOS_RADIUS.none;
  component.clipsContent = false;
  component.fills = [];
  component.strokes = [];
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Stepper");

  await syncStepperVariantChildren({
    component,
    count,
    current,
    variableByName,
    fonts,
    stats,
  });
}

function layoutStepperVariants(componentSet) {
  if (!componentSet || !componentSet.children) return;

  for (const child of componentSet.children) {
    if (child.type !== "COMPONENT") continue;

    const props = parseStepperVariantName(child.name);
    if (!props) continue;

    const countIndex = STEPPER_COUNTS.indexOf(props.count);
    const currentIndex = STEPPER_CURRENT.indexOf(props.current);
    child.x = countIndex * 760;
    child.y = currentIndex * 116;
  }

  resizeComponentSetToContainChildren(componentSet);
}

async function syncRatingVariantChildren({
  component,
  scale,
  value,
  state,
  variableByName,
  fonts,
  stats,
}) {
  for (const child of Array.from(component.children || [])) {
    child.remove();
  }

  const valueNumber = Number(value);
  const readonly = state === "Readonly";

  if (scale === "Thumbs") {
    // A choice between two, so exactly the one chosen fills. Down is 1 and up
    // is 2, the same "1 is the lowest" rule the stars follow, so a product
    // stores one shape whichever scale it asks on.
    for (let index = 1; index <= 2; index += 1) {
      const thumb = await createRatingThumb({
        index,
        chosen: index === valueNumber,
        readonly,
        variableByName,
        stats,
      });
      component.appendChild(thumb);
    }
    return;
  }

  for (let index = 1; index <= 5; index += 1) {
    const star = await createRatingStar({
      index,
      filled: index <= valueNumber,
      readonly,
      variableByName,
      fonts,
      stats,
    });
    component.appendChild(star);
  }
}

/**
 * One thumb: a 40 disc in a 44 target, as every other control's hit area is.
 * Chosen is the theme's colour on its own wash with a 2 ring; unchosen is the
 * muted background with the foreground's quiet grey and no ring.
 */
async function createRatingThumb({
  index,
  chosen,
  readonly,
  variableByName,
  stats,
}) {
  const cell = figma.createFrame();
  cell.name = index === 1 ? "Rating Thumb Down" : "Rating Thumb Up";
  cell.layoutMode = "HORIZONTAL";
  cell.primaryAxisSizingMode = "FIXED";
  cell.counterAxisSizingMode = "FIXED";
  cell.primaryAxisAlignItems = "CENTER";
  cell.counterAxisAlignItems = "CENTER";
  cell.resizeWithoutConstraints(44, 44);
  cell.cornerRadius = KOZMOS_RADIUS.pill;
  cell.clipsContent = false;
  cell.fills = [];
  cell.strokes = [];
  cell.opacity = readonly ? 0.72 : 1;
  cell.setSharedPluginData(RUN_NAMESPACE, "kind", "rating-thumb-hit-area");
  setFixedChildSizing(cell);

  const disc = figma.createFrame();
  disc.name = "Thumb Disc";
  disc.layoutMode = "HORIZONTAL";
  disc.primaryAxisSizingMode = "FIXED";
  disc.counterAxisSizingMode = "FIXED";
  disc.primaryAxisAlignItems = "CENTER";
  disc.counterAxisAlignItems = "CENTER";
  disc.resizeWithoutConstraints(40, 40);
  disc.cornerRadius = KOZMOS_RADIUS.pill;
  disc.clipsContent = false;
  disc.fills = [
    chosen
      ? paintFromVariable("Colors/theme/0", "#F1F5FE", variableByName, stats)
      : paintFromVariable(
          "Colors/background/100",
          "#F2F4F7",
          variableByName,
          stats,
        ),
  ];
  disc.strokes = chosen
    ? [paintFromVariable("Colors/theme/600", "#1051E8", variableByName, stats)]
    : [];
  disc.strokeWeight = chosen ? 2 : 0;
  disc.setSharedPluginData(RUN_NAMESPACE, "kind", "rating-thumb-disc");
  setFixedChildSizing(disc);

  const icon = await createFixedIconInstance(
    index === 1 ? "thumbs-down" : "thumbs-up",
    chosen ? "Colors/theme/600" : "Colors/foreground/400",
    chosen ? "#1051E8" : "#5D626F",
    variableByName,
    stats,
    20,
    "Rating/thumb/icon/size",
  );
  disc.appendChild(icon);
  setHugChildSizing(icon);

  cell.appendChild(disc);
  return cell;
}

async function createRatingStar({
  index,
  filled,
  readonly,
  variableByName,
  fonts,
  stats,
}) {
  const cell = figma.createFrame();
  cell.name = `Rating Star ${index}`;
  cell.layoutMode = "HORIZONTAL";
  cell.primaryAxisSizingMode = "FIXED";
  cell.counterAxisSizingMode = "FIXED";
  cell.primaryAxisAlignItems = "CENTER";
  cell.counterAxisAlignItems = "CENTER";
  cell.resizeWithoutConstraints(44, 44);
  cell.cornerRadius = KOZMOS_RADIUS.control;
  cell.clipsContent = false;
  cell.fills = [];
  cell.strokes = [];
  cell.opacity = readonly ? 0.72 : 1;
  cell.setSharedPluginData(RUN_NAMESPACE, "kind", "rating-star-hit-area");
  setFixedChildSizing(cell);

  if (typeof figma.createStar === "function") {
    const glyph = figma.createStar();
    glyph.name = filled ? "Star / filled" : "Star / empty";
    glyph.pointCount = 5;
    glyph.innerRadius = 0.45;
    glyph.resizeWithoutConstraints(22, 22);
    glyph.fills = filled
      ? [paintFromVariable("Data/Yellow", "#A66A00", variableByName, stats)]
      : [];
    glyph.strokes = [
      paintFromVariable(
        filled ? "Data/Yellow" : "Colors/foreground/500",
        filled ? "#A66A00" : "#747B8B",
        variableByName,
        stats,
      ),
    ];
    glyph.strokeWeight = 1.5;
    glyph.setSharedPluginData(RUN_NAMESPACE, "kind", "rating-star-glyph");
    cell.appendChild(glyph);
    return cell;
  }

  const fallback = figma.createText();
  fallback.name = filled ? "Star / filled" : "Star / empty";
  fallback.fontName = fonts.medium;
  fallback.fontSize = 20;
  fallback.lineHeight = { unit: "PIXELS", value: 20 };
  fallback.characters = "*";
  await applyTextStyleToNodeAsync(fallback, "buttonLabel", stats);
  fallback.textAlignHorizontal = "CENTER";
  fallback.textAlignVertical = "CENTER";
  fallback.fills = [
    paintFromVariable(
      filled ? "Data/Yellow" : "Colors/foreground/500",
      filled ? "#A66A00" : "#747B8B",
      variableByName,
      stats,
    ),
  ];
  setTextAutoResize(fallback, "WIDTH_AND_HEIGHT");
  cell.appendChild(fallback);
  return cell;
}

function stepperCountNumber(count) {
  const parsed = Number(count);
  return Number.isFinite(parsed) ? parsed : 2;
}

function stepperCurrentIndex(current) {
  const parsed = Number(current);
  return Number.isFinite(parsed) ? Math.max(0, parsed - 1) : 0;
}

function stepperWidth(countNumber) {
  const stepWidth = 88;
  const connectorWidth = 92;
  return (
    countNumber * stepWidth + Math.max(0, countNumber - 1) * connectorWidth
  );
}

async function syncStepperVariantChildren({
  component,
  count,
  current,
  variableByName,
  fonts,
  stats,
}) {
  for (const child of Array.from(component.children || [])) {
    child.remove();
  }

  const countNumber = stepperCountNumber(count);
  const currentIndex = stepperCurrentIndex(current);
  const stepWidth = 88;
  const connectorWidth = 92;
  const stepLabels = ["Details", "Shipping", "Payment", "Confirm"];

  for (let index = 0; index < countNumber; index += 1) {
    const step = await createStepperStepItem({
      index,
      label: stepLabels[index] || `Step ${index + 1}`,
      currentIndex,
      variableByName,
      fonts,
      stats,
    });
    step.x = index * (stepWidth + connectorWidth);
    step.y = 0;
    component.appendChild(step);

    if (index < countNumber - 1) {
      const connector = createStepperConnector({
        index,
        active: index < currentIndex,
        variableByName,
        stats,
      });
      connector.x = step.x + stepWidth;
      connector.y = 15;
      component.appendChild(connector);
    }
  }
}

async function createStepperStepItem({
  index,
  label,
  currentIndex,
  variableByName,
  fonts,
  stats,
}) {
  const completed = index < currentIndex;
  const current = index === currentIndex;

  const item = figma.createFrame();
  item.name = `Step ${index + 1}`;
  item.layoutMode = "VERTICAL";
  item.primaryAxisSizingMode = "FIXED";
  item.counterAxisSizingMode = "FIXED";
  item.primaryAxisAlignItems = "MIN";
  item.counterAxisAlignItems = "CENTER";
  item.itemSpacing = 8;
  item.paddingLeft = 0;
  item.paddingRight = 0;
  item.paddingTop = 0;
  item.paddingBottom = 0;
  item.resizeWithoutConstraints(88, 72);
  item.fills = [];
  item.strokes = [];
  item.clipsContent = false;
  item.setSharedPluginData(RUN_NAMESPACE, "kind", "stepper-step");

  const indicator = figma.createFrame();
  indicator.name = `Step ${index + 1} Indicator`;
  indicator.layoutMode = "HORIZONTAL";
  indicator.primaryAxisSizingMode = "FIXED";
  indicator.counterAxisSizingMode = "FIXED";
  indicator.primaryAxisAlignItems = "CENTER";
  indicator.counterAxisAlignItems = "CENTER";
  indicator.resizeWithoutConstraints(32, 32);
  indicator.cornerRadius = KOZMOS_RADIUS.pill;
  indicator.clipsContent = false;
  // The accent is React's primary, theme/600, on every platform; it was
  // theme/500 here and on the natives until 2026-09-22. A completed step's
  // ring is its fill's colour, as React and the natives draw it — it was
  // foreground/500 here, a grey ring around the blue.
  indicator.fills = [
    paintFromVariable(
      completed ? "Colors/theme/600" : "Surface/0",
      completed ? "#1051E8" : "#FFFFFF",
      variableByName,
      stats,
    ),
  ];
  indicator.strokes = [
    paintFromVariable(
      current || completed ? "Colors/theme/600" : "Colors/foreground/500",
      current || completed ? "#1051E8" : "#747B8B",
      variableByName,
      stats,
    ),
  ];
  indicator.strokeWeight = current || completed ? 2 : 1;
  indicator.setSharedPluginData(RUN_NAMESPACE, "kind", "stepper-indicator");
  setFixedChildSizing(indicator);

  if (completed) {
    const check = await createFixedIconInstance(
      "check",
      "Surface/0",
      "#FFFFFF",
      variableByName,
      stats,
      16,
      null,
    );
    check.name = "Completed Icon";
    indicator.appendChild(check);
  } else {
    const number = figma.createText();
    number.name = "Step Number";
    number.fontName = fonts.medium;
    number.fontSize = 14;
    number.lineHeight = { unit: "PIXELS", value: 20 };
    number.characters = String(index + 1);
    await applyTextStyleToNodeAsync(number, "fieldText", stats);
    number.textAlignHorizontal = "CENTER";
    number.textAlignVertical = "CENTER";
    number.fills = [
      paintFromVariable(
        "Colors/foreground/0",
        "#0B0D12",
        variableByName,
        stats,
      ),
    ];
    setTextAutoResize(number, "WIDTH_AND_HEIGHT");
    indicator.appendChild(number);
  }

  const text = figma.createText();
  text.name = `Step ${index + 1} Text`;
  text.fontName = current ? fonts.medium : fonts.regular;
  text.fontSize = 12;
  text.lineHeight = { unit: "PIXELS", value: 16 };
  text.characters = label;
  await applyTextStyleToNodeAsync(text, "fieldMeta", stats);
  text.textAlignHorizontal = "CENTER";
  text.textAlignVertical = "CENTER";
  text.resizeWithoutConstraints(88, 32);
  setTextAutoResize(text, "HEIGHT");
  text.fills = [
    paintFromVariable("Colors/foreground/0", "#0B0D12", variableByName, stats),
  ];
  text.setSharedPluginData(RUN_NAMESPACE, "kind", "stepper-label");
  setFixedChildSizing(text);

  item.appendChild(indicator);
  item.appendChild(text);
  return item;
}

function createStepperConnector({ index, active, variableByName, stats }) {
  const connector = figma.createRectangle();
  connector.name = `Step ${index + 1} Connector`;
  connector.resizeWithoutConstraints(92, 2);
  connector.cornerRadius = KOZMOS_RADIUS.pill;
  // The accent, or the border role at its own strength, as React and the
  // natives draw it; the pending connector was faded to 32 % until 2026-09-22.
  connector.fills = [
    paintFromVariable(
      active ? "Colors/theme/600" : "Border/Subtle",
      active ? "#1051E8" : "#C7CAD1",
      variableByName,
      stats,
    ),
  ];
  connector.strokes = [];
  connector.opacity = 1;
  connector.setSharedPluginData(RUN_NAMESPACE, "kind", "stepper-connector");
  return connector;
}

