async function updateToastVariant(
  component,
  { value, variableByName, fonts, stats },
) {
  component.name = `Content=${value}`;
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "AUTO";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.itemSpacing = 16;
  component.paddingLeft = 24;
  component.paddingRight = 32;
  component.paddingTop = 24;
  component.paddingBottom = 24;
  component.resizeWithoutConstraints(420, 100);
  component.cornerRadius = KOZMOS_RADIUS.control;
  component.clipsContent = false;
  component.fills = [
    paintFromVariable("Surface/0", "#FFFFFF", variableByName, stats),
  ];
  component.strokes = [
    paintFromVariable("Border/Subtle", "#C7CAD1", variableByName, stats),
  ];
  component.strokeWeight = 1;
  component.effects = [elevationEffect("floating")];
  component.setSharedPluginData(RUN_NAMESPACE, "kind", "component-variant");
  component.setSharedPluginData(RUN_NAMESPACE, "component", "Toast");

  await syncToastVariantChildren({
    component,
    value,
    variableByName,
    fonts,
    stats,
  });
}

/**
 * One axis's value out of a variant name, or null when it carries none.
 *
 * A set that grows a second axis has to read variants drawn before it: those
 * names have no such key, and the component's parser then supplies its own
 * default so Update RENAMES the variant rather than replacing it. Replacing
 * would change the node id every Code Connect pin on the set depends on.
 */
function variantAxisValue(name, axisName) {
  for (const part of name.split(",")) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    if (part.slice(0, index).trim() !== axisName) continue;
    return part.slice(index + 1).trim();
  }
  return null;
}

function parseSingleAxisVariantName(name, axisName, values) {
  const parts = name.split(",");
  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    if (key !== axisName || values.indexOf(value) === -1) continue;
    return { value };
  }

  return null;
}

function parseStateStatusVariantName(name, states, statuses) {
  const values = {};
  const parts = name.split(",");

  for (const part of parts) {
    const index = part.indexOf("=");
    if (index === -1) continue;
    const key = part.slice(0, index).trim();
    const value = part.slice(index + 1).trim();
    values[key] = value;
  }

  const state = values.State;
  const status = values.Status || "Default";

  if (states.indexOf(state) === -1 || statuses.indexOf(status) === -1) {
    return null;
  }

  return { state, status };
}

async function syncIconButtonChildren({
  component,
  variant,
  state,
  config,
  variableByName,
  iconSize,
  iconSizeToken,
  spinnerSize,
  spinnerSizeToken,
  stats,
}) {
  removeGeneratedButtonChild(
    component,
    "Loading Indicator",
    state !== "Loading",
  );
  removeGeneratedButtonChild(component, "Icon", state === "Loading");
  removeGeneratedButtonChild(component, "Label Text", true);

  if (state === "Loading") {
    let spinner = directChildNamed(component, "Loading Indicator");
    if (spinner && spinner.type !== "ELLIPSE") {
      spinner.remove();
      spinner = null;
    }

    if (!spinner) {
      spinner = createSpinnerGlyph(
        config.foreground,
        config.foregroundFallback,
        variableByName,
        stats,
        spinnerSize,
        spinnerSizeToken,
      );
    } else {
      spinner.resize(spinnerSize, spinnerSize);
      bindSizeVariables(
        spinner,
        spinnerSizeToken,
        spinnerSizeToken,
        variableByName,
        stats,
      );
      spinner.fills = [];
      spinner.strokes = [
        paintFromVariable(
          config.foreground,
          config.foregroundFallback,
          variableByName,
          stats,
        ),
      ];
      spinner.strokeWeight = 2;
      spinner.dashPattern = [8, 4];
    }
    component.appendChild(spinner);
    return;
  }
}

async function syncButtonVariantChildren({
  component,
  variant,
  size,
  state,
  config,
  variableByName,
  fonts,
  textStyle,
  stats,
}) {
  const metrics = buttonMetrics(size);
  removeGeneratedButtonChild(
    component,
    "Loading Indicator",
    state !== "Loading",
  );
  removeGeneratedButtonChild(
    component,
    "Icon",
    size !== "Icon" || state === "Loading",
  );
  removeGeneratedButtonChild(component, "Label Text", size === "Icon");

  if (state === "Loading") {
    let spinner = directChildNamed(component, "Loading Indicator");
    if (spinner && spinner.type !== "ELLIPSE") {
      spinner.remove();
      spinner = null;
    }

    if (!spinner) {
      spinner = createSpinnerGlyph(
        config.foreground,
        config.foregroundFallback,
        variableByName,
        stats,
        metrics.spinnerSize,
        metrics.spinnerSizeToken,
      );
    } else {
      spinner.resize(metrics.spinnerSize, metrics.spinnerSize);
      bindSizeVariables(
        spinner,
        metrics.spinnerSizeToken,
        metrics.spinnerSizeToken,
        variableByName,
        stats,
      );
      spinner.fills = [];
      spinner.strokes = [
        paintFromVariable(
          config.foreground,
          config.foregroundFallback,
          variableByName,
          stats,
        ),
      ];
      spinner.strokeWeight = 2;
      spinner.dashPattern = [8, 4];
    }
    component.appendChild(spinner);
  }

  if (size !== "Icon") {
    let label = directChildNamed(component, "Label Text");
    if (label && label.type !== "TEXT") {
      label.remove();
      label = null;
    }

    if (!label || label.type !== "TEXT") {
      label = figma.createText();
      label.name = "Label Text";
    }

    await applyButtonLabelTypography(
      label,
      fonts,
      textStyle,
      variableByName,
      stats,
    );
    label.characters = state === "Loading" ? "Loading" : variant;
    label.fills = [
      paintFromVariable(
        config.foreground,
        config.foregroundFallback,
        variableByName,
        stats,
      ),
    ];
    label.textDecoration = variant === "Link" ? "UNDERLINE" : "NONE";
    component.appendChild(label);
  }
}

