function removeDirectChildren(parent) {
  if (!parent || !parent.children) return;
  const children = [];
  for (const child of parent.children) children.push(child);
  for (const child of children) child.remove();
}

function removeDirectChildrenExcept(parent, keptChild) {
  if (!parent || !parent.children) return;
  const children = [];
  for (const child of parent.children) {
    if (keptChild && child.id === keptChild.id) continue;
    children.push(child);
  }
  for (const child of children) child.remove();
}

function removeDirectChildrenExceptMany(parent, keptChildren) {
  if (!parent || !parent.children) return;
  const keptIds = new Set();
  for (const child of keptChildren || []) {
    if (child && child.id) keptIds.add(child.id);
  }

  const children = [];
  for (const child of parent.children) {
    if (keptIds.has(child.id)) continue;
    children.push(child);
  }
  for (const child of children) child.remove();
}

function removeDirectChildrenNamed(parent, names) {
  if (!parent || !parent.children) return;
  const nameSet = new Set(names);
  const children = [];
  for (const child of parent.children) {
    if (nameSet.has(child.name)) children.push(child);
  }
  for (const child of children) child.remove();
}

function removeDirectChildrenMatching(parent, predicate) {
  if (!parent || !parent.children) return;
  const children = [];
  for (const child of parent.children) {
    if (predicate(child)) children.push(child);
  }
  for (const child of children) child.remove();
}

function findDescendantNamed(parent, name) {
  if (!parent || !parent.children) return null;

  for (const child of parent.children) {
    if (child.name === name) return child;
    const nested = findDescendantNamed(child, name);
    if (nested) return nested;
  }

  return null;
}

function extractDescendantNamed(parent, name, stats, context) {
  const node = findDescendantNamed(parent, name);
  if (!node) return null;

  try {
    parent.appendChild(node);
    return node;
  } catch (error) {
    if (stats && stats.warnings) {
      stats.warnings.push(
        `Could not preserve ${context || name} (${messageFor(error)}).`,
      );
    }
    return null;
  }
}

function extractReusableSlotsByName(parent, slotNames, stats, ownerName) {
  const slots = {};

  for (const slotName of slotNames || []) {
    const node = extractDescendantNamed(
      parent,
      slotName,
      stats,
      `${ownerName} ${slotName}`,
    );
    if (!node) continue;

    if (!isReusableSlotContainer(node)) {
      if (stats && stats.warnings) {
        stats.warnings.push(
          `${ownerName} ${slotName}: preserved node is not a slot-compatible frame.`,
        );
      }
      continue;
    }

    slots[slotName] = node;
  }

  return slots;
}

function reusableSlotNamed(reusableSlots, slotName) {
  if (!reusableSlots) return null;
  return reusableSlots[slotName] || null;
}

function shouldRefreshGeneratedShellSlotDefaults(ownerName, slotName, slot) {
  if (!slot || !slot.children || slot.children.length === 0) return false;

  if (ownerName === "Sidebar" && slotName === "Navigation Slot") {
    return slot.children.every(isGeneratedSidebarNavigationSlotChild);
  }

  if (ownerName === "Navbar" && slotName === "Navigation Slot") {
    return slot.children.every(isGeneratedNavbarNavigationSlotChild);
  }

  // NavigationItem's slot contents are state-dependent — the leading icon is
  // blue when Selected and grey when Disabled — so reusing them verbatim would
  // freeze every variant at the colour it was first built with. Refresh what
  // the plugin made; leave anything a designer put there alone.
  if (ownerName === "NavigationItem") {
    return slot.children.every(isGeneratedNavigationItemSlotChild);
  }

  return false;
}

function isGeneratedNavigationItemSlotChild(node) {
  if (!node) return false;
  const kind = generatedKind(node);
  if (kind === "icon-slot-instance" || kind === "missing-nested-component") {
    return true;
  }
  // The frames these slots are migrating off predate the stamps above, so match
  // the names the builder assigns as well — the same allowance Sidebar's rows
  // needed, and for the same reason.
  return /^(Trailing Icon|Badge Text|Icon)$/.test(node.name || "");
}

function isGeneratedSidebarNavigationSlotChild(node) {
  if (!node) return false;
  if (isGeneratedNavigationItemShellInstance(node)) return true;
  if (node.type === "TEXT" && node.name === "Section Text") return true;
  if (
    !/^(Item \d+ Text(?: Rail)? Row|Tool Text Row|Settings Text Row)$/.test(
      node.name || "",
    )
  ) {
    return false;
  }
  if (generatedKind(node) === "missing-nested-component") return true;

  // Sidebar was built before NavigationItem existed, so every row fell back to
  // a plain frame — and that was before the fallback learned to stamp itself
  // "missing-nested-component". Those legacy frames carry no shared plugin data
  // at all, so demanding the stamp made them permanently unrefreshable: Update
  // reused them for ever, and only Rebuild would replace them, at the cost of
  // the node ID that six Code Connect declarations pin across React, SwiftUI
  // and Compose. An unstamped frame sitting under a generated row name is ours.
  // Navbar's predicate below has the same shape but no legacy nodes to heal.
  return generatedKind(node) === "" && node.type === "FRAME";
}

function isGeneratedNavbarNavigationSlotChild(node) {
  if (!node) return false;
  if (isGeneratedNavigationItemShellInstance(node)) return true;
  return (
    generatedKind(node) === "missing-nested-component" &&
    /^Item \d+ Text Frame$/.test(node.name || "")
  );
}

function isGeneratedNavigationItemShellInstance(node) {
  return (
    isGeneratedNestedComponentInstance(node) &&
    nodeSourceComponentSet(node) === "NavigationItem"
  );
}

function generatedKind(node) {
  if (!node || !node.getSharedPluginData) return "";
  try {
    return node.getSharedPluginData(RUN_NAMESPACE, "kind") || "";
  } catch (_error) {
    return "";
  }
}

function createOrReuseShellSlot({
  component,
  height,
  itemSpacing = 12,
  layoutMode = "VERTICAL",
  ownerName,
  reusableSlot,
  slotName,
  stats,
  width,
}) {
  const hasReusableContent =
    reusableSlot && reusableSlot.children && reusableSlot.children.length > 0;
  const refreshGeneratedDefaults = shouldRefreshGeneratedShellSlotDefaults(
    ownerName,
    slotName,
    reusableSlot,
  );
  if (refreshGeneratedDefaults) {
    removeDirectChildren(reusableSlot);
    incrementStat(stats, "generatedShellSlotDefaultsRefreshed");
  }
  const reusedContent = hasReusableContent && !refreshGeneratedDefaults;

  if (reusableSlot && reusableSlot.type === "SLOT") {
    configureContentSlotNode(reusableSlot, {
      height,
      itemSpacing,
      layoutMode,
      slotKind:
        reusableSlot.getSharedPluginData &&
        reusableSlot.getSharedPluginData(RUN_NAMESPACE, "slot-kind")
          ? reusableSlot.getSharedPluginData(RUN_NAMESPACE, "slot-kind")
          : "native",
      slotName,
      width,
    });
    return { node: reusableSlot, reusedContent };
  }

  const created = createComponentContentSlot({
    component,
    height,
    itemSpacing,
    layoutMode,
    ownerName,
    slotName,
    stats,
    width,
  });

  if (reusableSlot) {
    const moved = moveDirectChildrenIntoSlot(
      reusableSlot,
      created.node,
      stats,
      `${ownerName} ${slotName}`,
    );
    if (!moved) {
      try {
        created.node.remove();
      } catch (_removeError) {
        // The freshly created slot may already have been detached by Figma.
      }
      configureContentSlotNode(reusableSlot, {
        height,
        itemSpacing,
        layoutMode,
        slotKind:
          reusableSlot.getSharedPluginData &&
          reusableSlot.getSharedPluginData(RUN_NAMESPACE, "slot-kind")
            ? reusableSlot.getSharedPluginData(RUN_NAMESPACE, "slot-kind")
            : "frame-fallback",
        slotName,
        width,
      });
      return { node: reusableSlot, reusedContent };
    }

    try {
      reusableSlot.remove();
    } catch (_removeError) {
      // The reusable frame may already be detached after moving its children.
    }
  }

  return { node: created.node, reusedContent };
}

function moveDirectChildrenIntoSlot(source, target, stats, context) {
  if (!source || !source.children || !target || !target.appendChild) {
    return true;
  }

  const children = [];
  for (const child of source.children) children.push(child);

  for (const child of children) {
    try {
      target.appendChild(child);
    } catch (error) {
      if (stats && stats.warnings) {
        stats.warnings.push(
          `Could not migrate ${context} content into native slot (${messageFor(error)}).`,
        );
      }
      return false;
    }
  }

  return true;
}

