async function syncSliderVariantChildren({
  component,
  state,
  status,
  type,
  config,
  variableByName,
  fonts,
  stats,
}) {
  const label = await syncFieldLabel({
    component,
    text: "Slider",
    tokenPrefix: "Slider",
    colorToken: config.label,
    colorFallback: config.labelFallback,
    variableByName,
    fonts,
    stats,
  });

  let root = directChildNamed(component, "Slider Control");
  if (root && root.type !== "FRAME") {
    root.remove();
    root = null;
  }

  if (!root || root.type !== "FRAME") {
    root = figma.createFrame();
    root.name = "Slider Control";
  }

  root.layoutMode = "NONE";
  root.resizeWithoutConstraints(320, 44);
  root.fills = [];
  root.strokes = [];
  root.clipsContent = false;
  root.setSharedPluginData(RUN_NAMESPACE, "kind", "slider-control");

  let track = directChildNamed(root, "Slider Track");
  if (track && track.type !== "FRAME") {
    track.remove();
    track = null;
  }

  if (!track || track.type !== "FRAME") {
    track = figma.createFrame();
    track.name = "Slider Track";
  }

  track.layoutMode = "NONE";
  track.resizeWithoutConstraints(320, 8);
  track.x = 0;
  track.y = 18;
  try {
    track.constraints = { horizontal: "STRETCH", vertical: "CENTER" };
  } catch (_error) {
    // Constraints are unavailable on some older plugin runtimes.
  }
  track.cornerRadius = KOZMOS_RADIUS.pill;
  track.fills = [
    paintFromVariable(
      config.trackFill,
      config.trackFillFallback,
      variableByName,
      stats,
    ),
  ];
  track.strokes = [
    paintFromVariable(
      config.trackStroke,
      config.trackStrokeFallback,
      variableByName,
      stats,
    ),
  ];
  track.strokeWeight = 1;
  track.clipsContent = true;
  track.setSharedPluginData(RUN_NAMESPACE, "kind", "slider-track");

  let range = directChildNamed(track, "Slider Range");
  if (range && range.type !== "RECTANGLE") {
    range.remove();
    range = null;
  }

  if (!range || range.type !== "RECTANGLE") {
    range = figma.createRectangle();
    range.name = "Slider Range";
  }

  const isRange = type === "Range";
  range.resizeWithoutConstraints(160, 8);
  range.x = isRange ? 80 : 0;
  range.y = 0;
  try {
    range.constraints = { horizontal: "SCALE", vertical: "CENTER" };
  } catch (_error) {
    // Constraints are unavailable on some older plugin runtimes.
  }
  range.cornerRadius = KOZMOS_RADIUS.pill;
  range.fills = [
    paintFromVariable(
      config.rangeFill,
      config.rangeFillFallback,
      variableByName,
      stats,
    ),
  ];
  range.strokes = [];
  range.setSharedPluginData(RUN_NAMESPACE, "kind", "slider-range");
  track.appendChild(range);
  root.appendChild(track);
  // The control is not auto layout, so FILL cannot apply here; the track's
  // STRETCH constraint carries it to the control's width.

  const thumbSpecs = isRange
    ? [
        {
          anchorName: "Slider Thumb Anchor Start",
          name: "Slider Thumb Start",
          centerX: 80,
          focus: false,
        },
        {
          anchorName: "Slider Thumb Anchor End",
          name: "Slider Thumb End",
          centerX: 240,
          focus: true,
        },
      ]
    : [
        {
          anchorName: "Slider Thumb Anchor",
          name: "Slider Thumb",
          centerX: 160,
          focus: true,
        },
      ];
  const desiredAnchorNames = thumbSpecs.map((spec) => spec.anchorName);

  for (const child of Array.from(root.children || [])) {
    if (isGeneratedSliderThumbAnchor(child)) {
      if (desiredAnchorNames.indexOf(child.name) === -1) {
        child.remove();
      }
      continue;
    }

    if (isGeneratedSliderThumb(child)) {
      // Legacy direct thumbs stretch under Figma SCALE constraints. Range-aware
      // thumbs now live inside zero-width responsive anchors so the handle size
      // stays fixed when the parent instance is resized.
      child.remove();
    }
  }

  const thumbs = [];
  for (const spec of thumbSpecs) {
    let anchor = directChildNamed(root, spec.anchorName);
    if (anchor && anchor.type !== "FRAME") {
      anchor.remove();
      anchor = null;
    }

    if (!anchor || anchor.type !== "FRAME") {
      anchor = figma.createFrame();
    }

    anchor.name = spec.anchorName;
    anchor.layoutMode = "NONE";
    anchor.resizeWithoutConstraints(SLIDER_THUMB_SIZE, 44);
    anchor.x = spec.centerX - SLIDER_THUMB_SIZE / 2;
    anchor.y = 0;
    try {
      anchor.constraints = { horizontal: "SCALE", vertical: "STRETCH" };
    } catch (_error) {
      // Constraints are unavailable on some older plugin runtimes.
    }
    anchor.fills = [];
    anchor.strokes = [];
    anchor.clipsContent = false;
    anchor.setSharedPluginData(RUN_NAMESPACE, "kind", "slider-thumb-anchor");

    for (const child of Array.from(anchor.children || [])) {
      if (isGeneratedSliderThumb(child) && child.name !== spec.name) {
        child.remove();
      }
    }

    let thumb = directChildNamed(anchor, spec.name);
    if (thumb && thumb.type !== "FRAME") {
      thumb.remove();
      thumb = null;
    }

    if (!thumb || thumb.type !== "FRAME") {
      thumb = figma.createFrame();
    }

    thumb.name = spec.name;
    thumb.layoutMode = "NONE";
    thumb.resize(SLIDER_THUMB_SIZE, SLIDER_THUMB_SIZE);
    thumb.x = 0;
    thumb.y = 12;
    try {
      thumb.constraints = { horizontal: "CENTER", vertical: "CENTER" };
    } catch (_error) {
      // Constraints are unavailable on some older plugin runtimes.
    }
    thumb.cornerRadius = KOZMOS_RADIUS.pill;
    thumb.clipsContent = false;
    thumb.fills = [
      paintFromVariable(
        config.thumbFill,
        config.thumbFillFallback,
        variableByName,
        stats,
      ),
    ];
    thumb.strokes = [
      paintFromVariable(
        config.thumbStroke,
        config.thumbStrokeFallback,
        variableByName,
        stats,
      ),
    ];
    thumb.strokeWeight = 2;
    thumb.setSharedPluginData(RUN_NAMESPACE, "kind", "slider-thumb");

    syncFocusRing(thumb, {
      enabled: state !== "Disabled" && spec.focus,
      width: SLIDER_THUMB_SIZE,
      height: SLIDER_THUMB_SIZE,
      radius: KOZMOS_RADIUS.pill,
      variableName: focusRingVariableForInputStatus(status),
      fallback: focusRingFallbackForInputStatus(status),
      variableByName,
      stats,
    });

    anchor.appendChild(thumb);
    root.appendChild(anchor);
    thumbs.push(thumb);
  }

  bindSliderGeometryVariables(
    component,
    root,
    track,
    thumbs,
    variableByName,
    stats,
  );

  component.appendChild(label);
  component.appendChild(root);
  // The control fills the Slider's width, so a resized instance stretches
  // it. FILL needs the control inside the component's auto layout, so it is
  // set after the append: before it, Figma refused it for a new control.
  setVerticalFixedFillChildSizing(root);
  normalizeInputFamilyChildSizing(component);
}

async function syncProgressVariantChildren({
  component,
  value,
  config,
  variableByName,
  stats,
}) {
  let track = directChildNamed(component, "Progress Track");
  if (track && track.type !== "FRAME") {
    track.remove();
    track = null;
  }

  if (!track || track.type !== "FRAME") {
    track = figma.createFrame();
    track.name = "Progress Track";
  }

  track.layoutMode = "NONE";
  track.resizeWithoutConstraints(320, 8);
  track.x = 0;
  track.y = 0;
  track.cornerRadius = KOZMOS_RADIUS.pill;
  track.fills = [
    paintFromVariable(
      config.trackFill,
      config.trackFillFallback,
      variableByName,
      stats,
    ),
  ];
  track.strokes = [
    paintFromVariable(
      config.trackStroke,
      config.trackStrokeFallback,
      variableByName,
      stats,
    ),
  ];
  track.strokeWeight = 1;
  track.clipsContent = true;
  track.setSharedPluginData(RUN_NAMESPACE, "kind", "progress-track");

  let range = directChildNamed(track, "Progress Range");
  if (range && range.type !== "RECTANGLE") {
    range.remove();
    range = null;
  }

  if (!range || range.type !== "RECTANGLE") {
    range = figma.createRectangle();
    range.name = "Progress Range";
  }

  const rangeWidth = Math.max(1, Math.round((Number(value) / 100) * 320));
  range.resizeWithoutConstraints(rangeWidth, 8);
  range.x = 0;
  range.y = 0;
  range.cornerRadius = KOZMOS_RADIUS.pill;
  range.visible = value !== "0";
  range.fills = [
    paintFromVariable(
      config.rangeFill,
      config.rangeFillFallback,
      variableByName,
      stats,
    ),
  ];
  range.strokes = [];
  range.setSharedPluginData(RUN_NAMESPACE, "kind", "progress-range");

  track.appendChild(range);
  component.appendChild(track);
  bindProgressGeometryVariables(component, track, range, variableByName, stats);
}

