async function createEmptyStateActionButton(stats) {
  let action = null;
  let buttonSet = null;
  const created = await createNestedComponentInstance({
    componentSetName: "Button",
    variantProperties: {
      Variant: "Outline",
      Size: "Default",
      State: "Default",
    },
    name: "Action",
    stats,
  });

  if (!created) {
    action = createMissingNestedComponentNode(
      "Action",
      "Build Button before updating EmptyState.",
      stats,
    );
  } else {
    action = created.instance;
    buttonSet = created.componentSet;
  }

  if (action.type === "INSTANCE" && buttonSet) {
    try {
      action.setProperties({
        Variant: "Outline",
        Size: "Default",
        State: "Default",
      });
    } catch (error) {
      stats.warnings.push(
        `EmptyState Action: could not set Button variant properties (${messageFor(error)}).`,
      );
    }
    setInstanceTextProperty(
      action,
      buttonSet,
      "Label Text",
      "Clear filters",
      stats,
    );
    markNestedComponentInstance(action, "Button", "empty-state-action");
  }

  if (action.setSharedPluginData) {
    action.setSharedPluginData(RUN_NAMESPACE, "role", "empty-state-action");
  }

  return action;
}

